"use strict";
const DATA = [{"id": "s01", "section": 1, "unit": 1, "unitName": "单元01 · 第01–06节", "short": "第01节 · L1–2", "title": "一般疑问句", "lessons": "Lesson 1 — Lesson 2", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>一般疑问句</strong></td>\n<td>一般疑问句的句式结构</td>\n<td>★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td><strong>一般疑问句</strong></td>\n<td>陈述句变为一般疑问句</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">一般疑问句</div><div class=\"gb\"><p class=\"source-line\">以提出问题为目的的句子叫疑问句。以 be 动词、助动词或情态动词开头，用 yes 或 no 回答的疑问句叫一般疑问句。朗读一般疑问句时，一般用升调。</p>\n<p class=\"source-line\">（1）—— Is this your handbag? 这是你的手提包吗？<br>\n—— Yes, it is. 是的，它是。<br>\n—— No, it isn't. 不，它不是。</p>\n<p class=\"source-line\">（2）—— Do you play basketball? 你打篮球吗？<br>\n—— Yes, I do. 是的，我打（篮球）。<br>\n—— No, I don't. 不，我不打（篮球）。</p>\n<p class=\"source-line\">（3）—— Can you dance? 你会跳舞吗？<br>\n—— Yes, I can. 是的，我会。<br>\n—— No, I can't. 不，我不会。</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般疑问句的句式结构</div><div class=\"gb\"><h5>1. 含 be 动词的一般疑问句</h5>\n<ul>\n<li>问句： be 动词（am / is / are） + 主语 （+其他）?</li>\n<li>肯定回答： Yes, 主语 + be 动词 (am / is / are).</li>\n<li>否定回答： No, 主语 + be 动词 (am / is / are) + not.</li>\n</ul>\n<p class=\"source-line\"><strong>注意</strong>：对一般疑问句进行回答时，肯定回答不能用缩写形式。\n—— Are you Dr. Zhang? 你是张医生吗？<br>\n—— Yes, I am. 是的，我是。<br>\n—— No, I'm not. 不，我不是。</p>\n<h5>2. 含情态动词的一般疑问句</h5>\n<ul>\n<li>问句： 情态动词 + 主语 + 动词原形 （+其他）?</li>\n<li>肯定回答： Yes, 主语 + 情态动词.</li>\n<li>否定回答： No, 主语 + 情态动词 + not.</li>\n</ul>\n<p class=\"source-line\">—— Can you speak English? 你会说英语吗？<br>\n—— Yes, I can. 是的，我会。<br>\n—— No, I can't. 不，我不会。</p>\n<h5>3. 含实义动词的一般疑问句</h5>\n<ul>\n<li>问句： 助动词 + 主语 + 动词原形 （+其他）?</li>\n<li>肯定回答： Yes, 主语 + do / does / did.</li>\n<li>否定回答： No, 主语 + don't / doesn't / didn't.</li>\n</ul>\n<p class=\"source-line\">—— Does her father work in a factory? 她父亲在工厂工作吗？<br>\n—— Yes, he does. 是的，他在工厂工作。<br>\n—— No, he doesn't. 不，他不在工厂工作。</p></div></div>\n<div class=\"g\"><div class=\"gt\">陈述句变为一般疑问句</div><div class=\"gb\"><p class=\"source-line\"><strong>口诀：</strong></p>\n<p class=\"source-line\">（1） 一找: 有情找情 (can / could / must / should)；有 be 找 be (am / is / are / was / were)；无情无 be 添助动 (do / does / did)。</p>\n<p class=\"source-line\">（2） 二变: I 变 you, we 变 you; my 变 your, our 变 your。</p>\n<p class=\"source-line\">（3） 三问号: 结尾句号变问号。</p>\n<p class=\"source-line\"><strong>注意</strong>：第一人称为主语的肯定句变为一般疑问句时，主语要变为第二人称。</p>\n<h5>1. 含 be 动词的陈述句变一般疑问句</h5>\n<ul>\n<li>I am a teacher. → Are you a teacher? （我是一名老师。你是一名老师吗？）</li>\n<li>There is some water in the glass. → Is there any water in the glass? （玻璃杯里有些水。玻璃杯里有水吗？）\n<strong>注意</strong>：含有 some 的陈述句变为一般疑问句时，要把 some 变成 any。</li>\n</ul>\n<h5>2. 含情态动词的陈述句变一般疑问句</h5>\n<ul>\n<li>Tom can play football. → Can Tom play football? （汤姆会踢足球。汤姆会踢足球吗？）</li>\n</ul>\n<h5>3. 含实义动词的陈述句变一般疑问句</h5>\n<ul>\n<li>Tom likes books. → Does Tom like books? （汤姆喜欢书。汤姆喜欢书吗？）</li>\n</ul></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">Are there <span class=\"blank-token\"><strong><em>_</em></strong>_</span> in the tree?</p>", "options": ["any birds", "some birds", "a bird"], "correct": 0, "answer": "A"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— <span class=\"blank-token\"><strong><em>_</em></strong>_</span> you write to me soon?<br>\n—— Yes, I can.</p>", "options": ["Do", "Can", "can"], "correct": 1, "answer": "B"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Does he go to school by bike?<br>\n—— <span class=\"blank-token\"><strong><em>_</em></strong>_</span></p>", "options": ["Yes, he will.", "No, he doesn't.", "No, he isn't."], "correct": 1, "answer": "B"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— I like balls. Do you like balls?<br>\n—— <span class=\"blank-token\"><strong><em>_</em></strong>_</span> I like toy bears.</p>", "options": ["Yes, I do.", "No, I don't.", "Thanks."], "correct": 1, "answer": "B"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Does your mother often cook?<br>\n—— <span class=\"blank-token\"><strong><em>_</em></strong>_</span> She can cook yummy food.</p>", "options": ["Yes, she does.", "Yes, he does.", "No, she doesn't."], "correct": 0, "answer": "A"}], "questionCount": 5, "hasAnswers": true}, {"title": "句型转换。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">Is this your handbag? （作肯定回答）</p>", "options": [], "correct": null, "answer": "Yes, it is."}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">This is my handbag. （改为一般疑问句）</p>", "options": [], "correct": null, "answer": "Is this your handbag?"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">Is that your handbag? （作否定回答）</p>", "options": [], "correct": null, "answer": "No, it isn't."}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">They love their parents. （改为一般疑问句并作肯定回答）</p>", "options": [], "correct": null, "answer": "Do they love their parents? Yes, they do."}, {"number": 10, "type": "input", "questionHtml": "<p class=\"source-line\">She can swim. （改为一般疑问句并作否定回答）</p>", "options": [], "correct": null, "answer": "Can she swim? No, she can't."}], "questionCount": 5, "hasAnswers": true}, {"title": "【真题锦囊】【昆明·五华区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ he your father?</p>", "options": ["Does", "Is", "Are", "Do"], "correct": 1, "answer": "B<br>\n解析：为一般疑问句，句中无实义动词，所以不能用 do / does 提问。主语 he （他） 为第三人称单数, be 动词应用 is, 故本题选择 B 选项。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ you like pears?</p>", "options": ["Do", "Are", "Does", "Can"], "correct": 0, "answer": "A<br>\n解析：为一般疑问句, like （喜欢）为实义动词，所以此题是含有实义动词的一般疑问句，排除 B 选项。主语 you （你; 你们）为第二人称，助动词应用 do。D 选项不符合题意。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ David and Jane like watching TV?<br>\n—— Yes, they ____.</p>", "options": ["Do; does", "Do; do", "Does; does", "Do; don't"], "correct": 1, "answer": "B"}], "questionCount": 3, "hasAnswers": true}, {"title": "【真题锦囊】【滁州·南谯区】判断题：判断下列句子是否为一般疑问句。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">This is a sweater.</p>", "options": ["正确", "错误"], "correct": 1, "answer": "B<br>\n解析：是以指示代词 this （这个） 开头的陈述句，句末为句号，与一般疑问句句型结构不符。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">Is that an egg?</p>", "options": ["正确", "错误"], "correct": 0, "answer": "A<br>\n解析：是以 be 动词开头的一般疑问句，符合一般疑问句句型结构。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">No, it isn't.</p>", "options": ["正确", "错误"], "correct": 1, "answer": "B<br>\n解析：是以 be 动词开头的一般疑问句的否定回答，以 “No” 开头, it 指代问句中提到的事物，故此句不是一般疑问句。"}], "questionCount": 3, "hasAnswers": true}, {"title": "【真题锦囊】【合肥·蜀山区】按要求改变句型。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">I am a student. （改为一般疑问句，并作否定回答）</p>", "options": [], "correct": null, "answer": "Are you a student? No, I'm not.<br>"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">She reads English in the morning. （改为一般疑问句）</p>", "options": [], "correct": null, "answer": "Does she read English in the morning?<br>"}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">He can play basketball very well. （改为一般疑问句，并作肯定和否定回答）</p>", "options": [], "correct": null, "answer": "Can he play basketball very well? Yes, he can. No, he can't.<br>"}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s02", "section": 2, "unit": 1, "unitName": "单元01 · 第01–06节", "short": "第02节 · L3–4", "title": "肯定句变否定句", "lessons": "Lesson 3 — Lesson 4", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>否定句</strong></td>\n<td>含 be 动词的否定句</td>\n<td>★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td><strong>否定句</strong></td>\n<td>含实义动词的否定句</td>\n<td>★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">否定句</div><div class=\"gb\"><p class=\"source-line\">否定句就是表示否定的句子，必须有否定词。下面主要给大家讲两种否定句：含 be 动词的否定句和含实义动词的否定句。</p>\n<h5>1. 含 be 动词 的否定句</h5>\n<p class=\"source-line\">方法： 把含 be 动词的肯定句改为否定句，就在 be 动词后面加 not。</p>\n<p class=\"source-line\">（1） 肯定句: This is my umbrella. 这是我的雨伞。\n   否定句: This is not my umbrella. 这不是我的雨伞。</p>\n<p class=\"source-line\">（2） 肯定句: I am a worker. 我是一名工人。\n   否定句: I am not a worker. 我不是一名工人。</p>\n<p class=\"source-line\">（3） 肯定句: We are good friends. 我们是好朋友。\n   否定句: We are not good friends. 我们不是好朋友。</p>\n<p class=\"source-line\">（4） 肯定句: I was ten years old last year. 我去年 10 岁。\n   否定句: I was not ten years old last year. 我去年不是 10 岁。</p>\n<p class=\"source-line\">（5） 肯定句: We were happy last Sunday. 我们上周日很开心。\n   否定句: We were not happy last Sunday. 我们上周日不开心。</p>\n<p class=\"source-line\">:::note title=\"注意\"\nbe 动词与 not 的缩写情况如下：is not = isn't, are not = aren't, was not = wasn't, were not = weren't\n注意: am not 不缩写\n:::</p>\n<h5>2. 含实义动词的否定句</h5>\n<p class=\"source-line\">方法： 把含实义动词的肯定句改为否定句，根据时态和人称的不同用 “do / does / did not + 动词原形” 构成否定。</p>\n<p class=\"source-line\">（1） 肯定句: We go to the park every morning. 我们每天早晨去公园。\n   否定句: We don't go to the park every morning. 我们每天早晨不去公园。</p>\n<p class=\"source-line\">（2） 肯定句: My mother likes flowers. 我妈妈喜欢花儿。\n   否定句: My mother doesn't like flowers. 我妈妈不喜欢花儿。</p>\n<p class=\"source-line\">（3） 肯定句: I went shopping with my mother yesterday. 我和妈妈昨天去购物了。\n   否定句: I didn't go shopping with my mother yesterday. 我和妈妈昨天没有去购物。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "判断题：判断下列句子是肯定句还是否定句。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">The taxi comes.</p>", "options": ["肯定句", "否定句"], "correct": 0, "answer": "A"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">He isn't my brother.</p>", "options": ["肯定句", "否定句"], "correct": 1, "answer": "B"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">I didn't go to the supermarket yesterday.</p>", "options": ["肯定句", "否定句"], "correct": 1, "answer": "B"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">They are my grandparents.</p>", "options": ["肯定句", "否定句"], "correct": 0, "answer": "A"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">She is my aunt.</p>", "options": ["肯定句", "否定句"], "correct": 0, "answer": "A"}], "questionCount": 5, "hasAnswers": true}, {"title": "把下列句子改成否定句。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">She is a clever girl. （改为否定句）</p>", "options": [], "correct": null, "answer": "She isn't a clever girl."}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">They are in the same class. （改为否定句）</p>", "options": [], "correct": null, "answer": "They aren't in the same class."}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">I was sad last night. （改为否定句）</p>", "options": [], "correct": null, "answer": "I wasn't sad last night."}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">Andy missed the bus two hours ago. （改为否定句）</p>", "options": [], "correct": null, "answer": "Andy didn't miss the bus two hours ago."}, {"number": 10, "type": "input", "questionHtml": "<p class=\"source-line\">My sister likes strawberries. （改为否定句）</p>", "options": [], "correct": null, "answer": "My sister doesn't like strawberries."}, {"number": 11, "type": "input", "questionHtml": "<p class=\"source-line\">I am from China. （改为否定句）</p>", "options": [], "correct": null, "answer": "I am not from China."}, {"number": 12, "type": "input", "questionHtml": "<p class=\"source-line\">This is my handbag. （改为否定句）</p>", "options": [], "correct": null, "answer": "This is not my handbag."}], "questionCount": 7, "hasAnswers": true}, {"title": "【真题锦囊】【滁州·琅琊区】根据括号内的提示将下列句子变成否定句。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">My aunt ____ (be) a worker. She is a nurse.</p>", "options": [], "correct": null, "answer": "isn't<br>"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">My sister ____ (do) go to school because she had a cold.</p>", "options": [], "correct": null, "answer": "didn't<br>"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">They ____ (be) from Shanghai.</p>", "options": [], "correct": null, "answer": "aren't<br>"}, {"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\">Andy and Mary ____ (be) classmates last year.</p>", "options": [], "correct": null, "answer": "weren't<br>"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【滁州·南谯区】把下列句子改为否定句。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">I am from China.</p>", "options": [], "correct": null, "answer": "I am not from China."}, {"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">This is my handbag.</p>", "options": [], "correct": null, "answer": "This isn't my handbag."}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">My father likes tea.</p>", "options": [], "correct": null, "answer": "My father doesn't like tea."}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">My mother went to Beijing last month.</p>", "options": [], "correct": null, "answer": "My mother didn't go to Beijing last month."}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s03", "section": 3, "unit": 1, "unitName": "单元01 · 第01–06节", "short": "第03节 · L5–6", "title": "人称代词主格和不定冠词", "lessons": "Lesson 5 — Lesson 6", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>人称代词主格和不定冠词</strong></td>\n<td>人称代词主格</td>\n<td>★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td><strong>人称代词主格和不定冠词</strong></td>\n<td>不定冠词</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">人称代词</div><div class=\"gb\"><p class=\"source-line\">人称代词是表示“你、我、他”等人称的代词。为了避免重复，用来代替前面提到过的人、动物、事物等名称的词。人称代词根据用法不同而有人称、数与格的变化。</p>\n<ul>\n<li>She is a new student. 她是一名新学生。</li>\n<li>I like swimming. 我喜欢游泳。</li>\n<li>They are happy. 他们很开心。</li>\n</ul></div></div>\n<div class=\"g\"><div class=\"gt\">人称代词主格</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>人称</th>\n<th>单数</th>\n<th>复数</th>\n<th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>第一人称</td>\n<td>I 我</td>\n<td>we 我们</td>\n<td>I am a boy. 我是一个男孩儿。<br>We are boys. 我们是男孩儿。</td>\n</tr>\n<tr>\n<td>第二人称</td>\n<td>you 你</td>\n<td>you 你们</td>\n<td>You are clever. 你很聪明。<br>You are clever. 你们很聪明。</td>\n</tr>\n<tr>\n<td>第三人称</td>\n<td>he 他<br>she 她<br>it 它</td>\n<td>they 他/她/它们</td>\n<td>He sings very well. 他唱歌很好。<br>They sing very well. 他们唱歌很好。<br>She is good at dancing. 她擅长跳舞。<br>They are good at dancing. 她们擅长跳舞。<br>It eats grapes. 它吃葡萄。<br>They eat grapes. 它们吃葡萄。</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\"><strong>注意</strong>：人称的区分：“我/我们”叫作第一人称，“你/你们”叫作第二人称，“他/她/它（们）”叫作第三人称。</p></div></div>\n<div class=\"g\"><div class=\"gt\">人称代词的用法</div><div class=\"gb\"><h5>1. 人称代词的主格在句子中作主语</h5>\n<ul>\n<li>I am studying English now. 我现在正在学习英语。</li>\n<li>She gave Zhang Peng an English book. 她给了张鹏一本英语书。</li>\n</ul>\n<h5>2. 多个并列主语的语序</h5>\n<p class=\"source-line\">如果有几个人称代词并列作主语，它们的顺序是:\n* <strong>单数</strong>—you → he / she → I\n* <strong>复数</strong>—we → you → they</p>\n<ul>\n<li>You, she and I are good friends. 我、你和她都是好朋友。</li>\n<li>We, you and they all like music. 我们、你们和他们都喜欢音乐。</li>\n<li>I and she make mistakes. 我和她犯了错误。 （若把错误责任担，第一人称最当先）</li>\n</ul>\n<p class=\"source-line\">:::tip title=\"口诀\"\n人称代词排列顺序口诀：人称代词并列现，单数并列231，复数并列123；若把错误责任担，第一人称最当先。时时注意比身份，人总要在动物前。\n:::</p>\n<p class=\"source-line\">:::note title=\"注意\"\n人称代词主格与 be 动词的缩写：I am = I'm, we are = we're, you are = you're, she is = she's, he is = he's, it is = it's, they are = they're\n:::</p></div></div>\n<div class=\"g\"><div class=\"gt\">不定冠词</div><div class=\"gb\"><p class=\"source-line\">冠词用在名词的前面，必须与名词一起出现。英语中的冠词有3个，它们是 a、an 和 the。这3个冠词又可分为不定冠词和定冠词。</p>\n<ul>\n<li>This is a car. 这是一辆小汽车。</li>\n<li>You should take an umbrella. 你应该带一把雨伞。</li>\n<li>The student goes to school on foot. 那个学生步行上学。</li>\n</ul></div></div>\n<div class=\"g\"><div class=\"gt\">不定冠词的用法</div><div class=\"gb\"><h5>1. 泛指任意一个</h5>\n<p class=\"source-line\">泛指一类事物或人中的任意一个。\n* His father is a policeman. 他父亲是一名警察。\n* Give me a book, please. 请给我一本书。</p>\n<h5>2. 代表一类</h5>\n<p class=\"source-line\">代表某一类人或事物。\n* A student should study hard. 学生应当努力学习。\n* A horse is a useful animal. 马是有用的动物。</p>\n<h5>3. 表示数量“一”</h5>\n<p class=\"source-line\">表示数量，有“一”的意思。但数的概念没有 one 强烈。\n* She has a mouth, a nose and two eyes. 她有一张嘴、一个鼻子和两只眼睛。</p>\n<h5>4. 表示单位“每”</h5>\n<p class=\"source-line\">表示单位，相当于“每”的意思。\n* We have three meals a day. 我们每日吃三餐。</p>\n<h5>5. 固定短语</h5>\n<p class=\"source-line\">用于某些固定短语中。\n* a few 一些，几个\n* a little 一点儿\n* a bit 一点儿\n* a lot of 许多，大量</p>\n<h5>6. a 和 an 的区别</h5>\n<p class=\"source-line\">发音以元音音素开头的单词前用 an。\n* an orange 一个橘子\n* an umbrella 一把雨伞\n* an old man 一位老人</p>\n<p class=\"source-line\">:::tip title=\"口诀\"\na、an 的用法区别: 用 a 用 an 这样辨，不看字母看音素，不见元音别放 n。\n:::</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "根据汉语提示用单词填空。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong><em></span> （她） is a student. <span class=\"blank-token\"><strong><em>_</em></strong></em></span> （我） am a student, too.</p>", "options": [], "correct": null, "answer": "She, I"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong><em></span> （他） looks like him. <span class=\"blank-token\"><strong><em>_</em></strong></em></span> （他们） are twins.</p>", "options": [], "correct": null, "answer": "He, They"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong><em></span>（你们）are from the UK. <span class=\"blank-token\"><strong><em>_</em></strong></em></span>（我们）are from China.</p>", "options": [], "correct": null, "answer": "You, We"}], "questionCount": 3, "hasAnswers": true}, {"title": "在横线上写出适当的人称代词。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\">Stella is a student. <span class=\"blank-token\"><strong><em>_</em></strong><em></span> isn't German. <span class=\"blank-token\"><strong><em>_</em></strong></em></span> is Spanish.</p>", "options": [], "correct": null, "answer": "She, She"}, {"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">Alice is a student. <span class=\"blank-token\"><strong><em>_</em></strong><em></span> isn't German. <span class=\"blank-token\"><strong><em>_</em></strong></em></span> is French.</p>", "options": [], "correct": null, "answer": "She, She"}, {"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">This is her car. <span class=\"blank-token\"><strong><em>_</em></strong>_</span> is a French car.</p>", "options": [], "correct": null, "answer": "It"}], "questionCount": 3, "hasAnswers": true}, {"title": "选择题：从 a、an 中选择正确答案。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">它是一辆小汽车。 It's <span class=\"blank-token\"><strong><em>_</em></strong>_</span> car.</p>", "options": ["an", "a"], "correct": 1, "answer": "B"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">它是一个苹果。 It's <span class=\"blank-token\"><strong><em>_</em></strong>_</span> apple.</p>", "options": ["a", "an"], "correct": 1, "answer": "B"}, {"number": 9, "type": "mcq", "questionHtml": "<p class=\"source-line\">她是一名英语老师。 She is <span class=\"blank-token\"><strong><em>_</em></strong>_</span> English teacher.</p>", "options": ["an", "a"], "correct": 0, "answer": "A"}, {"number": 10, "type": "mcq", "questionHtml": "<p class=\"source-line\">有一只宠物狗。 There is <span class=\"blank-token\"><strong><em>_</em></strong>_</span> pet dog.</p>", "options": ["a", "an"], "correct": 0, "answer": "A"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【佛山·南海区】用人称代词主格代替画线部分内容。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\"><u>My mother and I</u> are at home.</p>", "options": [], "correct": null, "answer": "We<br>"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\"><u>Mr. Smith</u> is a kind man.</p>", "options": [], "correct": null, "answer": "He<br>"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\"><u>Her aunt</u> is a model（模特）。</p>", "options": [], "correct": null, "answer": "She<br>"}, {"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\"><u>The car</u> is red.</p>", "options": [], "correct": null, "answer": "It<br>"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【昆明·官渡区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">William is ____ kind boy.</p>", "options": ["/", "an", "a"], "correct": 2, "answer": "C<br>\n解析：kind是发音以辅音音素开头的单词，应用不定冠词a修饰。A选项不符合语法。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">English is ____ language （语言）. It is ____ important tool.</p>", "options": ["a; an", "a; /", "a; a"], "correct": 0, "answer": "A<br>\n解析：language 是发音以辅音音素开头的单词，应用不定冠词 a 修饰。important 是发音以元音音素开头的单词，应用不定冠词 an 修饰。"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">I usually have ____ egg and bread for breakfast.</p>", "options": ["a", "an", "/"], "correct": 1, "answer": "B<br>\n解析：egg 是发音以元音音素开头的单词，应用不定冠词 an 修饰。"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Is this ____ schoolbag?<br>\n—— Yes, it is.</p>", "options": ["a", "an", "/"], "correct": 0, "answer": "A<br>\n解析：schoolbag 是发音以辅音音素开头的单词，应用不定冠词 a 修饰。"}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s04", "section": 4, "unit": 1, "unitName": "单元01 · 第01–06节", "short": "第04节 · L7–8", "title": "含 what 的特殊疑问句", "lessons": "Lesson 7 — Lesson 8", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>含 what 的特殊疑问句</strong></td>\n<td>概念</td>\n<td>★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td><strong>含 what 的特殊疑问句</strong></td>\n<td>what 的用法</td>\n<td>★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">特殊疑问句</div><div class=\"gb\"><p class=\"source-line\">通常以疑问词开头，对句中某一成分提问的句子叫特殊疑问句。\n常用的疑问词有 what、who、whose、which、when、where、how、why 等。</p>\n<p class=\"source-line\">what 用于对人名、时间、职业、日期、天气、颜色等事物提问，意为“什么”。\n—— What is your name? 你叫什么名字？<br>\n—— My name's Mary. 我的名字是玛丽。</p>\n<p class=\"source-line\">—— What nationality are you? 你是哪国人？<br>\n—— I'm British. 我是英国人。</p></div></div>\n<div class=\"g\"><div class=\"gt\">what 的用法</div><div class=\"gb\"><h5>1. 问“是什么”</h5>\n<p class=\"source-line\">—— What is this? 这是什么？<br>\n—— It's a pencil sharpener. 它是一个转笔刀。</p>\n<p class=\"source-line\">—— What are those? 那些是什么？<br>\n—— They are horses. 它们是马。</p>\n<h5>2. 问“姓名”</h5>\n<p class=\"source-line\">—— What is your name? 你叫什么名字？<br>\n—— My name is Andy. 我的名字是安迪。</p>\n<p class=\"source-line\">—— What is her name? 她叫什么名字？<br>\n—— Her name is Sue. 她的名字是休。</p>\n<h5>3. 问“天气”</h5>\n<p class=\"source-line\">—— What is the weather like today? 今天天气怎么样？<br>\n—— It's sunny. 天气晴朗。</p>\n<h5>4. 问“颜色”</h5>\n<p class=\"source-line\">—— What colour is your bag? 你的包是什么颜色的？<br>\n—— It's red. 它是红色的。</p>\n<p class=\"source-line\">—— What colour do you like? 你喜欢什么颜色？<br>\n—— I like blue. 我喜欢蓝色。</p>\n<h5>5. 问“时间”</h5>\n<p class=\"source-line\">—— What time is it? 几点了？<br>\n—— It's 8:00. 8:00 了。</p>\n<p class=\"source-line\">—— What time do you usually get up? 你通常几点钟起床？<br>\n—— I usually get up at 6:30 a.m. 我通常早上 6:30 起床。</p>\n<h5>6. 问“星期几”</h5>\n<p class=\"source-line\">—— What day is it today? 今天星期几？<br>\n—— It's Friday. 今天星期五。</p>\n<h5>7. 问“日期”</h5>\n<p class=\"source-line\">—— What date is it today? 今天几号？<br>\n—— It's March 6th. 今天是3月6日。</p>\n<h5>8. 问“正在做什么”</h5>\n<p class=\"source-line\">—— What are you doing? 你正在做什么？<br>\n—— I'm doing my homework. 我正在做作业。</p>\n<p class=\"source-line\">—— What is your mother doing? 你妈妈正在做什么？<br>\n—— She's cooking. 她正在烹饪。</p>\n<h5>9. 问“意愿”</h5>\n<p class=\"source-line\">—— What would you like to drink? 你想喝什么？<br>\n—— I'd like some juice. 我想要一些果汁。</p>\n<h5>10. 问“工作”</h5>\n<p class=\"source-line\">—— What does your mother do? 你妈妈是做什么的？<br>\n—— She's a doctor. 她是一名医生。</p>\n<h5>11. 问“尺码”</h5>\n<p class=\"source-line\">—— What size do you want? 你想要几码？<br>\n—— Size 37. 37 码。</p>\n<h5>12. 问“吃什么”</h5>\n<p class=\"source-line\">—— What would you like for breakfast? 你早餐想要什么？<br>\n—— I'd like an egg, bread and milk. 我想要一个鸡蛋、面包和牛奶。</p>\n<h5>13. 问“季节”</h5>\n<p class=\"source-line\">—— What is your favourite season? 你最喜欢的季节是什么？<br>\n—— Winter. 冬天。</p>\n<h5>14. 问“爱好”</h5>\n<p class=\"source-line\">—— What is your hobby? 你的爱好是什么？<br>\n—— I like collecting stamps. 我喜欢集邮。</p>\n<h5>15. 问“计划”</h5>\n<p class=\"source-line\">—— What are you going to do tomorrow? 你明天打算做什么？<br>\n—— I'm going to buy some books. 我打算去买些书。</p>\n<h5>16. 问“身体情况”</h5>\n<p class=\"source-line\">—— What is the matter? 怎么了？<br>\n—— I have a sore throat. 我喉咙痛。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "选择题：选择正确的特殊疑问词组。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">A: <span class=\"blank-token\"><strong><em>_</em></strong>_</span> is it today?\n   B: It's May 1st.\nE. What size</p>", "options": ["What date", "What time", "What colour", "What day"], "correct": 0, "answer": "A"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">A: <span class=\"blank-token\"><strong><em>_</em></strong>_</span> does your brother get up?\n   B: My brother gets up at 6:00.\nE. What date</p>", "options": ["What colour", "What time", "What day", "What size"], "correct": 1, "answer": "B"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">A: <span class=\"blank-token\"><strong><em>_</em></strong>_</span> is it?\n   B: It's green.\nE. What time</p>", "options": ["What day", "What size", "What colour", "What date"], "correct": 2, "answer": "C"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">A: <span class=\"blank-token\"><strong><em>_</em></strong>_</span> is it today?\n   B: Today is Monday.\nE. What date</p>", "options": ["What time", "What colour", "What size", "What day"], "correct": 3, "answer": "D"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">A: <span class=\"blank-token\"><strong><em>_</em></strong>_</span> do you want?\n   B: Size 36.\nE. What size</p>", "options": ["What time", "What colour", "What day", "What date"], "correct": null, "answer": "E"}], "questionCount": 5, "hasAnswers": true}, {"title": "根据要求完成下列各题。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">He is <u>a policeman</u>.（对画线部分提问）</p>", "options": [], "correct": null, "answer": "What is"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">I'm <u>French</u>.（对画线部分提问）</p>", "options": [], "correct": null, "answer": "What nationality"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">I like <u>red</u>.（对画线部分提问）</p>", "options": [], "correct": null, "answer": "What colour"}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">My name is <u>Robert</u>.（对画线部分提问）</p>", "options": [], "correct": null, "answer": "What is"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【佛山·高明区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ are these?<br>\n—— They're peaches.</p>", "options": ["Where", "What", "Who"], "correct": 1, "answer": "B"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ is your dress?<br>\n—— It's purple.</p>", "options": ["What time", "What day", "What colour"], "correct": 2, "answer": "C"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ is it?<br>\n—— It's 9:30.</p>", "options": ["What time", "What date", "What colour"], "correct": 0, "answer": "A"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ is it today?<br>\n—— It's July 2nd.</p>", "options": ["What time", "What date", "What day"], "correct": 1, "answer": "B"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【沈阳·大东区】对画线部分提问。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">They are <u>red</u>.</p>", "options": [], "correct": null, "answer": "What colour are they?<br>"}, {"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">I often go to bed <u>at half past eight</u>.</p>", "options": [], "correct": null, "answer": "What time do you often go to bed?<br>"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">His name is <u>Jason</u>.</p>", "options": [], "correct": null, "answer": "What is his name?<br>"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">I want <u>some milk</u>.</p>", "options": [], "correct": null, "answer": "What do you want?<br>"}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s05", "section": 5, "unit": 1, "unitName": "单元01 · 第01–06节", "short": "第05节 · L9–10", "title": "含 how 的特殊疑问句", "lessons": "Lesson 9 — Lesson 10", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>含 how 的特殊疑问句</strong></td>\n<td>概念</td>\n<td>★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td><strong>含 how 的特殊疑问句</strong></td>\n<td>how 的用法</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">含 how 的特殊疑问句</div><div class=\"gb\"><p class=\"source-line\">通常以疑问词开头，对句中某一成分提问的句子叫特殊疑问句。常用的疑问词有 what、who、whose、which、when、where、how、why 等。how 用来对感觉、方式、工具以及数量、距离、时间等进行提问。</p>\n<p class=\"source-line\">—— How are you, Binbin? 你好吗，彬彬？<br>\n—— I'm well, thanks. 我很好，谢谢。</p>\n<p class=\"source-line\">—— How much is the suit? 这套西装多少钱？<br>\n—— It's 130 yuan. 它 130 元。</p>\n<p class=\"source-line\">—— How often do you go shopping, Cindy? 你多久去购物一次，辛迪？<br>\n—— I go shopping twice a month. 我一个月去购物两次。</p></div></div>\n<div class=\"g\"><div class=\"gt\">how 的用法</div><div class=\"gb\"><h5>1. 日常问候</h5>\n<p class=\"source-line\">—— How are you? 你好吗？<br>\n—— I'm fine. 我很好。</p>\n<p class=\"source-line\">—— How is your mother? 你妈妈怎么样？<br>\n—— She's very well. 她非常好。</p>\n<h5>2. 询问“感觉”</h5>\n<p class=\"source-line\">—— How do you feel? 你感觉怎么样？<br>\n—— I feel terrible. 我感觉糟透了。</p>\n<h5>3. 询问“方式”</h5>\n<p class=\"source-line\">—— How do you go to school? 你怎样去上学？<br>\n—— I go to school by bike. 我骑自行车去上学。</p>\n<h5>4. 询问“数（量）”</h5>\n<ul>\n<li><strong>how many</strong> 多少（询问可数事物的数量）\n—— How many people are there in your family? 你家里有几口人？<br>\n—— Three. 3 口人。</li>\n<li><strong>how much</strong> 多少（询问不可数事物的量）\n—— How much water do you have? 你有多少水？<br>\n—— Half a bottle. 半瓶。</li>\n</ul>\n<h5>5. 询问“价钱”</h5>\n<ul>\n<li><strong>how much</strong> 多少钱\n—— How much are these tomatoes? 这些西红柿多少钱？<br>\n—— They're ten yuan. 它们 10 元。</li>\n</ul>\n<h5>6. 询问“年龄”</h5>\n<ul>\n<li><strong>how old</strong> 几岁\n—— How old are you? 你几岁了？<br>\n—— I'm twenty years old. 我 20 岁了。</li>\n</ul>\n<h5>7. 询问“距离”</h5>\n<ul>\n<li><strong>how far</strong> 多远\n—— How far is it from here to your school? 从这儿到你学校有多远？<br>\n—— It's five kilometres. 5 千米。</li>\n</ul>\n<h5>8. 询问“多长”或“多长时间”</h5>\n<ul>\n<li><strong>how long</strong> 多长\n—— How long is the river? 这条河多长？<br>\n—— It's about 300 metres long. 它大约 300 米长。</li>\n<li><strong>how long</strong> 多长时间\n—— How long does it take you to go to school? 去学校花费你多长时间？<br>\n—— It's about half an hour. 大约半个小时。</li>\n</ul>\n<h5>9. 询问“频率”</h5>\n<ul>\n<li><strong>how often</strong> 多久一次\n—— How often do you go to the cinema? 你多久去看一次电影？<br>\n—— I go to the cinema once a week. 我一周去看一次电影。</li>\n</ul>\n<h5>10. 询问“多久”</h5>\n<ul>\n<li><strong>how soon</strong> 多久\n—— How soon will he be back? 他多久会回来？<br>\n—— In an hour. 1 小时以后。</li>\n</ul></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "选择题：选择正确答案。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong>_</span> old is Mary?</p>", "options": ["How many", "How"], "correct": 1, "answer": "B"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong>_</span> books are there?</p>", "options": ["How many", "How much"], "correct": 0, "answer": "A"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong>_</span> children are in the park?</p>", "options": ["How many", "How much"], "correct": 0, "answer": "A"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong>_</span> is your arm?</p>", "options": ["How long", "How far"], "correct": 0, "answer": "A"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong>_</span> pens can you see?</p>", "options": ["How many", "How soon"], "correct": 0, "answer": "A"}], "questionCount": 5, "hasAnswers": true}, {"title": "按要求完成下列各题。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">你爸爸现在好吗？（翻译句子）\n   <span class=\"blank-token\"><strong><em>_</em></strong>_</span> your father now?</p>", "options": [], "correct": null, "answer": "How is"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">你今天好吗？（翻译句子）\n   <span class=\"blank-token\"><strong><em>_</em></strong>_</span> today？</p>", "options": [], "correct": null, "answer": "How are you"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">He is English. （缩写句子）</p>", "options": [], "correct": null, "answer": "He's English."}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">She is from Beijing. （缩写句子）</p>", "options": [], "correct": null, "answer": "She's from Beijing."}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【佛山·禅城区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ are you?<br>\n—— I'm fine, thank you.</p>", "options": ["How old", "What", "How"], "correct": 2, "answer": "C<br>\n解析：答语意为 “我很好，谢谢你”, 应使用 “How are you?” 提问。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ does he visit his grandparents?<br>\n—— Twice a month.</p>", "options": ["How much", "How often", "How long"], "correct": 1, "answer": "B<br>\n解析：答语意为 “一个月两次”, 应使用询问频率的 “How often...?”。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ water is there in the glass?<br>\n—— There is a little water in the glass.</p>", "options": ["How much", "How many", "How soon"], "correct": 0, "answer": "A<br>\n解析：由答语可知问句询问水的量，应用 “How much...?” 提问。"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ is your younger brother?<br>\n—— He is three years old.</p>", "options": ["How", "How old", "How tall"], "correct": 1, "answer": "B<br>\n解析：答语意为 “他 3 岁了”, 应用 “How old...?” 询问年龄。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ are those pants?<br>\n—— They're 50 dollars.</p>", "options": ["How long", "How far", "How much"], "correct": 2, "answer": "C<br>\n解析：答语意为 “它们 50 美元”, 由此可知问句对价格进行提问，询问价格可以用 “How much... ?”。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ was your holiday?<br>\n—— It was great!</p>", "options": ["How", "How long", "How soon"], "correct": 0, "answer": "A<br>\n解析：答语意为“它棒极了!”,问句应询问他人的感受，疑问词应用how。"}], "questionCount": 6, "hasAnswers": true}, {"title": "【真题锦囊】【天津·南开区】对画线部分提问。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">My aunt goes to work <u>by subway</u>.</p>", "options": [], "correct": null, "answer": "How does your aunt go to work?"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">I usually go to the library <u>four times a month</u>.</p>", "options": [], "correct": null, "answer": "How often do you usually go to the library?"}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">The schoolbag is <u>seventy yuan</u>.</p>", "options": [], "correct": null, "answer": "How much is the schoolbag?"}, {"number": 10, "type": "input", "questionHtml": "<p class=\"source-line\">There are <u>fifty</u> apples in the basket.</p>", "options": [], "correct": null, "answer": "How many apples are there in the basket?"}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s06", "section": 6, "unit": 1, "unitName": "单元01 · 第01–06节", "short": "第06节 · L11–12", "title": "含 whose 的特殊疑问句以及名词所有格", "lessons": "Lesson 11 — Lesson 12", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>含 whose 的特殊疑问句以及名词所有格</strong></td>\n<td>概念</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td><strong>含 whose 的特殊疑问句以及名词所有格</strong></td>\n<td>whose 的常见句型结构</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td><strong>含 whose 的特殊疑问句以及名词所有格</strong></td>\n<td>名词所有格</td>\n<td>★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">特殊疑问句</div><div class=\"gb\"><p class=\"source-line\">通常以疑问词开头，对句中某一成分提问的句子叫特殊疑问句。</p>\n<p class=\"source-line\">常用的疑问词有 what、who、whose、which、when、where、how、why 等。</p>\n<p class=\"source-line\">whose 用于对物品的所属提问，意思是“谁的”。</p>\n<p class=\"source-line\">—— Whose coat is this? 这是谁的外套？<br>\n—— It's my brother's. 它是我哥哥的。</p>\n<p class=\"source-line\">—— Whose glasses are those? 那副眼镜是谁的？<br>\n—— They're my father's. 它们是我爸爸的。</p></div></div>\n<div class=\"g\"><div class=\"gt\">whose 的常见句型结构</div><div class=\"gb\"><h5>1. Whose + 名词 + be 动词 + 主语？</h5>\n<p class=\"source-line\">在该句型中, whose 作定语, be 动词的变化主要取决于后面的主语。若主语为单数, be 动词用 is; 若主语为复数, be 动词用 are。另外, be 动词前面的名词的单复数形式要与主语保持一致。</p>\n<p class=\"source-line\">—— Whose schoolbag is this? 这是谁的书包？<br>\n—— It's Mary's. 它是玛丽的。</p>\n<p class=\"source-line\">—— Whose sweaters are those? 那些是谁的毛衣？<br>\n—— They're my mother's. 它们是我妈妈的。</p>\n<h5>2. Whose + be 动词 + 主语？</h5>\n<p class=\"source-line\">在该句型中，whose 作表语，be 动词的变化主要取决于后面的主语。若主语为单数，be 动词用 is；主语为复数，be 动词用 are。</p>\n<p class=\"source-line\">—— Whose is the pen? 这支钢笔是谁的？<br>\n—— It's John's. 它是约翰的。</p>\n<p class=\"source-line\">—— Whose are those books? 那些书是谁的？<br>\n—— They're Jack's. 它们是杰克的。</p></div></div>\n<div class=\"g\"><div class=\"gt\">名词所有格</div><div class=\"gb\"><h5>1. 概念</h5>\n<p class=\"source-line\">名词所有格用来表示所属关系，一般用“'s”和 of 来表示名词的所有格。“'s”用于有生命的名词，而 of 则用于无生命的名词。</p>\n<p class=\"source-line\">Lucy's room is big. 露西的房间大。\nThe windows of the house are colourful. 这幢房子的窗户是彩色的。</p>\n<h5>2. 名词所有格的构成规则</h5>\n<p class=\"source-line\">（1） 单数名词，直接在词尾加 “'s”。</p>\n<p class=\"source-line\">the girl's bag 女孩儿的包</p>\n<p class=\"source-line\">his father's glasses 他爸爸的眼镜</p>\n<p class=\"source-line\">（2） 复数名词，不以 s 结尾时，在词尾加 “'s”。</p>\n<p class=\"source-line\">Women's Day 妇女节</p>\n<p class=\"source-line\">Children's Day 儿童节</p>\n<p class=\"source-line\">（3） 复数名词，以 s 结尾时，直接在词尾加 “'”。</p>\n<p class=\"source-line\">Teachers' Day 教师节\nthe students' books 学生们的书</p>\n<p class=\"source-line\">（4）表示共有时，在最后一个名词后面加“’s”;表示各自所有时，在每个名词后加“’s”。</p>\n<p class=\"source-line\">Kitty and Lily's room 姬蒂和莉莉的房间（共有一个房间）\nKitty's and Lily's rooms 姬蒂的房间和莉莉的房间（各有一个房间）</p>\n<p class=\"source-line\">（5）表示无生命的事物的所有格时，一般加 of 构成所有格，结构为 “名词+of+所有者”。</p>\n<p class=\"source-line\">the window of the room 这个房间的窗户\nthe map of China 中国地图</p>\n<p class=\"source-line\">（6）双重所有格表示整体中的一个部分，结构为“名词+of+名词所有格/名词性物主代词”。</p>\n<p class=\"source-line\">a friend of my father's 我爸爸的一个朋友</p>\n<p class=\"source-line\">a rubber of mine 我的一块橡皮</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ is this?<br>\n—— It's Mary's.</p>", "options": ["Who", "Whose", "Which"], "correct": 1, "answer": "B"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ is Lucy now?<br>\n—— She's in the car.</p>", "options": ["Whose", "Which", "Where"], "correct": 2, "answer": "C"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ is it today?<br>\n—— It's Monday.</p>", "options": ["What day", "What time", "What date"], "correct": 0, "answer": "A"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Whose books are these?<br>\n—— ____ Mr Smith's.</p>", "options": ["It's", "They're", "He's"], "correct": 1, "answer": "B"}], "questionCount": 4, "hasAnswers": true}, {"title": "翻译句子。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">它是玛丽的手提包。(Mary, handbag)</p>", "options": [], "correct": null, "answer": "It's Mary's handbag."}, {"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">它是保罗的车。(Paul, car)</p>", "options": [], "correct": null, "answer": "It's Paul's car."}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">那是汤姆和约翰的房间。(Tom, John, room)</p>", "options": [], "correct": null, "answer": "That is Tom and John's room."}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">我妈妈的妈妈是我的外婆。(mother, grandmother)</p>", "options": [], "correct": null, "answer": "My mother's mother is my grandmother."}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【昆明·官渡区】用所给词的适当形式填空。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">—— Whose pencil-case is it?<br>\n—— It's ____ (Lucy).</p>", "options": [], "correct": null, "answer": "Lucy's<br>"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">These are ____ (teacher) books.</p>", "options": [], "correct": null, "answer": "teachers'<br>"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">These are ____ (Mike and Jim) rooms.</p>", "options": [], "correct": null, "answer": "Mike's and Jim's<br>"}, {"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\">—— ____ (Who) cups are these?<br>\n—— They're Andy's.</p>", "options": [], "correct": null, "answer": "Whose<br>"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【惠州·惠阳区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">That isn't ____ desk.</p>", "options": ["Sam", "Sams", "Sam's"], "correct": 2, "answer": "C"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">The third Sunday in June is ____ Day, right?</p>", "options": ["Father", "Father's", "Fathers"], "correct": 1, "answer": "B"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ jacket is it?<br>\n—— It's Tim's.</p>", "options": ["Whose", "Which", "What"], "correct": 0, "answer": "A"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ sister is an English teacher.</p>", "options": ["Jim's and Kate's", "Jim and Kate's", "Jim and Kate"], "correct": 1, "answer": "B"}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s07", "section": 7, "unit": 2, "unitName": "单元02 · 第07–12节", "short": "第07节 · L13–14", "title": "what colour 引导的特殊疑问句、祈使句", "lessons": "Lesson 13 — Lesson 14", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>what colour 引导的特殊疑问句、祈使句</strong></td>\n<td>what colour 引导的特殊疑问句</td>\n<td>★</td>\n<td>★</td>\n</tr>\n<tr>\n<td><strong>what colour 引导的特殊疑问句、祈使句</strong></td>\n<td>祈使句</td>\n<td>★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">what colour 引导的特殊疑问句</div><div class=\"gb\"><p class=\"source-line\">通常以疑问词开头，对句中某一成分提问的句子叫特殊疑问句。常用的疑问词有what、who、whose、which、when、where、how、why等。what colour引导的特殊疑问句通常询问某物的颜色。类似的还有how often问频率，how old问年龄，how much问价格等。</p>\n<p class=\"source-line\">—— What colour is the bag? 这个包是什么颜色的？<br>\n—— It's black. 它是黑色的。</p>\n<p class=\"source-line\">—— What colour are these crayons? 这些蜡笔是什么颜色的？<br>\n—— They're red, yellow and green. 它们是红色、黄色和绿色的。</p></div></div>\n<div class=\"g\"><div class=\"gt\">祈使句</div><div class=\"gb\"><p class=\"source-line\">表示请求、命令、劝告或建议等的句子叫祈使句。它通常省略主语(you)，根据语气的强弱，句末使用感叹号(!)或句号(.)。为表示礼貌，可在句首或句末加上“please”。朗读时通常用降调。</p>\n<p class=\"source-line\">有时为了加强语气，可在动词原形前加do。如:Do be quiet, please! 请安静!</p>\n<p class=\"source-line\">Come in, please. 请进。</p>\n<p class=\"source-line\">Be careful next time! 下次小心点儿!</p>\n<p class=\"source-line\">Let me try. 让我试试。</p></div></div>\n<div class=\"g\"><div class=\"gt\">祈使句常见的三种类型</div><div class=\"gb\"><h5>1. Be 型：Be + 其他</h5>\n<p class=\"source-line\">Be quiet! 安静!</p>\n<h5>2. Do 型：实义动词原形（+ 其他）</h5>\n<p class=\"source-line\">Shut up. 闭嘴。</p>\n<p class=\"source-line\">Don't talk. 不要说话。</p>\n<h5>3. Let 型：Let + 宾语 + 动词原形（+ 其他）</h5>\n<p class=\"source-line\">Let's go. 让我们一起去。</p>\n<p class=\"source-line\">Let him not go. 别让他去。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "补全对话", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">—— ____ is your new tie?<br>\n—— It's green.</p>", "options": [], "correct": null, "answer": "What colour"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">—— ____ colour is your new car?<br>\n—— It's black.</p>", "options": [], "correct": null, "answer": "What"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">—— What colour do you like?<br>\n—— I ____ blue.</p>", "options": [], "correct": null, "answer": "like"}], "questionCount": 3, "hasAnswers": true}, {"title": "单项选择", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ get off the bus before it stops.</p>", "options": ["Don't", "Doesn't", "Didn't", "Won't"], "correct": 0, "answer": "A"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">It's hot. ____ the window, please.</p>", "options": ["Open", "Close", "Opening", "Closing"], "correct": 0, "answer": "A"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ me your ticket, please.</p>", "options": ["Showing", "Showed", "Show", "To show"], "correct": 2, "answer": "C"}], "questionCount": 3, "hasAnswers": true}, {"title": "英汉互译", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">不要迟到。</p>", "options": [], "correct": null, "answer": "Don't be late."}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">安静！</p>", "options": [], "correct": null, "answer": "Be quiet!"}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">看我！</p>", "options": [], "correct": null, "answer": "Look at me!"}, {"number": 10, "type": "input", "questionHtml": "<p class=\"source-line\">Don't be sad.</p>", "options": [], "correct": null, "answer": "不要伤心。"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【惠州·惠城区】判断题：判断下列句子是否为祈使句。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">Take off your jacket.</p>", "options": ["正确", "错误"], "correct": 0, "answer": "A"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">Let's play games.</p>", "options": ["正确", "错误"], "correct": 0, "answer": "A"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">How are you?</p>", "options": ["正确", "错误"], "correct": 1, "answer": "B"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">Don't play football in the classroom.</p>", "options": ["正确", "错误"], "correct": 0, "answer": "A"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【昆明·五华区】选择题：选择正确的单词完成句子。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong>_</span> careful. The bus is coming.</p>", "options": ["Is", "Be"], "correct": 1, "answer": "B<br>\n解析：此句是 Be 型祈使句。位于句首时，be 使用原形并大写首字母。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">Let's ____ to school together.</p>", "options": ["go", "goes"], "correct": 0, "answer": "A<br>\n解析：此句是 Let 型祈使句，Let's 后接动词原形。"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ on and join us!</p>", "options": ["Comes", "Come"], "correct": 1, "answer": "B<br>\n解析：此句是 Do 型祈使句，实义动词使用原形。"}], "questionCount": 3, "hasAnswers": true}, {"title": "【真题锦囊】【昆明·五华区】将下列句子改为祈使句", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">You can sit on this chair.</p>", "options": [], "correct": null, "answer": "Sit on this chair."}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">You must sweep the floor carefully.</p>", "options": [], "correct": null, "answer": "Sweep the floor carefully."}, {"number": 10, "type": "input", "questionHtml": "<p class=\"source-line\">You should stay at home today.</p>", "options": [], "correct": null, "answer": "Stay at home today."}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s08", "section": 8, "unit": 2, "unitName": "单元02 · 第07–12节", "short": "第08节 · L15–16", "title": "可数名词单复数变化规则（一）", "lessons": "Lesson 15 — Lesson 16", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>可数名词单复数变化规则（一）</strong></td>\n<td>可数名词的概念</td>\n<td>★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td><strong>可数名词单复数变化规则（一）</strong></td>\n<td>名词单数变复数的规则变化</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">可数名词的概念</div><div class=\"gb\"><p class=\"source-line\">一般可以用数目来计算的名词叫可数名词，一般无法用数目来计算的名词叫不可数名词。在英语语法中，可数名词有单数和复数两种形式。表示一个人或事物时用单数，表示一个以上的人或事物时用复数。</p>\n<p class=\"source-line\">I want to drink some water. 我想喝些水。</p>\n<p class=\"source-line\">I have two good friends.</p>\n<p class=\"source-line\">我有2个好朋友。</p>\n<p class=\"source-line\">There are three suitcases. 有 3 个手提箱。</p></div></div>\n<div class=\"g\"><div class=\"gt\">名词单数变复数的规则变化</div><div class=\"gb\"><h5>1. 一般情况下，在词尾加 s</h5>\n<p class=\"source-line\">book → books 书 room → rooms 房间 pear → pears 梨</p>\n<p class=\"source-line\">house → houses 房子 day → days 天 song → songs 歌曲</p>\n<h5>2. 以 s、x、sh、ch 结尾的名词，在词尾加 es。如：</h5>\n<p class=\"source-line\">bus → buses 公共汽车 box → boxes 箱子</p>\n<p class=\"source-line\">watch → watches 手表 dish → dishes 盘子</p>\n<h5>3. 以“辅音字母 + y”结尾的名词，先变 y 为 i，再加 es</h5>\n<p class=\"source-line\">city → cities 城市 body → bodies 身体</p>\n<p class=\"source-line\">story → stories 故事</p>\n<p class=\"source-line\">factory → factories 工厂</p>\n<h5>4. 以 o 结尾的名词</h5>\n<p class=\"source-line\">多数以 o 结尾的名词直接加 s，部分常用词加 es。</p>\n<p class=\"source-line\">直接加 s：piano → pianos 钢琴</p>\n<p class=\"source-line\">radio → radios 收音机</p>\n<p class=\"source-line\">加 es：potato → potatoes 土豆</p>\n<p class=\"source-line\">:::tip title=\"口诀\"\nhero、potato、tomato、mango 等常用词的复数形式加 es。\n:::</p>\n<p class=\"source-line\">hero → heroes 英雄</p>\n<h5>5. 以 f 或 fe 结尾的名词</h5>\n<p class=\"source-line\">部分以 f 或 fe 结尾的名词，先将 f 或 fe 变为 v，再加 es。</p>\n<p class=\"source-line\">half → halves 一半</p>\n<p class=\"source-line\">leaf → leaves 树叶</p>\n<p class=\"source-line\">knife → knives 刀</p>\n<p class=\"source-line\">wife → wives 妻子</p>\n<p class=\"source-line\">:::note title=\"注意\"\n并非所有以 f 或 fe 结尾的名词都变为 ves，例如 roof → roofs、chief → chiefs。\n:::</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "把下列可数名词由单数变为复数", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">book</p>", "options": [], "correct": null, "answer": "books"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">suit</p>", "options": [], "correct": null, "answer": "suits"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">factory</p>", "options": [], "correct": null, "answer": "factories"}, {"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\">tie</p>", "options": [], "correct": null, "answer": "ties"}, {"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">passport</p>", "options": [], "correct": null, "answer": "passports"}, {"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">box</p>", "options": [], "correct": null, "answer": "boxes"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">umbrella</p>", "options": [], "correct": null, "answer": "umbrellas"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">dog ____</p>", "options": [], "correct": null, "answer": "dogs"}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">baby</p>", "options": [], "correct": null, "answer": "babies"}, {"number": 10, "type": "input", "questionHtml": "<p class=\"source-line\">shelf</p>", "options": [], "correct": null, "answer": "shelves"}, {"number": 11, "type": "input", "questionHtml": "<p class=\"source-line\">city</p>", "options": [], "correct": null, "answer": "cities"}, {"number": 12, "type": "input", "questionHtml": "<p class=\"source-line\">boy</p>", "options": [], "correct": null, "answer": "boys"}, {"number": 13, "type": "input", "questionHtml": "<p class=\"source-line\">fox</p>", "options": [], "correct": null, "answer": "foxes"}, {"number": 14, "type": "input", "questionHtml": "<p class=\"source-line\">dish</p>", "options": [], "correct": null, "answer": "dishes"}, {"number": 15, "type": "input", "questionHtml": "<p class=\"source-line\">sandwich</p>", "options": [], "correct": null, "answer": "sandwiches"}], "questionCount": 15, "hasAnswers": true}, {"title": "用所给词的正确形式填空", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 16, "type": "input", "questionHtml": "<p class=\"source-line\">There are nine ____ (apple) on the desk.</p>", "options": [], "correct": null, "answer": "apples"}, {"number": 17, "type": "input", "questionHtml": "<p class=\"source-line\">The boy has two ____ (watch).</p>", "options": [], "correct": null, "answer": "watches"}, {"number": 18, "type": "input", "questionHtml": "<p class=\"source-line\">A cat has four ____ (foot).</p>", "options": [], "correct": null, "answer": "feet"}, {"number": 19, "type": "input", "questionHtml": "<p class=\"source-line\">There are 25 ____ (girl) and 15 ____ (boy) in the group.</p>", "options": [], "correct": null, "answer": "girls, boys"}, {"number": 20, "type": "input", "questionHtml": "<p class=\"source-line\">I have a lot of ____ (tomato) here.</p>", "options": [], "correct": null, "answer": "tomatoes"}, {"number": 21, "type": "input", "questionHtml": "<p class=\"source-line\">Look, a ____ (kite) is in the tree.</p>", "options": [], "correct": null, "answer": "kite"}, {"number": 22, "type": "input", "questionHtml": "<p class=\"source-line\">There are many ____ (bus) on the road.</p>", "options": [], "correct": null, "answer": "buses"}, {"number": 23, "type": "input", "questionHtml": "<p class=\"source-line\">Three ____ (photo) are on the table.</p>", "options": [], "correct": null, "answer": "photos"}, {"number": 24, "type": "input", "questionHtml": "<p class=\"source-line\">The ____ (plane) are in the sky.</p>", "options": [], "correct": null, "answer": "planes"}, {"number": 25, "type": "input", "questionHtml": "<p class=\"source-line\">My father likes to eat ____ (potato).</p>", "options": [], "correct": null, "answer": "potatoes"}], "questionCount": 10, "hasAnswers": true}, {"title": "【真题锦囊】【昆明·西山区】单项选择", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">I am 12 ____ old.</p>", "options": ["years", "year", "yeares", "/"], "correct": 0, "answer": "A<br>\n解析：当年龄大于 1 时, year （岁） 要变为复数形式，即在 year 后面加 “s”, 变为 years。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">Look at these ____.</p>", "options": ["pear", "pears", "peares", "a pear"], "correct": 1, "answer": "B<br>\n解析：these （这些） 是复数, pear （梨） 应变为复数形式，即在词尾加 “s”, 变为 pears。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">I have two long ____ and two big ____.</p>", "options": ["feet; leg", "legs; foot", "legs; feet", "leg; foot"], "correct": 2, "answer": "C<br>\n解析：two（两个）后接复数名词。leg（腿）变复数形式在词尾加“s”, 变为 legs。foot （脚）的复数形式为 feet。"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">Look! ____ are eating our sandwiches.</p>", "options": ["The duck", "This duck", "These ducks", "A duck"], "correct": 2, "answer": "C<br>\n解析：由 be 动词 are 可知主语为复数，只有 C 选项符合语法。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">Here are some ____ in these ____.</p>", "options": ["knifes; pencil boxes", "knife; pencils boxes", "knives; pencils boxes", "knives; pencil boxes"], "correct": 3, "answer": "D<br>\n解析：some （一些） 和 these （这些） 均表示复数。knife （刀） 的复数形式为 knives, pencil box （铅笔盒） 的复数形式为 pencil boxes, 故此题选择 D 选项。"}], "questionCount": 5, "hasAnswers": true}, {"title": "【真题锦囊】【深圳·福田区】填入所给名词的正确形式", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">I have two ____ (knife).</p>", "options": [], "correct": null, "answer": "knives<br>"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">A few ____ (boy) are drawing on the wall.</p>", "options": [], "correct": null, "answer": "boys<br>"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">Please take those ____ (photo) for me.</p>", "options": [], "correct": null, "answer": "photos<br>"}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">Do you want some ____ (milk)?</p>", "options": [], "correct": null, "answer": "milk<br>"}, {"number": 10, "type": "input", "questionHtml": "<p class=\"source-line\">I like these red ____ (tomato).</p>", "options": [], "correct": null, "answer": "tomatoes<br>"}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s09", "section": 9, "unit": 2, "unitName": "单元02 · 第07–12节", "short": "第09节 · L17–18", "title": "可数名词单复数变化规则（二）", "lessons": "Lesson 17 — Lesson 18", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>可数名词单复数变化规则（二）</strong></td>\n<td>概念</td>\n<td>★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td><strong>可数名词单复数变化规则（二）</strong></td>\n<td>名词单数变复数的不规则变化</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">可数名词</div><div class=\"gb\"><p class=\"source-line\">一般可以用数目来计算的名词叫可数名词，一般无法用数目来计算的名词叫不可数名词。在英语语法中，可数名词有单数和复数两种形式。表示一个人或事物时用单数，表示一个以上的人或事物时用复数。</p>\n<p class=\"source-line\">The fish swim in the river.\n鱼在河里游泳。</p>\n<p class=\"source-line\">The children are playing on the playground. 孩子们正在操场上玩儿。</p>\n<p class=\"source-line\">There are 15 women teachers in our school.\n我们学校有 15 名女教师。</p></div></div>\n<div class=\"g\"><div class=\"gt\">名词单数变复数的不规则变化</div><div class=\"gb\"><h5>1. 元音字母发生变化。如：</h5>\n<p class=\"source-line\">man → men 男人</p>\n<p class=\"source-line\">woman → women 女人</p>\n<p class=\"source-line\">goose → geese 鹅</p>\n<p class=\"source-line\">foot → feet 脚</p>\n<p class=\"source-line\">tooth → teeth 牙齿</p>\n<p class=\"source-line\">以 man 或 woman 为核心词的复合名词变复数时，通常将 man 变为 men、woman 变为 women；German、human 等并不适用此规则。如：an Englishman → two Englishmen, a woman teacher → two women teachers。</p>\n<h5>2. 词尾发生变化。如：</h5>\n<p class=\"source-line\">child → children 孩子</p>\n<p class=\"source-line\">ox → oxen 公牛</p>\n<h5>3. 单复数同形。如：</h5>\n<p class=\"source-line\">Chinese → Chinese 中国人</p>\n<p class=\"source-line\">Japanese → Japanese 日本人</p>\n<p class=\"source-line\">deer → deer 鹿</p>\n<p class=\"source-line\">fish → fish 鱼</p>\n<p class=\"source-line\">sheep → sheep 绵羊</p>\n<p class=\"source-line\">:::tip title=\"口诀\"\n男人女人 a 变 e，鹅足牙 oo 变 ee；小孩儿加上 ren，老鼠变成 ice；中日小鹿鱼绵羊，单数复数一个样。\n:::</p>\n<p class=\"source-line\">:::tip title=\"口诀\"\n中（Chinese）日（Japanese）不变，英（Englishman → Englishmen）法（Frenchman → Frenchmen）变，其余通常在词尾加 s。\n:::</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "把下列可数名词由单数变为复数", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">mechanic ____</p>", "options": [], "correct": null, "answer": "mechanics"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">teacher ____</p>", "options": [], "correct": null, "answer": "teachers"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">customs officer ____</p>", "options": [], "correct": null, "answer": "customs officers"}, {"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\">taxi driver ____</p>", "options": [], "correct": null, "answer": "taxi drivers"}, {"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">housewife ____</p>", "options": [], "correct": null, "answer": "housewives"}, {"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">policeman ____</p>", "options": [], "correct": null, "answer": "policemen"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">girlfriend ____</p>", "options": [], "correct": null, "answer": "girlfriends"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">path ____</p>", "options": [], "correct": null, "answer": "paths"}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">mouse ____</p>", "options": [], "correct": null, "answer": "mice"}, {"number": 10, "type": "input", "questionHtml": "<p class=\"source-line\">foot ____</p>", "options": [], "correct": null, "answer": "feet"}], "questionCount": 10, "hasAnswers": true}, {"title": "单项选择", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 11, "type": "mcq", "questionHtml": "<p class=\"source-line\">There are ____ and ____.</p>", "options": ["sheep; dogs", "sheep; dog", "sheeps; dog"], "correct": 0, "answer": "A"}, {"number": 12, "type": "mcq", "questionHtml": "<p class=\"source-line\">There are some ____ and ____ in the basket.</p>", "options": ["tomatoes; potatos", "tomatos; potatos", "tomatoes; potatoes"], "correct": 2, "answer": "C"}, {"number": 13, "type": "mcq", "questionHtml": "<p class=\"source-line\">Both my father and my brother are ____.</p>", "options": ["policemen", "policewomen", "police officers"], "correct": 0, "answer": "A"}, {"number": 14, "type": "mcq", "questionHtml": "<p class=\"source-line\">These boys want to be ____ in the future.</p>", "options": ["man doctors", "men doctors", "man's doctors"], "correct": 1, "answer": "B"}], "questionCount": 4, "hasAnswers": true}, {"title": "用所给词的适当形式填空", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 15, "type": "input", "questionHtml": "<p class=\"source-line\">Six ____ (sheep) are in the field.</p>", "options": [], "correct": null, "answer": "sheep"}, {"number": 16, "type": "input", "questionHtml": "<p class=\"source-line\">30 ____ (day) is a long time for me.</p>", "options": [], "correct": null, "answer": "days"}, {"number": 17, "type": "input", "questionHtml": "<p class=\"source-line\">Some ____ (mouse) are in the hole.</p>", "options": [], "correct": null, "answer": "mice"}, {"number": 18, "type": "input", "questionHtml": "<p class=\"source-line\">Chinese ____ (people) like to eat noodles.</p>", "options": [], "correct": null, "answer": "people"}, {"number": 19, "type": "input", "questionHtml": "<p class=\"source-line\">I have two ____ (pencil-box).</p>", "options": [], "correct": null, "answer": "pencil-boxes"}, {"number": 20, "type": "input", "questionHtml": "<p class=\"source-line\">There are some ____ (child) in the garden.</p>", "options": [], "correct": null, "answer": "children"}], "questionCount": 6, "hasAnswers": true}, {"title": "【真题锦囊】【惠州·惠城区】写出下列单词的复数形式", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">tooth ____</p>", "options": [], "correct": null, "answer": "teeth"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">man ____</p>", "options": [], "correct": null, "answer": "men"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">piano ____</p>", "options": [], "correct": null, "answer": "pianos"}, {"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\">sheep ____</p>", "options": [], "correct": null, "answer": "sheep"}, {"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">child ____</p>", "options": [], "correct": null, "answer": "children"}], "questionCount": 5, "hasAnswers": true}, {"title": "【真题锦囊】【蚌埠·禹会区】单项选择", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">I have two ____ and three sharp ____.</p>", "options": ["watches; knives", "watchs; knives", "watches; knifes"], "correct": 0, "answer": "A<br>\n解析：two （二） 和 three （三） 后接可数名词的复数形式。watch 的复数形式为 watches, knife 的复数形式为 knives。"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">There are ten ____ in our class.</p>", "options": ["Germen", "Germans", "German"], "correct": 1, "answer": "B<br>\n解析：ten （十） 后面的名词要用可数名词的复数形式。German 的复数形式是 Germans。"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">Can you see nine ____ in the picture?</p>", "options": ["fish", "bookes", "horse"], "correct": 0, "answer": "A<br>\n解析：nine（九）后接可数名词的复数形式。B 选项 bookes 写法错误。C 选项 horse （马）为单数名词。A 选项 fish（鱼）单复数同形。故本题选择 A 选项。"}, {"number": 9, "type": "mcq", "questionHtml": "<p class=\"source-line\">The ____ begin to eat the green ____ of young trees.</p>", "options": ["deer; leaves", "deer; leafs", "deers; leaf"], "correct": 0, "answer": "A<br>\n解析：句意为 “鹿开始吃小树的绿叶”, 由 begin （开始） 可知主语应为可数名词复数, deer （鹿） 的复数形式为 deer, leaf （叶子） 的复数形式为 leaves。故本题选择 A 选项。"}, {"number": 10, "type": "mcq", "questionHtml": "<p class=\"source-line\">She must look after those ____.</p>", "options": ["dog", "geese", "animal"], "correct": 1, "answer": "B<br>\n解析：those （那些） 后接复数名词, A、C 选项均为单数名词。B 选项 geese 为 goose （鹅） 的复数形式。故此题选择 B 选项。"}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s10", "section": 10, "unit": 2, "unitName": "单元02 · 第07–12节", "short": "第10节 · L19–20", "title": "There be 句型", "lessons": "Lesson 19 — Lesson 20", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>There be 句型</strong></td>\n<td>There be 句型的概念</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td><strong>There be 句型</strong></td>\n<td>There be 句型的形式</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td><strong>There be 句型</strong></td>\n<td>There be 句型的就近原则</td>\n<td>★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">There be 句型的概念</div><div class=\"gb\"><p class=\"source-line\">在英语中, There be 句型表示 “某地存在某人或某物”。there 是无意义的引导词，在句中不充当任何成分。be 后面的名词是主语，两者在数上必须一致。句子最后面是地点或时间状语。</p>\n<p class=\"source-line\">There is a book on the desk.</p>\n<p class=\"source-line\">书桌上有一本书。</p>\n<p class=\"source-line\">There are some candies in the box.\n箱子里有一些糖果。</p></div></div>\n<div class=\"g\"><div class=\"gt\">There be 句型的形式</div><div class=\"gb\"><h5>1. 肯定句：There be + 主语 + 地点 / 时间状语</h5>\n<p class=\"source-line\">There is a new bike in front of the house.</p>\n<p class=\"source-line\">房子前面有一辆新自行车。</p>\n<p class=\"source-line\">There are twelve months in a year. 一年有 12 个月。</p>\n<h5>2. 否定句：There be + not any + 主语 + 地点 / 时间状语，或 There be + no + 主语 + 地点 / 时间状语</h5>\n<p class=\"source-line\">There are no mangoes on the desk. = There aren't any mangoes on the desk.\n书桌上没有芒果。</p>\n<p class=\"source-line\">There is no ink in the bottle. 瓶子里没有墨水。</p>\n<h5>3. 疑问句</h5>\n<p class=\"source-line\">（1）一般疑问句：只需将 be 提到 there 前。</p>\n<p class=\"source-line\">—— Is there a river in the forest? 森林里有条河吗？<br>\n—— Yes, there is. 是的，有。</p>\n<p class=\"source-line\">—— Are there any candies in your bag? 你包里有糖果吗？<br>\n—— No, there aren't. 不，没有。</p>\n<p class=\"source-line\">（2）特殊疑问句：常由 how many 或 how much 引导。</p>\n<p class=\"source-line\">—— How many students are there in your class? 你们班有多少名学生？<br>\n—— There are forty students in our class. 我们班有 40 名学生。</p>\n<p class=\"source-line\">—— How much money is there in your bag? 你包里有多少钱？<br>\n—— There's no money in my bag. 我包里没有钱。</p>\n<p class=\"source-line\">:::tip title=\"口诀\"\n“有”字放前面，有“啥”放中间，地点（时间）放后面。单数用 is（was），复数用 are（were），注意 be 的变化。\n:::</p></div></div>\n<div class=\"g\"><div class=\"gt\">There be 句型的就近原则</div><div class=\"gb\"><p class=\"source-line\">当 There be 句型中有两个或两个以上的主语时, be 的形式由离其最近的主语的单复数形式决定。</p>\n<p class=\"source-line\">There is a cock and five hens near the house.</p>\n<p class=\"source-line\">房子附近有1只公鸡和5只母鸡。</p>\n<p class=\"source-line\">There are five hens and a cock near the house.</p>\n<p class=\"source-line\">房子附近有 5 只母鸡和 1 只公鸡。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "选择题：选择恰当的 be 动词。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ an eraser in the pencil case.</p>", "options": ["are", "is"], "correct": 1, "answer": "B"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ bananas on the table.</p>", "options": ["is", "are"], "correct": 1, "answer": "B"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ a book and three pencils on the desk.</p>", "options": ["are", "is"], "correct": 1, "answer": "B"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ some pears and a banana in the fridge.</p>", "options": ["is", "are"], "correct": 1, "answer": "B"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ some apples in the basket.</p>", "options": ["are", "is"], "correct": 0, "answer": "A"}], "questionCount": 5, "hasAnswers": true}, {"title": "按要求完成下列各题", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">There are some pears on the tree. （变为一般疑问句，并作肯定和否定回答）</p>", "options": [], "correct": null, "answer": "Are there any pears on the tree? Yes, there are. No, there aren't."}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">There is some orange juice in the glass. （变为否定句）</p>", "options": [], "correct": null, "answer": "There isn't any orange juice in the glass."}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">There is a swing on the playground. （变为一般疑问句，并作肯定和否定回答）</p>", "options": [], "correct": null, "answer": "Is there a swing on the playground? Yes, there is. No, there isn't."}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">There are <u>forty</u> pupils in Miss Wang's class.（对画线部分提问）</p>", "options": [], "correct": null, "answer": "How many pupils are there in Miss Wang's class?"}], "questionCount": 4, "hasAnswers": true}, {"title": "单项选择", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 10, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ many trees here two years ago.</p>", "options": ["was", "is", "are", "were"], "correct": 3, "answer": "D"}, {"number": 11, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ some interesting books in the school library now.</p>", "options": ["is", "are", "was", "were"], "correct": 1, "answer": "B"}, {"number": 12, "type": "mcq", "questionHtml": "<p class=\"source-line\">How many days ____ in a week?</p>", "options": ["are there", "is there", "have", "were there"], "correct": 0, "answer": "A"}, {"number": 13, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ some juice in the bottle.</p>", "options": ["be", "are", "have", "is"], "correct": 3, "answer": "D"}, {"number": 14, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ any trees near the house.</p>", "options": ["are", "aren't", "is", "isn't"], "correct": 1, "answer": "B"}], "questionCount": 5, "hasAnswers": true}, {"title": "【真题锦囊】【合肥·包河区】选择题：选择括号内的正确单词。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">There <span class=\"blank-token\"><strong><em>_</em></strong>_</span> twelve months in a year.</p>", "options": ["are", "is"], "correct": 0, "answer": "A"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">There <span class=\"blank-token\"><strong><em>_</em></strong>_</span> some milk in the bottle.</p>", "options": ["is", "isn't"], "correct": 0, "answer": "A"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">There are some <span class=\"blank-token\"><strong><em>_</em></strong>_</span> in the garden.</p>", "options": ["flower", "flowers"], "correct": 1, "answer": "B"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">There <span class=\"blank-token\"><strong><em>_</em></strong>_</span> any books on the shelf.</p>", "options": ["are", "aren't"], "correct": 1, "answer": "B"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【昆明·五华区】单项选择", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ an apple and two oranges on the table.</p>", "options": ["is", "are", "were"], "correct": 0, "answer": "A<br>\n解析：an apple （一个苹果） 为单数形式，故 be 用 is。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ seven days in a week.</p>", "options": ["is", "are", "was"], "correct": 1, "answer": "B<br>\n解析：seven days （7 天） 为复数形式，故 be 用 are。"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">How many desks ____ in your classroom?</p>", "options": ["there are", "is there", "are there"], "correct": 2, "answer": "C<br>\n解析：此题是由 how many 引导的特殊疑问句, desks 为可数名词复数，故选 are there。"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ is there on the table?</p>", "options": ["How many apples", "How much bread", "How much breads"], "correct": 1, "answer": "B<br>\n解析：由 is there 可知此句主语应是不可数名词, how much （多少）询问不可数名词的量, bread（面包）为不可数名词，无复数形式，故此题选择 B 选项。"}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s11", "section": 11, "unit": 2, "unitName": "单元02 · 第07–12节", "short": "第11节 · L21–22", "title": "人称代词宾格", "lessons": "Lesson 21 — Lesson 22", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>人称代词宾格</strong></td>\n<td>人称代词宾格</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">人称代词</div><div class=\"gb\"><p class=\"source-line\">人称代词是表示“你、我、他”等人称的代词，是为了避免重复，用来代替前面提到过的人、动物、事物等名称的词。人称代词根据用法不同而有人称、数与格的变化。</p>\n<p class=\"source-line\">He is a boy.\n他是一个男孩儿。</p>\n<p class=\"source-line\">Give me an envelope, please. 请给我一个信封。</p></div></div>\n<div class=\"g\"><div class=\"gt\">人称代词的主格、宾格</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>人称</th>\n<th>数</th>\n<th>主格</th>\n<th>宾格</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>第一人称</td>\n<td>单数</td>\n<td>I</td>\n<td>me</td>\n</tr>\n<tr>\n<td>第一人称</td>\n<td>复数</td>\n<td>we</td>\n<td>us</td>\n</tr>\n<tr>\n<td>第二人称</td>\n<td>单数</td>\n<td>you</td>\n<td>you</td>\n</tr>\n<tr>\n<td>第二人称</td>\n<td>复数</td>\n<td>you</td>\n<td>you</td>\n</tr>\n<tr>\n<td>第三人称</td>\n<td>单数</td>\n<td>he / she / it</td>\n<td>him / her / it</td>\n</tr>\n<tr>\n<td>第三人称</td>\n<td>复数</td>\n<td>they</td>\n<td>them</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">:::tip title=\"口诀\"\n我用 me，你用 you；男他 him，女她 her；动植物它用 it。我们用 us，你们用 you，他们、她们、它们全用 them。\n:::</p></div></div>\n<div class=\"g\"><div class=\"gt\">人称代词主格的用法</div><div class=\"gb\"><h5>1. 用于句子开头作主语。</h5>\n<p class=\"source-line\">He is a doctor. 他是一名医生。</p></div></div>\n<div class=\"g\"><div class=\"gt\">人称代词宾格的用法</div><div class=\"gb\"><h5>1. 在 be 动词后作表语。</h5>\n<p class=\"source-line\">—— Who is it? 是谁？<br>\n—— It's me. 是我。</p>\n<h5>2. 在动词和介词后作宾语。</h5>\n<p class=\"source-line\">The ducklings follow him. 这些小鸭子跟着他。</p>\n<p class=\"source-line\">He runs after them. 他追赶它们。</p>\n<p class=\"source-line\">人称代词宾格巧用：代词宾格不动脑，跟着动词介词跑。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "选择题：选择正确的人称代词。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ am wearing a white coat.</p>", "options": ["Me", "I"], "correct": 1, "answer": "B"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">These green shoes are nice. I like ____.</p>", "options": ["they", "them"], "correct": 1, "answer": "B"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">Look! There are some rabbits. Oh! ____ are so cute.</p>", "options": ["Them", "They"], "correct": 1, "answer": "B"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">Ann is a good student. ____ is good at English. Her teacher likes her.</p>", "options": ["She", "Her"], "correct": 0, "answer": "A"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Look! Some boys are playing football. Who is the boy in the green T-shirt?<br>\n—— ____ is Robert. He is my good friend.</p>", "options": ["Him", "He"], "correct": 1, "answer": "B"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">Give ____ a toy, please.</p>", "options": ["he", "him"], "correct": 1, "answer": "B"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">Let ____ help you.</p>", "options": ["me", "I"], "correct": 0, "answer": "A"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\"><span class=\"blank-token\"><strong><em>_</em></strong>_</span> can go there by bus.</p>", "options": ["We", "Us"], "correct": 0, "answer": "A"}], "questionCount": 8, "hasAnswers": true}, {"title": "单项选择", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 9, "type": "mcq", "questionHtml": "<p class=\"source-line\">Look at ____.</p>", "options": ["he", "him", "his"], "correct": 1, "answer": "B"}, {"number": 10, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ is short.</p>", "options": ["She", "Her", "me"], "correct": 0, "answer": "A"}, {"number": 11, "type": "mcq", "questionHtml": "<p class=\"source-line\">Let ____ help you.</p>", "options": ["I", "We", "me"], "correct": 2, "answer": "C"}, {"number": 12, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ are from China.</p>", "options": ["They", "Them", "Him"], "correct": 0, "answer": "A"}, {"number": 13, "type": "mcq", "questionHtml": "<p class=\"source-line\">Give ____ some bananas.</p>", "options": ["they", "we", "them"], "correct": 2, "answer": "C"}, {"number": 14, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ are a good teacher.</p>", "options": ["Them", "Us", "You"], "correct": 2, "answer": "C"}, {"number": 15, "type": "mcq", "questionHtml": "<p class=\"source-line\">I don't know ____.</p>", "options": ["she", "he", "her"], "correct": 2, "answer": "C"}, {"number": 16, "type": "mcq", "questionHtml": "<p class=\"source-line\">Come with ____.</p>", "options": ["I", "me", "they"], "correct": 1, "answer": "B"}], "questionCount": 8, "hasAnswers": true}, {"title": "【真题锦囊】【佛山·南海区】单项选择", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">Can you find ____?</p>", "options": ["they", "them", "he"], "correct": 1, "answer": "B<br>\n解析：find（找到）为实义动词，后接人称代词宾格。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ is a tall boy.</p>", "options": ["She", "He", "They"], "correct": 1, "answer": "B"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">Let ____ clean the floor.</p>", "options": ["me", "I", "we"], "correct": 0, "answer": "A"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">I can't find my books. Where ____?</p>", "options": ["is it", "are they", "are you"], "correct": 1, "answer": "B<br>\n解析：第一句的句意为 “我找不到我的书了”, 其中 books （书） 为复数形式，故第二句中的 be 动词用 are, 人称代词用 they。故本题选择 B 选项。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">They are my good friends. I love ____ and they love ____.</p>", "options": ["they; me", "them; I", "them; me"], "correct": 2, "answer": "C"}], "questionCount": 5, "hasAnswers": true}, {"title": "【真题锦囊】【滁州·琅琊区】用括号内人称代词的适当形式填空", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">John and I are in the same school. ____ (we) go to school together.</p>", "options": [], "correct": null, "answer": "We"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">Everyone likes ____ (she).</p>", "options": [], "correct": null, "answer": "her"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">____ (I) have many friends. Some of ____ (they) are good at English.</p>", "options": [], "correct": null, "answer": "I; them"}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">They are waiting for ____ (he).</p>", "options": [], "correct": null, "answer": "him<br>"}, {"number": 10, "type": "input", "questionHtml": "<p class=\"source-line\">____ (she) is going to the shop with ____ (I).</p>", "options": [], "correct": null, "answer": "She; me"}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s12", "section": 12, "unit": 2, "unitName": "单元02 · 第07–12节", "short": "第12节 · L23–24", "title": "介词 on 的用法", "lessons": "Lesson 23 — Lesson 24", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>内容</th>\n<th>难度指数</th>\n<th>重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>介词 on 的用法</strong></td>\n<td>介词的概念</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td><strong>介词 on 的用法</strong></td>\n<td>介词 on 的用法</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">介词的概念</div><div class=\"gb\"><p class=\"source-line\">介词用来表示其后面的名词、代词或相当于名词的短语、从句与句中其他成分之间的关系。它是一种虚词。它不能独立充当句子成分，必须与名词、代词或相当于名词的其他词类、短语或从句构成介词短语，充当句子成分。</p>\n<p class=\"source-line\">常见的介词有 in、on、at、under、of、for 等。</p>\n<p class=\"source-line\">in January 在 1 月</p>\n<p class=\"source-line\">on June 1st 在 6 月 1 日</p>\n<p class=\"source-line\">at 12 o'clock 在 12:00</p>\n<p class=\"source-line\">under the desk 在书桌下面</p>\n<p class=\"source-line\">This is a photo of my family. 这是一张我家人的照片。</p>\n<p class=\"source-line\">What can I do for you? 我可以为你做什么？</p></div></div>\n<div class=\"g\"><div class=\"gt\">介词 on 的用法</div><div class=\"gb\"><h5>1. 表示位置，意为 “在……上面（物体的表面）”。</h5>\n<p class=\"source-line\">on the desk 在书桌上</p>\n<p class=\"source-line\">on the shelf 在架子上</p>\n<p class=\"source-line\">on the playground 在操场上</p>\n<h5>2. 表示时间，意为 “在（某一天）”。</h5>\n<p class=\"source-line\">（1） “on + 星期”</p>\n<p class=\"source-line\">on Monday 在星期一</p>\n<p class=\"source-line\">on Friday 在星期五</p>\n<p class=\"source-line\">on Sunday 在星期日</p>\n<p class=\"source-line\">（2） “on + 日期”</p>\n<p class=\"source-line\">on March 1st 在3月1日</p>\n<p class=\"source-line\">on July 10th 在7月10日</p>\n<p class=\"source-line\">on October 26th, 2024 在 2024 年 10 月 26 日</p>\n<p class=\"source-line\">（3） “on + 具体某天的上午、下午、晚上等”</p>\n<p class=\"source-line\">on Sunday morning 在星期日上午</p>\n<p class=\"source-line\">on Tuesday night 在星期二晚上</p>\n<p class=\"source-line\">on Monday afternoon 在星期一下午</p>\n<p class=\"source-line\">（4） “on + 节日”</p>\n<p class=\"source-line\">on Mid-Autumn Day 在中秋节当天</p>\n<p class=\"source-line\">on Teachers' Day 在教师节</p>\n<h5>3. 表示状态，意为“处于……状态”。</h5>\n<p class=\"source-line\">Who is on duty today? 今天谁值日？</p>\n<p class=\"source-line\">The house is on fire. 这个房子着火了。</p>\n<p class=\"source-line\">My mother was away on business. 我妈妈出差了。</p>\n<h5>4. 表示关系，意为 “关于，有关”。</h5>\n<p class=\"source-line\">I bought a book on health. 我买了一本关于健康的书。</p>\n<h5>5. 表示方位，意为“在……一边”</h5>\n<p class=\"source-line\">You will see the bus on your left. 你将在你的左边看到公共汽车。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "选择题：选择正确的介词。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">What do you wear ____ sunny days?</p>", "options": ["on", "in"], "correct": 0, "answer": "A"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">We have no classes ____ Sundays.</p>", "options": ["at", "on"], "correct": 1, "answer": "B"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">There is a book ____ the desk.</p>", "options": ["of", "on"], "correct": 1, "answer": "B"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">Children don't go to school ____ New Year's Day.</p>", "options": ["in", "on"], "correct": 1, "answer": "B"}], "questionCount": 4, "hasAnswers": true}, {"title": "单项选择", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">Look, there's a picture ____ the wall.</p>", "options": ["in", "on", "at"], "correct": 1, "answer": "B"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">She was born ____ 2000.</p>", "options": ["at", "on", "in"], "correct": 2, "answer": "C"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">My sister was born ____ October 10th, 2012.</p>", "options": ["on", "at", "in"], "correct": 0, "answer": "A"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">Teachers' Day is ____ September 10th.</p>", "options": ["at", "in", "on"], "correct": 2, "answer": "C"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【天津·和平区】用适当的介词填空", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">I get up ____ six o'clock every morning.</p>", "options": [], "correct": null, "answer": "at<br>"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">He goes to bed early ____ Mondays.</p>", "options": [], "correct": null, "answer": "on<br>"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">____ the afternoon of April 1st, we went to Beijing.</p>", "options": [], "correct": null, "answer": "On<br>"}, {"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\">He left home ____ July.</p>", "options": [], "correct": null, "answer": "in<br>"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【北京·房山区】单项选择", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">Children's Day is ____ June 1st.</p>", "options": ["in", "on", "at"], "correct": 1, "answer": "B"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">You can see the stars ____ night.</p>", "options": ["at", "on", "in"], "correct": 0, "answer": "A"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">We have PE ____ Mondays.</p>", "options": ["in", "at", "on"], "correct": 2, "answer": "C"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">Mary is ____ duty today.</p>", "options": ["in", "on", "at"], "correct": 1, "answer": "B"}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s13", "section": 13, "unit": 3, "unitName": "单元03 · 第13–18节", "short": "第13节 · L25–26", "title": "定冠词 the 的用法", "lessons": "Lesson 25 — Lesson 26", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th style=\"text-align: right;\">新概念重要指数</th>\n<th style=\"text-align: right;\">小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>冠词</td>\n<td>不定冠词 a、an</td>\n<td style=\"text-align: right;\">★★</td>\n<td style=\"text-align: right;\">★★★</td>\n</tr>\n<tr>\n<td>冠词</td>\n<td>定冠词 the</td>\n<td style=\"text-align: right;\">★★★</td>\n<td style=\"text-align: right;\">★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">冠词</div><div class=\"gb\"><p class=\"source-line\">冠词(Article)是虚词,它在名词的前面,必须与名词一起出现。英语冠词有3个,它们是a、an和the。这3个冠词又可分为不定冠词和定冠词两类。</p>\n<p class=\"source-line\">In the room, there is a table and a stereo.</p>\n<p class=\"source-line\">房间里有一张桌子和一台立体声音响。</p></div></div>\n<div class=\"g\"><div class=\"gt\">★ 不定冠词 a、an 的用法</div><div class=\"gb\"><p class=\"source-line\">a、an 是不定冠词,有 “一; 每一” 的意思。a 用在发音以辅音音素开头的单词前面, an 用在发音以元音音素开头的单词前面。</p>\n<p class=\"source-line\">如: a hamburger 一个汉堡包、an ant 一只蚂蚁。</p>\n<p class=\"source-line\">a、an 的用法区别: 用 a 用 an 这样辨, 不看字母看音素, 不见元音别放 n。</p></div></div>\n<div class=\"g\"><div class=\"gt\">定冠词 the 的用法</div><div class=\"gb\"><h5>1. 特指某(些)人或某(些)事物。</h5>\n<p class=\"source-line\">Give me the book. 把那本书给我。</p>\n<p class=\"source-line\">How do you like the film? 你认为那部电影怎么样？</p>\n<h5>2. 用在谈话双方都知道的人或事物前。</h5>\n<p class=\"source-line\">Where is the dictionary? 字典在哪儿?</p>\n<p class=\"source-line\">Open the window, please. 请把窗户打开。</p>\n<h5>3. 用于上文提到过的人或事物前。</h5>\n<p class=\"source-line\">I buy a dress and a yellow sweater with my mum. The dress is in the wardrobe. The sweater is on the desk.</p>\n<p class=\"source-line\">我和我妈妈买了一条连衣裙和一件黄色的毛衣。连衣裙在衣柜里。毛衣在书桌上。</p>\n<h5>4. 用于世界上独一无二的事物前。</h5>\n<p class=\"source-line\">The earth is bigger than the moon, but smaller than the sun.\n地球比月球大,但比太阳小。</p>\n<h5>5. 用于序数词和形容词最高级前。</h5>\n<p class=\"source-line\">Miss Li teaches the first class. 李老师教第一节课。<br />\nHe is the tallest boy in his class. 他是他班级里最高的男孩儿。</p>\n<h5>6. 用于可数名词单数前,表示某一类人或事物。</h5>\n<p class=\"source-line\">The dog is a friendly animal. 狗是一种友好的动物。</p>\n<h5>7. 与下列专有名词等连用。</h5>\n<p class=\"source-line\">（1）用在江、河、湖、海、群岛、山脉的名称前。如: the Yellow River 黄河</p>\n<p class=\"source-line\">（2）用在由普通名词构成的专有名词前。如: the United Nations 联合国、the Great Wall 长城。</p>\n<p class=\"source-line\">（3）用在姓氏的复数形式前,表示全家人。</p>\n<p class=\"source-line\">The Greens are sitting at the table. 格林一家人正围坐在桌旁。</p>\n<h5>8. 和某些形容词连用,表示某类人。</h5>\n<p class=\"source-line\">the old 老人</p>\n<p class=\"source-line\">the young 年轻人</p>\n<p class=\"source-line\">the sick 病人</p>\n<p class=\"source-line\">the rich 富人</p>\n<p class=\"source-line\">the poor 穷人</p>\n<h5>9. 用在乐器名称前。</h5>\n<p class=\"source-line\">play the piano 弹钢琴</p>\n<p class=\"source-line\">play the violin 拉小提琴</p>\n<h5>10. 用在表示方向的名词前。</h5>\n<p class=\"source-line\">The sun rises in the east. 太阳从东方升起。</p>\n<h5>11. 用在一些习惯用语中。</h5>\n<p class=\"source-line\">in the morning / afternoon / evening 在上午 / 下午 / 晚上</p>\n<p class=\"source-line\">on the left / right 在左边 / 右边</p>\n<p class=\"source-line\">in the end 最后</p>\n<p class=\"source-line\">go to the cinema 去看电影</p>\n<p class=\"source-line\">:::tip title=\"口诀\"\n定冠词用法：特指双熟悉，上文已提及；世上无独二，序数最高级；某些专有名，习语及乐器。\n:::</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【合肥·庐阳区】判断题：判断下列表达是否正确。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">a story</p>", "options": ["正确", "错误"], "correct": 0, "answer": "A"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">a apple</p>", "options": ["正确", "错误"], "correct": 1, "answer": "B"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">an useful book</p>", "options": ["正确", "错误"], "correct": 1, "answer": "B"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">a milk</p>", "options": ["正确", "错误"], "correct": 1, "answer": "B"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【佛山·三水区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">I have a hat. ____ hat is nicer than yours.</p>", "options": ["A", "An", "The", "/"], "correct": 2, "answer": "C<br>\n解析：第一句意为 “我有一顶帽子”, 上文提到过的人或物在下文中提及时, 应用定冠词 the 修饰。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">I went to ____ Great Wall last week.</p>", "options": ["the", "a", "an", "/"], "correct": 0, "answer": "A<br>\n解析：the Great Wall(长城)为专有名词, 故选 A。"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">I am ____ first one to get to school.</p>", "options": ["a", "an", "the", "/"], "correct": 2, "answer": "C<br>\n解析：first(第一)为序数词, 序数词前应使用定冠词 the。"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">I need about ____ hour to finish the work.</p>", "options": ["/", "an", "some", "a"], "correct": 1, "answer": "B<br>\n解析：hour（小时）是发音以元音音素开头的单词，应使用不定冠词 an 修饰。A、C 选项不符合语法。"}, {"number": 9, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ Greens are preparing for the coming Mid-Autumn Festival.</p>", "options": ["/", "A", "An", "The"], "correct": 3, "answer": "D<br>\n解析：the 用在姓氏的复数名词前, 表示全家人。"}, {"number": 10, "type": "mcq", "questionHtml": "<p class=\"source-line\">Jack is ____ honest boy and never tells lies.</p>", "options": ["a", "some", "an", "/"], "correct": 2, "answer": "C<br>\n解析：honest (诚实的) 是发音以元音音素开头的单词, 应使用不定冠词 an 修饰。B、D 选项不符合语法。"}], "questionCount": 6, "hasAnswers": true}]}, {"id": "s14", "section": 14, "unit": 3, "unitName": "单元03 · 第13–18节", "short": "第14节 · L27–28", "title": "some、any 的用法", "lessons": "Lesson 27 — Lesson 28", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th style=\"text-align: right;\">新概念重要指数</th>\n<th style=\"text-align: right;\">小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>some、any 的用法</td>\n<td>some 的用法</td>\n<td style=\"text-align: right;\">★★</td>\n<td style=\"text-align: right;\">★★</td>\n</tr>\n<tr>\n<td>some、any 的用法</td>\n<td>any 的用法</td>\n<td style=\"text-align: right;\">★★★★★</td>\n<td style=\"text-align: right;\">★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">some 的用法</div><div class=\"gb\"><h5>1. some 作形容词,一般用于肯定句中。</h5>\n<p class=\"source-line\">（1）修饰可数名词复数或不可数名词,表示“一些,若干”。</p>\n<p class=\"source-line\">There are some books in the living room. 客厅里有一些书。<br />\nThere is some water in the glass. 玻璃杯子里有一些水。</p>\n<p class=\"source-line\">（2）修饰可数名词单数,表示不明确的“某个”。</p>\n<p class=\"source-line\">She lives at some place in Beijing.</p>\n<p class=\"source-line\">她住在北京的某个地方。</p>\n<h5>2. some 作代词, 表示 “有些人, 有些事物”。</h5>\n<p class=\"source-line\">There are many people in the park. Some are walking. Some are talking.\n公园里有许多人。一些在散步，一些在谈话。</p>\n<p class=\"source-line\">Some of the apples are green.</p>\n<p class=\"source-line\">一些苹果是绿色的。</p>\n<h5>3. some 作副词, 表示 “大约”。</h5>\n<p class=\"source-line\">I have kept fish for some 20 years. 我养鱼大约有 20 年了。</p>\n<p class=\"source-line\">It's some 20 kilometres away. 它大约在20公里外。</p>\n<h5>4. some 用在疑问句中。</h5>\n<p class=\"source-line\">（1）表示请求、邀请或建议的一般疑问句。</p>\n<p class=\"source-line\">Can I have some peaches? 我可以吃一些桃子吗?\nWould you like some more cake? 你想再来点儿蛋糕吗?</p>\n<p class=\"source-line\">（2）期望得到对方肯定回答的一般疑问句。</p>\n<p class=\"source-line\">Would you like some eggs for breakfast? 你早餐想吃鸡蛋吗?\nHave you got some cash? 你有现金吗?</p>\n<p class=\"source-line\">（3）特殊疑问句及选择疑问句。</p>\n<p class=\"source-line\">Where can I get some travel information? 我在哪里可以得到一些旅游信息？</p></div></div>\n<div class=\"g\"><div class=\"gt\">any 的用法</div><div class=\"gb\"><h5>1. any 用在疑问句中。</h5>\n<p class=\"source-line\">Are there any trains to Shanghai at night? 晚上有去上海的火车吗?\nHave you got any questions to ask? 你有问题要问吗?</p>\n<h5>2. any 用在否定句中。</h5>\n<p class=\"source-line\">There isn't any money in my wallet. 我的钱包里没有钱。</p>\n<p class=\"source-line\">There aren't any students in the classroom. 教室里没有学生。</p>\n<h5>3. any 也可以用在肯定句中, 意为 “任何的”。</h5>\n<p class=\"source-line\">You can read any book in our library. 你可以读我们图书馆的任何一本书。</p>\n<p class=\"source-line\">Any student can answer this question. 任何学生都可以回答这个问题。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【广州·天河区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">Do you have ____ money?</p>", "options": ["any", "many", "some"], "correct": 0, "answer": "A<br>\n解析：在一般疑问句中, 表示 “一些” 通常用 any, 故选 A。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">I have ____ oranges.</p>", "options": ["any", "some", "much"], "correct": 1, "answer": "B<br>\n解析：some 用在肯定句中, 表示 “一些”, 故选 B。C 选项不符合语法。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">Would you like ____ coffee?</p>", "options": ["lot", "any", "some"], "correct": 2, "answer": "C<br>\n解析：在表达请求或建议的句子中, 表示 “一些” 用 some, 故选 C。"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">He wanted a job, ____ sort of a job.</p>", "options": ["any", "some", "much"], "correct": 0, "answer": "A<br>\n解析：当表示 “任何一个” 时, 肯定句中用 any, 故选 A。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">There isn't ____ water in the glass.</p>", "options": ["some", "many", "any"], "correct": 2, "answer": "C<br>\n解析：any 用在否定句中, 故选 C。B 选项不符合语法。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">Lisa wants to do ____ housework.</p>", "options": ["some", "any", "an"], "correct": 0, "answer": "A<br>\n解析：some 通常用在肯定句中, 表示 “一些”, 故选 A。C 选项不符合语法。"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">Bill doesn't have ____ money.</p>", "options": ["some", "any", "many"], "correct": 1, "answer": "B<br>\n解析：any 通常用在否定句或疑问句中。C 选项不符合语法。"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">Do you have ____ pens?</p>", "options": ["some", "many", "any"], "correct": 2, "answer": "C<br>\n解析：在一般疑问句中, 表示 “一些” 通常用 any, 故选 C。"}, {"number": 9, "type": "mcq", "questionHtml": "<p class=\"source-line\">Could you please give me ____ milk?</p>", "options": ["few", "little", "some"], "correct": 2, "answer": "C<br>\n解析：在希望得到肯定回答的一般疑问句中, 表示 “一些” 用 some, 故选 C。"}, {"number": 10, "type": "mcq", "questionHtml": "<p class=\"source-line\">There are ____ pictures in the room.</p>", "options": ["some", "any", "much"], "correct": 0, "answer": "A<br>\n解析：此句为肯定句, pictures (图片) 是可数名词复数, 应用 some 修饰 pictures, 故选 A。"}], "questionCount": 10, "hasAnswers": true}]}, {"id": "s15", "section": 15, "unit": 3, "unitName": "单元03 · 第13–18节", "short": "第15节 · L29–30", "title": "祈使句", "lessons": "Lesson 29 — Lesson 30", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th style=\"text-align: right;\">新概念重要指数</th>\n<th style=\"text-align: right;\">小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>祈使句</td>\n<td>祈使句的概念</td>\n<td style=\"text-align: right;\">★★</td>\n<td style=\"text-align: right;\">★★★★★</td>\n</tr>\n<tr>\n<td>祈使句</td>\n<td>祈使句的句型结构</td>\n<td style=\"text-align: right;\">★★★</td>\n<td style=\"text-align: right;\">★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">祈使句</div><div class=\"gb\"><p class=\"source-line\">表示请求、命令、劝告或建议等的句子叫祈使句。它通常省略主语(you)，根据语气的强弱，句末使用感叹号(!)或句号(.)，为表示礼貌，可在句首或句末加上“please”。句子朗读用降调。</p>\n<p class=\"source-line\">有时为了加强语气,可在动词原形前加do。例如:Do be quiet! 一定要保持安静!</p>\n<p class=\"source-line\">Be quick!</p>\n<p class=\"source-line\">快点儿!</p>\n<p class=\"source-line\">Let's play basketball.</p>\n<p class=\"source-line\">我们打篮球吧。</p>\n<p class=\"source-line\">Sweep the floor.\n打扫地板。</p></div></div>\n<div class=\"g\"><div class=\"gt\">祈使句的句型结构</div><div class=\"gb\"><h5>1. 肯定祈使句</h5>\n<p class=\"source-line\">（1）Do 型肯定祈使句: 实义动词原形(+其他).</p>\n<p class=\"source-line\">Listen! 听!</p>\n<p class=\"source-line\">Stand up. 起立。</p>\n<p class=\"source-line\">Shut up! 闭嘴!</p>\n<p class=\"source-line\">（2）Be 型肯定祈使句: Be + 其他.</p>\n<p class=\"source-line\">Be careful! 小心!</p>\n<p class=\"source-line\">Be quiet! 保持安静!</p>\n<p class=\"source-line\">Be a good child. 做个好孩子。</p>\n<p class=\"source-line\">（3）Let 型肯定祈使句: Let + 宾语 + 动词原形 (+ 其他).</p>\n<p class=\"source-line\">Let her sit here! 让她坐这儿吧！<br />\nLet's go. 我们走吧。</p>\n<p class=\"source-line\">let's 表建议,包括所有对象; let us 表请求,不包括请求对象。</p>\n<h5>2. 否定祈使句</h5>\n<p class=\"source-line\">（1）Do 型否定祈使句: Don't + 动词原形 (+ 其他).</p>\n<p class=\"source-line\">Don't eat in class! 不要在课堂上吃东西!\nDon't go there! 不要去那儿!</p>\n<p class=\"source-line\">（2）Be 型否定祈使句: Don't be + 其他.</p>\n<p class=\"source-line\">Don't be nervous! 不要紧张!</p>\n<p class=\"source-line\">Don't be sad. 不要难过。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【沈阳·和平区】用所给词的适当形式填空。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">____ (not be) late for class.</p>", "options": [], "correct": null, "answer": "Don't be"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">____ (clean) the table, please.</p>", "options": [], "correct": null, "answer": "Clean"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">____ (not play) with fire.</p>", "options": [], "correct": null, "answer": "Don't play"}], "questionCount": 3, "hasAnswers": true}, {"title": "【真题锦囊】【北京·西城区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">The doctor says “____ eat too much”.</p>", "options": ["Stop", "Don’t", "Aren’t"], "correct": 1, "answer": "B<br>\n解析：题意为“医生说‘不要吃太多’”, eat(吃)为实义动词原形, 应用 don't, 故选 B。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ read in the sun.</p>", "options": ["Not to", "Don't", "Is"], "correct": 1, "answer": "B<br>\n解析：题意为 “不要在阳光下阅读”, read(阅读)为实义动词, 故在句首加 Don't。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">Let's ____ look at the picture.</p>", "options": ["not", "don't", "can't"], "correct": 0, "answer": "A<br>\n解析：句子是 Let 型否定祈使句。Let 型否定祈使句有两种形式, 分别是 “Don’t let + 宾语 + 动词原形 (+ 其他).” 和 “Let + 宾语 + not + 动词原形 (+ 其他).”。"}], "questionCount": 3, "hasAnswers": true}, {"title": "【真题锦囊】【佛山·三水区】句型转换。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">Let her make salad. (改为否定句)</p>", "options": [], "correct": null, "answer": "Let her not make salad. 或 Don't let her make salad."}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">Come here. (改为否定句)</p>", "options": [], "correct": null, "answer": "Don't come here."}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">Peter stands up. (改为祈使句)</p>", "options": [], "correct": null, "answer": "Peter, stand up."}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s16", "section": 16, "unit": 3, "unitName": "单元03 · 第13–18节", "short": "第16节 · L31–32", "title": "现在进行时", "lessons": "Lesson 31 — Lesson 32", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th style=\"text-align: right;\">新概念重要指数</th>\n<th style=\"text-align: right;\">小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>现在进行时</td>\n<td>现在进行时的概念</td>\n<td style=\"text-align: right;\">★★</td>\n<td style=\"text-align: right;\">★★</td>\n</tr>\n<tr>\n<td>现在进行时</td>\n<td>现在进行时的构成</td>\n<td style=\"text-align: right;\">★★★★★</td>\n<td style=\"text-align: right;\">★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">现在进行时的概念</div><div class=\"gb\"><p class=\"source-line\">现在进行时表示现在正在进行的动作或行为。</p>\n<p class=\"source-line\">My mother is cooking now. 我妈妈现在正在煮饭。</p>\n<p class=\"source-line\">We are playing football now. 我们现在正在踢足球。</p></div></div>\n<div class=\"g\"><div class=\"gt\">现在进行时的构成</div><div class=\"gb\"><h5>1. 肯定句: 主语 + be (am / is / are) + 现在分词 (+ 其他).</h5>\n<p class=\"source-line\">My little sister is reading a book and my brother is playing games. 我妹妹正在看书,我哥哥正在玩儿游戏。<br />\nHe is cleaning the bedroom. 他正在打扫卧室。</p>\n<h5>2. 否定句: 主语 + be (am / is / are) + not + 现在分词 (+ 其他).</h5>\n<p class=\"source-line\">My father isn't reading now. 我父亲现在没在看书。</p>\n<p class=\"source-line\">They aren't having a maths lesson. 他们没在上数学课。</p>\n<h5>3. 一般疑问句: Be (Am / Is / Are) + 主语 + 现在分词 (+ 其他)?</h5>\n<p class=\"source-line\">Are you having a music lesson? 你们正在上音乐课吗？</p>\n<p class=\"source-line\">Is she playing computer games? 她正在玩儿电脑游戏吗？</p>\n<h5>4. 特殊疑问句:疑问词 + be (am / is / are) + 主语 + 现在分词(+其他)?</h5>\n<p class=\"source-line\">What are you doing now? 你们现在正在做什么？</p>\n<p class=\"source-line\">What is he looking at? 他正在看什么？</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【天津·红桥区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">Who ____ over there now?</p>", "options": ["singing", "are sing", "is singing", "sing"], "correct": 2, "answer": "C<br>\n解析：句子是现在进行时的特殊疑问句, 句型结构是 “疑问词 + be (am / is / are) + 动词 -ing 形式 (+ 其他)?”, 此句中缺少 be 和动词 -ing 形式, 故选 C。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">It's nine o'clock. The students ____ an English class.</p>", "options": ["have", "having", "is having", "are having"], "correct": 3, "answer": "D<br>\n解析：根据句意可知第二个句子是现在进行时的肯定句, 句中缺少 be 和动词 -ing 形式, 句中主语是复数, be 用 are, 故选 D。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">Listen! The baby ____ in the living room.</p>", "options": ["are crying", "cried", "is crying", "cries"], "correct": 2, "answer": "C<br>\n解析：由 “Listen!” 可知第二个句子是现在进行时的肯定句,主语是第三人称单数, be 用 is, 故选 C。"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">Lily ____ the piano now.</p>", "options": ["is playing", "plays", "playing", "are playing"], "correct": 0, "answer": "A<br>\n解析：根据句意可知此句是现在进行时的肯定句, 主语 Lily 是第三人称单数, be 用 is, 故选 A。"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【天津·南开区】根据要求完成下列各题。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">Tom is reading a book. (改为否定句)</p>", "options": [], "correct": null, "answer": "Tom isn't reading a book.<br>"}, {"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">the dog, chase, the cat, now ( . ) (用现在进行时写句子)</p>", "options": [], "correct": null, "answer": "The dog is chasing the cat now.<br>"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">Kate is looking for her watch. (改为一般疑问句)</p>", "options": [], "correct": null, "answer": "Is Kate looking for her watch?<br>"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">Miss White <u>is doing some washing</u>. (对画线部分提问)</p>", "options": [], "correct": null, "answer": "What is, doing<br>"}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s17", "section": 17, "unit": 3, "unitName": "单元03 · 第13–18节", "short": "第17节 · L33–34", "title": "现在分词", "lessons": "Lesson 33 — Lesson 34", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th style=\"text-align: right;\">新概念重要指数</th>\n<th style=\"text-align: right;\">小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>现在分词</td>\n<td>现在分词的概念</td>\n<td style=\"text-align: right;\">★</td>\n<td style=\"text-align: right;\">★★</td>\n</tr>\n<tr>\n<td>现在分词</td>\n<td>现在分词的变化规则</td>\n<td style=\"text-align: right;\">★★</td>\n<td style=\"text-align: right;\">★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">现在分词的概念</div><div class=\"gb\"><p class=\"source-line\">动词的 -ing 形式除了可以作动名词外，还可以作现在分词。</p>\n<p class=\"source-line\">Look! They are jumping. 看！他们正在跳。</p>\n<p class=\"source-line\">The family are walking over the bridge.\n这家人正在过桥。</p></div></div>\n<div class=\"g\"><div class=\"gt\">现在分词变化规则</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>变化规则</th>\n<th>动词原形</th>\n<th>现在分词</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>一般情况下，直接在词尾加 -ing</td>\n<td>do</td>\n<td>doing</td>\n</tr>\n<tr>\n<td>一般情况下，直接在词尾加 -ing</td>\n<td>see</td>\n<td>seeing</td>\n</tr>\n<tr>\n<td>以不发音的字母 e 结尾，去 e 再加 -ing</td>\n<td>make</td>\n<td>making</td>\n</tr>\n<tr>\n<td>以不发音的字母 e 结尾，去 e 再加 -ing</td>\n<td>write</td>\n<td>writing</td>\n</tr>\n<tr>\n<td>末尾只有一个辅音字母的重读闭音节，双写末尾辅音字母再加 -ing</td>\n<td>run</td>\n<td>running</td>\n</tr>\n<tr>\n<td>末尾只有一个辅音字母的重读闭音节，双写末尾辅音字母再加 -ing</td>\n<td>swim</td>\n<td>swimming</td>\n</tr>\n<tr>\n<td>以 ie 结尾，先将 ie 变为 y，再加 -ing</td>\n<td>die</td>\n<td>dying</td>\n</tr>\n<tr>\n<td>以 ie 结尾，先将 ie 变为 y，再加 -ing</td>\n<td>lie</td>\n<td>lying</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">:::tip title=\"口诀\"\n现在分词变化规则：动词加上 ing，这种形式真有趣。哑 e 结尾去掉 e，然后加上 ing。结尾重读闭音节，双写再加 ing。结尾 ie 别慌张，变 y 加上 ing。\n:::</p>\n<p class=\"source-line\">重读闭音节三要素：</p>\n<p class=\"source-line\">（1）结构为“辅元辅”；</p>\n<p class=\"source-line\">（2）元音字母发短音；</p>\n<p class=\"source-line\">（3）最后一个音节是重读音节。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【昆明·五华区】用所给词的正确形式填空。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">Look at my baby brother. He ____ (sleep).</p>", "options": [], "correct": null, "answer": "is sleeping<br>"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">Lots of students are ____ (learn) Chinese in England now.</p>", "options": [], "correct": null, "answer": "learning<br>"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">Sue is ____ (talk) with her friends.</p>", "options": [], "correct": null, "answer": "talking"}, {"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\">Listen! Who ____ (sing) in the room?</p>", "options": [], "correct": null, "answer": "is singing"}, {"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">Look! My sister ____ (fly) a kite.</p>", "options": [], "correct": null, "answer": "is flying"}], "questionCount": 5, "hasAnswers": true}, {"title": "【真题锦囊】【佛山·顺德区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">What are you ____ now?</p>", "options": ["doing", "do", "does"], "correct": 0, "answer": "A<br>\n解析：now(现在)为现在进行时的标志性词语。do(做)的现在分词为 doing。"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">I am ____ English.</p>", "options": ["speak", "speaks", "speaking"], "correct": 2, "answer": "C"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">Look! The rabbit is ____.</p>", "options": ["jump", "jumping", "jumps"], "correct": 1, "answer": "B"}, {"number": 9, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Tina, what's your dad doing?<br>\n—— He ____ my computer.</p>", "options": ["repairs", "is repairing", "has repaired"], "correct": 1, "answer": "B"}, {"number": 10, "type": "mcq", "questionHtml": "<p class=\"source-line\">The workers ____ the community centre now.</p>", "options": ["cleaned", "is cleaning", "are cleaning"], "correct": 2, "answer": "C<br>\n解析：now (现在)为现在进行时的标志性词语, 主语为第三人称复数, be 用 are, clean (打扫)的现在分词为 cleaning。"}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s18", "section": 18, "unit": 3, "unitName": "单元03 · 第13–18节", "short": "第18节 · L35–36", "title": "方位介词", "lessons": "Lesson 35 — Lesson 36", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th style=\"text-align: right;\">新概念重要指数</th>\n<th style=\"text-align: right;\">小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>方位介词</td>\n<td>方位介词的概念</td>\n<td style=\"text-align: right;\">★★</td>\n<td style=\"text-align: right;\">★★</td>\n</tr>\n<tr>\n<td>方位介词</td>\n<td>between、on、beside 等的用法</td>\n<td style=\"text-align: right;\">★★★★★</td>\n<td style=\"text-align: right;\">★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">方位介词的概念</div><div class=\"gb\"><p class=\"source-line\">表示事物存在的方向和位置的介词,我们称之为方位介词。</p>\n<p class=\"source-line\">常见的方位介词有 in、on、at、under、beside、between、near、behind、up、over、down 等。</p>\n<p class=\"source-line\">The Greens are on the beach. 格林一家在沙滩上。</p>\n<p class=\"source-line\">The man is in the car. 那个男人在车里。</p>\n<p class=\"source-line\">Lucy is near her two sisters. 露西在她两个姐姐的附近。</p></div></div>\n<div class=\"g\"><div class=\"gt\">方位介词 between、on、beside</div><div class=\"gb\"><h5>1. between 和 among 的区别</h5>\n<p class=\"source-line\">（1）between : (空间上) 在……中间</p>\n<p class=\"source-line\">My mother planted a lot of flowers between the two gardens.</p>\n<p class=\"source-line\">我妈妈在两个花园中间种了许多花儿。</p>\n<p class=\"source-line\">（2）between : (时间上) 在……之间</p>\n<p class=\"source-line\">That lady is between fifty and sixty.</p>\n<p class=\"source-line\">那位女士年龄在50岁到60岁之间。</p>\n<p class=\"source-line\">（3）between 作为介词时常与 and 连用；不与 and 连用时，后面通常接表示两个或多个个体的复数名词或代词。</p>\n<p class=\"source-line\">The house is between the mountain and the sea. 房子在山与海之间。<br />\nThe apple is between the two boxes. 苹果在两个盒子之间。</p>\n<p class=\"source-line\">（4）among: 在……中；……之一；在三者或以上之中</p>\n<p class=\"source-line\">The house is among the trees. 房子在树木中。<br />\nI saw Peter among the crowd. 我看见彼得在人群中。</p>\n<h5>2. on、over 和 above 的区别</h5>\n<p class=\"source-line\">（1）on: (指与另一物体表面相接触) 在……上</p>\n<p class=\"source-line\">The book is on the desk. 那本书在书桌上。<br />\nThe apples are on the trees. 苹果在树上。</p>\n<p class=\"source-line\">（2）over: (指在物体的垂直上方) 悬在……上面</p>\n<p class=\"source-line\">There is a clock over the blackboard.\n黑板上方有一个钟。</p>\n<p class=\"source-line\">There is a bridge over the river. 河上有一座桥。</p>\n<p class=\"source-line\">（3）above: (一般指位置高于某物, 但不一定在正上方, 也不接触另一物) 在上面</p>\n<p class=\"source-line\">Raise your hands above your head. 把你的手举过头。<br />\nCan you see the birds flying above the trees?<br />\n你能看见鸟儿在树的上空飞吗？</p>\n<h5>3. beside 和 near 的区别</h5>\n<p class=\"source-line\">（1）beside: 在……旁边</p>\n<p class=\"source-line\">The chair is beside the table. 椅子在桌子旁边。</p>\n<p class=\"source-line\">Come and sit beside me. 过来坐我旁边。</p>\n<p class=\"source-line\">（2）near: 在……附近</p>\n<p class=\"source-line\">There is a supermarket near his home. 他家附近有一家超市。</p>\n<p class=\"source-line\">Don't play near the road. 不要在马路附近玩儿。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【佛山·顺德区】选择题：选择合适的介词。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">She puts her watch ____ the table.\nE. above\nF. among\nG. beside\nH. to</p>", "options": ["between", "at", "near", "on"], "correct": 3, "answer": "D<br>\n解析：此句意为 “她把手表放在桌子上”, 手表与桌子相接触, 故选介词 on。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">He often goes ____ school by bus.\nE. among\nF. beside\nG. to\nH. between</p>", "options": ["at", "near", "on", "above"], "correct": null, "answer": "G<br>\n解析：go to school(去上学)是固定短语, 故选介词 to。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">I don't need a car because I live ____ the city centre.\nE. beside\nF. to\nG. between\nH. at</p>", "options": ["near", "on", "above", "among"], "correct": 0, "answer": "A<br>\n解析：表达在城市中心附近介词用 near。"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">The letter B is ____ A and C.\nE. to\nF. between\nG. at\nH. near</p>", "options": ["on", "above", "among", "beside"], "correct": null, "answer": "F<br>\n解析：“between...and...”意为“在……和……之间”，是固定短语，故选介词 between。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">Sue sits ____ Mary.\nE. between\nF. at\nG. near\nH. on</p>", "options": ["above", "among", "beside", "to"], "correct": 2, "answer": "C<br>\n解析：表达坐在某人旁边介词用 beside。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">There is a mountain ____ the trees.\nE. at\nF. near\nG. on\nH. above</p>", "options": ["among", "beside", "to", "between"], "correct": 0, "answer": "A"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">You can see stars ____ night.\nE. near\nF. on\nG. above\nH. among</p>", "options": ["beside", "to", "between", "at"], "correct": 3, "answer": "D"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">The bird is flying ____ the trees.\nE. on\nF. above\nG. among\nH. beside</p>", "options": ["to", "between", "at", "near"], "correct": null, "answer": "F"}], "questionCount": 8, "hasAnswers": true}]}, {"id": "s19", "section": 19, "unit": 4, "unitName": "单元04 · 第19–24节", "short": "第19节 · L37–38", "title": "be going to 的用法", "lessons": "Lesson 37 — Lesson 38", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>be going to的用法</td>\n<td>be going to 的含义</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>be going to的用法</td>\n<td>be going to 结构</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>be going to的用法</td>\n<td>be going to 与 be doing 的区别</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">be going to 的含义</div><div class=\"gb\"><p class=\"source-line\">be going to 表示在将来某个时间里将要发生的动作或存在的状态,表示“打算,将要”。常和表示将来的时间状语 next year（明年）、tomorrow（在明天）、in the future（在将来）等连用。</p>\n<p class=\"source-line\">—— What are you going to do, Dad? 你打算做什么,爸爸?<br>\n—— I'm going to make a bookcase. 我打算做一个书架。<br>\n—— What is he going to do? 他打算做什么？<br>\n—— He is going to paint the bookcase. 他打算给书架漆上颜色。</p></div></div>\n<div class=\"g\"><div class=\"gt\">be going to 结构</div><div class=\"gb\"><h5>1. 含 be going to 结构的一般将来时的肯定句</h5>\n<p class=\"source-line\">结构: 主语 + be (am / is / are) going to + 动词原形 (+ 其他).</p>\n<p class=\"source-line\">I am going to paint it pink. 我打算把它漆成粉色。</p>\n<h5>2. 含 be going to 结构的一般将来时的否定句</h5>\n<p class=\"source-line\">结构: 主语 + be (am / is / are) not going to + 动词原形 (+ 其他).</p>\n<p class=\"source-line\">I am not going to paint it pink. 我不打算把它漆成粉色。</p>\n<h5>3. 含 be going to 结构的一般将来时的一般疑问句</h5>\n<p class=\"source-line\">结构: Be (Am / Is / Are) + 主语 + going to + 动词原形 (+ 其他)?</p>\n<p class=\"source-line\">Are you going to paint it pink? 你打算把它漆成粉色吗？</p>\n<h5>4. 含 be going to 结构的一般将来时的特殊疑问句</h5>\n<p class=\"source-line\">结构:疑问词+be(am/is/are)+主语+going to+动词原形(+其他)?</p>\n<p class=\"source-line\">When are you going to paint it? 你打算什么时候给它漆颜色？</p></div></div>\n<div class=\"g\"><div class=\"gt\">be going to 与 be doing 的区别</div><div class=\"gb\"><h5>1. be going to 结构常用在一般将来时中,表示在将来某个时间里将要发生的动作或存在的状态,表示“打算,将要”。</h5>\n<h5>2. be doing 结构常用在现在进行时中,表示现在正在进行或发生的动作。</h5>\n<p class=\"source-line\">I am going to make a bookcase. 我打算做一个书架。(打算要做)</p>\n<p class=\"source-line\">I am making a bookcase. 我正在做书架。(正在做)</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【昆明·盘龙区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ are they going to ____ tomorrow?<br>\n—— They are going to have a party.</p>", "options": ["When; do", "What; go", "What; do"], "correct": 2, "answer": "C<br>\n解析：答语意为 “他们打算举办一场派对”, 对做某事进行回答, 所以疑问词用 what。做某事用动词 do 代替。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">I'm ____ my grandmother tomorrow.</p>", "options": ["visited", "going to visit", "visit"], "correct": 1, "answer": "B<br>\n解析：tomorrow (在明天) 表示将来, 可用 be going to 结构表将来, 句中缺失的部分为 going to visit, 故此题选择 B 选项。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">I'm going ____ a tree tomorrow.</p>", "options": ["plant", "to plant", "plants"], "correct": 1, "answer": "B"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Are you going to take a piano lesson?<br>\n—— ____</p>", "options": ["No, we don't.", "No, I can't.", "Yes, I am."], "correct": 2, "answer": "C"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【北京·丰台区】阅读短文，根据短文内容选择正确答案。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">Who is going to give Ma Lili a birthday party?</p>", "options": ["Ma Lili herself.", "Her friends.", "Her parents."], "correct": 2, "answer": "C<br>\n解析：句子意为 “谁打算给马丽丽举办一个生日派对?”, 第一段第一句话提到 “Ma Lili’s parents are going to give a birthday party for her. (马丽丽的父母打算为她举办一个生日派对。)”, 故正确答案为 C 选项。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">How many people are coming to Ma Lili's party?</p>", "options": ["Twenty.", "Twenty-one.", "Twenty-five."], "correct": 2, "answer": "C<br>\n解析：句子意为 “多少个人将要来马丽丽的派对?”, 在第一段提到 “Ma Lili has a lot of friends. They are going to the party. (马丽丽有很多朋友。他们打算来派对。)” “There are twenty-five of them. (他们有 25 个人。)”, 故正确答案为 C 选项。"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">Her mother ____ for her party.</p>", "options": ["is making cakes", "is shopping", "makes a cake"], "correct": 0, "answer": "A<br>\n解析：句子意为 “她妈妈为她的聚会……”, 第二段第一句 “Ma Lili’s mother is making birthday cakes for the party. (马丽丽的妈妈正在为派对做蛋糕。)”, 句子时态为现在进行时, 故正确答案为 A 选项。"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">How old is Ma Lili going to be?</p>", "options": ["12.", "13.", "14."], "correct": 2, "answer": "C<br>\n解析：句子意为 “马丽丽将要多少岁?”, 第一段提到 “She’s going to be fourteen years old. (她将要 14 岁了。)”, 故正确答案为 C 选项。"}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s20", "section": 20, "unit": 4, "unitName": "单元04 · 第19–24节", "short": "第20节 · L39–40", "title": "动词 + 间接宾语 + 直接宾语", "lessons": "Lesson 39 — Lesson 40", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>宾语</td>\n<td>宾语</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>宾语</td>\n<td>直接宾语和间接宾语</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td>祈使句</td>\n<td>否定祈使句</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">宾语</div><div class=\"gb\"><p class=\"source-line\">宾语表示动作的对象,是动作的承受者。英语的及物动词须接宾语,宾语一般放在及物动词之后。可以用作宾语的有名词、代词、数词、动词不定式、动名词、名词化的形容词或分词、短语和从句。</p>\n<p class=\"source-line\">Pass me the fork, please. 请把叉子递给我。\nCan you see her? 你能看到她吗？</p></div></div>\n<div class=\"g\"><div class=\"gt\">直接宾语和间接宾语</div><div class=\"gb\"><h5>1. 有些及物动词,如 give(给)、tell(告诉)、show(给……看)、pass(递)、send(发送)、lend(借给)、bring(带来)等,可以有两个宾语。这种动词所要接的两个宾语,往往一个指物,一个指人。指物的叫直接宾语,指人的叫间接宾语。间接宾语一般放在直接宾语之前。</h5>\n<p class=\"source-line\">Give me a book, please. 请给我一本书。</p>\n<p class=\"source-line\">(me 是间接宾语, book 是直接宾语)</p>\n<p class=\"source-line\">Show me that picture. 给我看看那张照片。</p>\n<p class=\"source-line\">(me 是间接宾语, picture 是直接宾语)</p>\n<h5>2. 如果直接宾语是人称代词,须在间接宾语之前加介词 to 或 for,并把这个带 to 或 for 的间接宾语放在直接宾语之后。</h5>\n<p class=\"source-line\">Can you see the green bag? Hand it to me, please.</p>\n<p class=\"source-line\">你能看见那个绿色的包吗？请把它递给我。</p>\n<p class=\"source-line\">Take those flowers to her.</p>\n<p class=\"source-line\">把那些花儿带给她。</p>\n<h5>3. 强调间接宾语时,把作为直接宾语的名词放在前面,把带 to 的间接宾语放在后面。</h5>\n<p class=\"source-line\">I sent an email to my grandmother yesterday.</p>\n<p class=\"source-line\">我昨天给我奶奶发送了一封电子邮件。</p></div></div>\n<div class=\"g\"><div class=\"gt\">否定祈使句</div><div class=\"gb\"><h5>1. 表示请求、命令、劝告或建议等的句子叫祈使句。它通常省略主语(you)，根据语气的强弱，句末使用感叹号(!)或句号(.),为表示礼貌,可在句首或句末加上“please”。句子用降调朗读。</h5>\n<p class=\"source-line\">Be careful next time. 下次小心点儿。</p>\n<p class=\"source-line\">Don't be late! 不要迟到!</p>\n<h5>2. 祈使句的否定结构</h5>\n<p class=\"source-line\">（1）Let 型否定祈使句：</p>\n<p class=\"source-line\">① Don't let + 宾语 + 动词原形 (+ 其他).</p>\n<p class=\"source-line\">Don't let him go out. 不要让他出去。</p>\n<p class=\"source-line\">② Let + 宾语 + not + 动词原形 (+ 其他).</p>\n<p class=\"source-line\">Let him not go out. 不要让他出去。</p>\n<p class=\"source-line\">（2）No 型否定祈使句: No + 动词 -ing 形式. / No + 名词.</p>\n<p class=\"source-line\">No parking!\n禁止停车!</p>\n<p class=\"source-line\">No photos!\n禁止拍照!</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【昆明·盘龙区】用括号内所给动词的适当形式填空。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">Don't ____ (open) the door.</p>", "options": [], "correct": null, "answer": "open"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">No ____ (talk)!</p>", "options": [], "correct": null, "answer": "talking"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">Mary shows ____ (I) her new bag.</p>", "options": [], "correct": null, "answer": "me"}, {"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\">My mother bought a bike for ____ (I).</p>", "options": [], "correct": null, "answer": "me"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【合肥·蜀山区】把下列肯定祈使句改为否定祈使句。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">Put on your hat.（改为否定祈使句）</p>", "options": [], "correct": null, "answer": "Don't put on your hat.<br>"}, {"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">Turn on the lights.（改为否定祈使句）</p>", "options": [], "correct": null, "answer": "Don't turn on the lights.<br>"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">Take off your coats.（改为否定祈使句）</p>", "options": [], "correct": null, "answer": "Don't take off your coats.<br>"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">Let's go and play together.（改为否定祈使句）</p>", "options": [], "correct": null, "answer": "Let's not go and play together.<br>"}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s21", "section": 21, "unit": 4, "unitName": "单元04 · 第19–24节", "short": "第21节 · L41–42", "title": "不可数名词", "lessons": "Lesson 41 — Lesson 42", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>不可数名词</td>\n<td>概念</td>\n<td>★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>不可数名词</td>\n<td>不可数名词的量的表示方法</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">什么是不可数名词？</div><div class=\"gb\"><p class=\"source-line\">不可数名词指无法用准确的阿拉伯数字说明数量的词。比较常见的不可数名词是一些液体(饮料)、食品或调料类名词。不可数名词没有单数和复数之分。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>类别</th>\n<th>类型</th>\n<th>说明</th>\n<th>示例</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>不可数名词</td>\n<td>物质名词</td>\n<td>无法分为个体的实物的词</td>\n<td>cheese 乳酪 soap 肥皂 milk 牛奶 bread 面包</td>\n</tr>\n<tr>\n<td>不可数名词</td>\n<td>抽象名词</td>\n<td>表示动作、状态、品质、感情等抽象概念的词</td>\n<td>work 工作 study 学习 love 爱 friendship 友谊</td>\n</tr>\n</tbody>\n</table></div></div></div>\n<div class=\"g\"><div class=\"gt\">不可数名词的量的表示方法</div><div class=\"gb\"><h5>1. 用 some、much、a little、a lot of、a bit of、plenty of 等数量形容词表示。</h5>\n<p class=\"source-line\">:::note title=\"不可数名词的修饰语\"\nsome meat 一些肉<br>a lot of money 很多钱<br>a little water 一点水</p>\n<p class=\"source-line\">plenty of、some、a lot of、lots of、most of 等既可修饰可数名词复数，也可修饰不可数名词。\n:::</p>\n<h5>2. 用 “a ... of” 表示。</h5>\n<p class=\"source-line\">（1）表 “条、块、片、张、份、则” 的 piece。</p>\n<p class=\"source-line\">a piece of meat 一块肉</p>\n<p class=\"source-line\">a piece of paper 一张纸</p>\n<p class=\"source-line\">two pieces of information 两条信息</p>\n<p class=\"source-line\">a piece of advice 一条建议</p>\n<p class=\"source-line\">a piece of news 一则新闻</p>\n<p class=\"source-line\">（2）表 “容积、容量” 的 glass[一杯(的量)]、cup[一杯(的量)]、bottle[一瓶(的量)]、</p>\n<p class=\"source-line\">basket(一篮)。</p>\n<p class=\"source-line\">a glass of milk 一杯牛奶</p>\n<p class=\"source-line\">a bottle of juice 一瓶果汁</p>\n<p class=\"source-line\">a cup of tea 一杯茶</p>\n<p class=\"source-line\">a basket of food 一篮食物</p>\n<p class=\"source-line\">（3）表 “形状” 的 loaf(条)、bar(块)、tin(罐)。</p>\n<p class=\"source-line\">a loaf of bread 一条面包</p>\n<p class=\"source-line\">a tin of beans 一罐青豆</p>\n<p class=\"source-line\">a bar of soap 一块肥皂</p>\n<p class=\"source-line\">（4）表 “重量” 的 kilo (千克)、pound (磅)。</p>\n<p class=\"source-line\">a pound of sugar 一磅糖</p>\n<p class=\"source-line\">half a pound of coffee 半磅咖啡</p>\n<p class=\"source-line\">two kilos of meat 两千克肉</p>\n<p class=\"source-line\">（5）表“行为状态”的单位词。</p>\n<p class=\"source-line\">a ray of hope 一线希望</p>\n<p class=\"source-line\">a flash of lightning 一道闪电</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【天津·南开区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">They don't have ____.</p>", "options": ["much homework", "many homeworks", "many homework", "much homeworks"], "correct": 0, "answer": "A<br>\n解析：homework(家庭作业)为不可数名词, 可以用 much(许多)修饰。many(许多)常用来修饰可数名词复数。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">Can you give me ____?</p>", "options": ["a paper", "some pieces of paper", "some pieces of papers", "papers"], "correct": 1, "answer": "B<br>\n解析：paper(纸)为不可数名词, 其前不可以加不定冠词, 也不可以把 paper 变为复数形式。piece(块; 张)为可数名词, 复数形式为 pieces。故此题选择 B 选项。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Would you like to have a drink?<br>\n—— Yes. Two ____, please.</p>", "options": ["cup of tea", "cups of tea", "cup of teas", "cups of teas"], "correct": 1, "answer": "B<br>\n解析：two(二)后接可数名词复数, cup(杯)的复数形式为 cups。tea(茶)为不可数名词,无复数形式。故此题选择 B 选项。"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">We have some ____ and ____ every morning.</p>", "options": ["milks; egg", "milks; eggs", "milk; eggs", "milk; egg"], "correct": 2, "answer": "C<br>\n解析：some (一些) 可以修饰可数名词复数或不可数名词, milk (牛奶) 为不可数名词, egg (鸡蛋) 的复数形式为 eggs。故此题选择 C 选项。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">Dad has ____ for breakfast.</p>", "options": ["two piece of bread", "two pieces of bread", "two piece of breads", "two pieces of breads"], "correct": 1, "answer": "B<br>\n解析：two (二) 后接可数名词复数, piece (块; 张) 为可数名词, 复数形式为 pieces。bread (面包) 为不可数名词。故此题选择 B 选项。"}], "questionCount": 5, "hasAnswers": true}, {"title": "【真题锦囊】【沈阳·铁西区】用所给词的适当形式填空。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">There is some ____ (water) in the bottle.</p>", "options": [], "correct": null, "answer": "water"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">Do you want to have two ____ (pound) of ____ (sugar)?</p>", "options": [], "correct": null, "answer": "pounds, sugar"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">I'd like a ____ (loaf) of bread for breakfast.</p>", "options": [], "correct": null, "answer": "loaf"}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s22", "section": 22, "unit": 4, "unitName": "单元04 · 第19–24节", "short": "第22节 · L43–44", "title": "情态动词 can", "lessons": "Lesson 43 — Lesson 44", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>情态动词 can</td>\n<td>情态动词的概念</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>情态动词 can</td>\n<td>can 的用法</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td>情态动词 can</td>\n<td>can 的句式结构</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">什么是情态动词？</div><div class=\"gb\"><p class=\"source-line\">情态动词本身有一定的词义,表示说话人对有关行为或事物的态度和看法,认为其可能、应该或必要等。</p>\n<p class=\"source-line\">情态动词不能独立作谓语, 只能和动词原形一起构成谓语。情态动词没有人称和数的变化。</p>\n<p class=\"source-line\">常见的情态动词有 : can / could (能, 可以)、may / might (可能)、must (必须)、will / would (将要)、need (需要) 等。</p>\n<p class=\"source-line\">I can swim. 我会游泳。</p>\n<p class=\"source-line\">Her mother may be at home. 她妈妈可能在家。</p>\n<p class=\"source-line\">You must clean your bedroom on Sunday.</p>\n<p class=\"source-line\">你必须在星期日打扫你的卧室。</p>\n<p class=\"source-line\">Need I go home at once? 我需要立刻回家吗?</p></div></div>\n<div class=\"g\"><div class=\"gt\">can 的用法</div><div class=\"gb\"><h5>1. 表示能力,意为“能,会”。</h5>\n<p class=\"source-line\">I can speak English, but he can't. 我会讲英语,但是他不会。</p>\n<p class=\"source-line\">She can swim. 她会游泳。</p>\n<h5>2. 表示允许、许可或请求。</h5>\n<p class=\"source-line\">Can / May I come in? 我可以进来吗?\nCan / Could you help me? 你能帮我吗?</p>\n<h5>3. 用于否定句或疑问句中,表示推测。</h5>\n<p class=\"source-line\">The girl can't be Li Mei. She's at school.\n那个女孩儿不可能是李梅，她在学校呢。\nJack can't be at home. 杰克不可能在家。</p>\n<p class=\"source-line\">cannot = can't</p></div></div>\n<div class=\"g\"><div class=\"gt\">can 的句式结构</div><div class=\"gb\"><h5>1. 肯定句: 主语 + can + 动词原形 (+ 其他).</h5>\n<p class=\"source-line\">I can see three boats on the river. 我能看到河面上有 3 条船。</p>\n<p class=\"source-line\">He can play the guitar. 他会弹吉他。</p>\n<h5>2. 否定句: 主语 + can't + 动词原形 (+ 其他).</h5>\n<p class=\"source-line\">She can't play volleyball. 她不会打排球。</p>\n<p class=\"source-line\">I can't dance. 我不会跳舞。</p>\n<h5>3. 一般疑问句: Can + 主语 + 动词原形 (+ 其他)?</h5>\n<p class=\"source-line\">肯定回答: Yes, 主语 + can.</p>\n<p class=\"source-line\">否定回答: No, 主语 + can't.</p>\n<p class=\"source-line\">—— Can you sing English songs? 你会唱英文歌曲吗?<br>\n—— Yes, I can. 是的,我会。<br>\n—— Can you play the piano? 你会弹钢琴吗?<br>\n—— No, I can't. 不,我不会。</p>\n<h5>4. 特殊疑问句: 疑问词 + can + 主语 + 动词原形 (+ 其他)?</h5>\n<p class=\"source-line\">What can you do? 你会做什么？</p>\n<p class=\"source-line\">Who can play the violin? 谁会拉小提琴?</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【佛山·南海区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ you play football?<br>\n—— Yes, I can.</p>", "options": ["Do", "Can", "Are"], "correct": 1, "answer": "B"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Can I listen to music here?<br>\n—— ____, but you can listen in the music room.</p>", "options": ["Yes, you can", "No, you can't", "Yes, I do"], "correct": 1, "answer": "B"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">I can ____.</p>", "options": ["do kung fu", "does kung fu", "did kung fu"], "correct": 0, "answer": "A"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Can you sing?<br>\n—— No, I ____.</p>", "options": ["can", "don't", "can't"], "correct": 2, "answer": "C"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【天津·南开区】按照要求完成句子。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">Can you ____ (find) any ice cream? (用所给词的正确形式填空)</p>", "options": [], "correct": null, "answer": "find<br>"}, {"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">She can see <u>two birds</u> in the picture. (对画线部分提问)</p>", "options": [], "correct": null, "answer": "What can she see in the picture?<br>"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">你能做什么？（翻译句子）</p>", "options": [], "correct": null, "answer": "What can you do?"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">I can make cakes, but I ____ (can) make biscuits. (用所给词的正确形式填空)</p>", "options": [], "correct": null, "answer": "can't<br>"}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s23", "section": 23, "unit": 4, "unitName": "单元04 · 第19–24节", "short": "第23节 · L45–46", "title": "一般现在时（一）", "lessons": "Lesson 45 — Lesson 46", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>一般现在时(一)</td>\n<td>概念</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>一般现在时(一)</td>\n<td>一般现在时的构成</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>一般现在时(一)</td>\n<td>动词第三人称单数形式的变化规则</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">什么是一般现在时？</div><div class=\"gb\"><p class=\"source-line\">一般现在时是一种英语语法形式。表示通常性、规律性、习惯性的动作或状态，或者动作有时间规律发生的事件的一种时间状态。</p>\n<p class=\"source-line\">I get up at six o'clock every morning. 我每天早上6:00起床。</p>\n<p class=\"source-line\">I often go to school by bus. 我经常乘公共汽车去上学。</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般现在时的构成</div><div class=\"gb\"><h5>1. 含有 be 动词的一般现在时。</h5>\n<p class=\"source-line\">结构: 主语 + be 动词(am / is / are) + 表语(+其他).</p>\n<p class=\"source-line\">I am a boy. 我是一个男孩儿。</p>\n<p class=\"source-line\">It is cloudy today. 今天多云。</p>\n<h5>2. 含有实义动词的一般现在时。</h5>\n<p class=\"source-line\">结构: 主语+实义动词(+其他).</p>\n<p class=\"source-line\">It works well. 它运转正常。</p>\n<p class=\"source-line\">She goes to work by bike every day. 她每天骑自行车去上班。</p></div></div>\n<div class=\"g\"><div class=\"gt\">动词第三人称单数形式的变化规则</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>变化规则</th>\n<th>例词</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>一般情况下,在词尾直接加s</td>\n<td>run — runs<br>like — likes</td>\n</tr>\n<tr>\n<td>以s、x、sh、ch、o结尾的动词,在词尾加es</td>\n<td>pass — passes<br>teach — teaches</td>\n</tr>\n<tr>\n<td>以辅音字母加y结尾的动词,把y变i,再加es</td>\n<td>try — tries<br>study — studies</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">（1）以元音字母加 y 结尾的动词，在词尾加 s，如：pay — pays、play — plays 等。</p>\n<p class=\"source-line\">（2）have 的第三人称单数形式是 has。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【北京·丰台区】用所给词的适当形式填空。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">I ____ (want) to be a teacher. But he ____ (want) to be a doctor.</p>", "options": [], "correct": null, "answer": "want, wants<br>"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">Andy and I ____ (watch) TV every Sunday.</p>", "options": [], "correct": null, "answer": "watch<br>"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">Mary usually ____ (get) up at 6:30 in the morning.</p>", "options": [], "correct": null, "answer": "gets"}, {"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\">My parents often ____ (go) to the supermarket on Sundays.</p>", "options": [], "correct": null, "answer": "go"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【佛山·三水区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">Alice ____ a student. I ____ a worker. They ____ drivers.</p>", "options": ["are ; is ; am", "is ; am ; are", "am ; is ; are"], "correct": 1, "answer": "B<br>\n解析：第一句主语 Alice (艾丽斯) 是第三人称单数, 故 be 动词用 is; 第二句主语 I (我) 是第一人称, 故 be 动词用 am; 第三句主语 They (他们) 是第三人称复数, 故 be 动词用 are。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">Jack and his mother ____ at the supermarket.</p>", "options": ["are", "is", "am"], "correct": 0, "answer": "A<br>\n解析：主语 Jack and his mother (杰克和他妈妈) 是复数, 故 be 动词用 are。"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">She ____ to bed at nine every night.</p>", "options": ["is", "go", "goes"], "correct": 2, "answer": "C"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">My brother ____ his homework every day.</p>", "options": ["does", "do", "is"], "correct": 0, "answer": "A"}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s24", "section": 24, "unit": 4, "unitName": "单元04 · 第19–24节", "short": "第24节 · L47–48", "title": "一般现在时（二）", "lessons": "Lesson 47 — Lesson 48", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>一般现在时(二)</td>\n<td>一般现在时的肯定句</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>一般现在时(二)</td>\n<td>一般现在时的否定句</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>一般现在时(二)</td>\n<td>一般现在时的一般疑问句</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n<tr>\n<td>一般现在时(二)</td>\n<td>一般现在时的特殊疑问句</td>\n<td>★★★★★</td>\n<td>★★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">一般现在时的肯定句</div><div class=\"gb\"><h5>1. 含有 be 动词的肯定句。</h5>\n<p class=\"source-line\">结构: 主语 + be 动词(am / is / are) + 表语(+其他).</p>\n<p class=\"source-line\">They are good friends.\n他们是好朋友。</p>\n<p class=\"source-line\">She is my English teacher. 她是我的英语老师。</p>\n<h5>2. 含有实义动词的肯定句。</h5>\n<p class=\"source-line\">结构: 主语+实义动词(+其他).</p>\n<p class=\"source-line\">I have a beautiful cup.</p>\n<p class=\"source-line\">我有一个漂亮的杯子。</p>\n<p class=\"source-line\">My mother goes to work by bus every day.</p>\n<p class=\"source-line\">我妈妈每天乘公共汽车去上班。</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般现在时的否定句</div><div class=\"gb\"><h5>1. 含有 be 动词的否定句。</h5>\n<p class=\"source-line\">结构: 主语 + be 动词(am / is / are) + not + 表语(+其他).</p>\n<p class=\"source-line\">She is not my sister. 她不是我姐姐。</p>\n<p class=\"source-line\">Those are not donkeys. 那些不是驴。</p>\n<h5>2. 含有实义动词的否定句。</h5>\n<p class=\"source-line\">结构: 主语+助动词(do / does) + not + 其他.</p>\n<p class=\"source-line\">I do not like tigers. 我不喜欢老虎。</p>\n<p class=\"source-line\">She does not like pears. 她不喜欢梨。</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般现在时的一般疑问句</div><div class=\"gb\"><h5>1. 含有 be 动词的一般疑问句。</h5>\n<p class=\"source-line\">结构: Be 动词(Am / Is / Are) + 主语 + 表语(+其他)?</p>\n<p class=\"source-line\">Is Mr White a writer? 怀特先生是一位作家吗?</p>\n<p class=\"source-line\">Is this your pen? 这是你的钢笔吗？</p>\n<h5>2. 含有实义动词的一般疑问句。</h5>\n<p class=\"source-line\">结构: Do / Does + 主语 + 动词原形 (+ 其他)?</p>\n<p class=\"source-line\">Do you like watermelons? 你喜欢西瓜吗？</p>\n<p class=\"source-line\">Does he read English every morning? 他每天早上读英语吗?</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般现在时的特殊疑问句</div><div class=\"gb\"><h5>1. 对地点提问。</h5>\n<p class=\"source-line\">Where is the supermarket? 超市在哪里?</p>\n<p class=\"source-line\">Where do you want to go? 你想去哪里？</p>\n<h5>2. 对时间提问。</h5>\n<p class=\"source-line\">When is your birthday? 你的生日在什么时候？</p>\n<p class=\"source-line\">What time do you usually get up? 你通常几点起床？</p>\n<h5>3. 对方式提问。</h5>\n<p class=\"source-line\">How does your mother go to work? 你妈妈怎么去上班?\nHow do you go to school? 你怎么上学?</p>\n<h5>4. 对人物提问。</h5>\n<p class=\"source-line\">Who is your Chinese teacher? 你的语文老师是谁?\nWho are they? 他们是谁?</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【天津·红桥区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">I often ____ school by bus.</p>", "options": ["going to", "goes to", "go to"], "correct": 2, "answer": "C<br>\n解析：主语 I(我) 是第一人称, 故后面的动词用原形 go。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ you like playing the guitar?</p>", "options": ["Do", "Are", "Does"], "correct": 0, "answer": "A<br>\n解析：主语 you (你 / 你们) 是第二人称, 谓语动词是实义动词, 故用助动词 Do。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">What ____ they usually ____ on Sundays?</p>", "options": ["do; does", "do; do", "does; do"], "correct": 1, "answer": "B<br>\n解析：这是 what 引导的特殊疑问句, 主语 they (他们) 是第三人称复数, 故助动词用 do, 第二个空根据句意选择实义动词 do (做; 干)。"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">How ____ Andy go to school every day?</p>", "options": ["do", "is", "does"], "correct": 2, "answer": "C<br>\n解析：这是 how 引导的特殊疑问句, 主语 Andy (安迪) 是第三人称单数, 谓语动词是实义动词, 故助动词用 does。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">My mother usually ____ clothes on Sundays.</p>", "options": ["wash", "washes", "washing"], "correct": 1, "answer": "B<br>\n解析：主语是第三人称单数, 故后面的动词用单三形式。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">____ those tomatoes?</p>", "options": ["Do", "Is", "Are"], "correct": 2, "answer": "C<br>\n解析：句中没有实义动词, 主语 those (那些) 表示复数, 故用 be 动词 are。"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">Does he ____ dinner at home?</p>", "options": ["having", "had", "have"], "correct": 2, "answer": "C<br>\n解析：由 does 引导的一般疑问句,后面的动词用原形,故用 have。"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">Alice ____ to learn cooking.</p>", "options": ["wants", "want", "want to"], "correct": 0, "answer": "A<br>\n解析：主语是第三人称单数, 故后面的动词用单三形式。"}], "questionCount": 8, "hasAnswers": true}]}, {"id": "s25", "section": 25, "unit": 5, "unitName": "单元05 · 第25–30节", "short": "第25节 · L49–50", "title": "选择疑问句", "lessons": "Lesson 49 — Lesson 50", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>选择疑问句</td>\n<td>概念</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>选择疑问句</td>\n<td>一般疑问句式的选择疑问句</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>选择疑问句</td>\n<td>特殊疑问句式的选择疑问句</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>选择疑问句</td>\n<td>选择疑问句的回答</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>选择疑问句</td>\n<td>but的用法</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">什么是选择疑问句？</div><div class=\"gb\"><p class=\"source-line\">选择疑问句是指提出两个或两个以上可能的答案供对方选择的句式。</p>\n<p class=\"source-line\">—— Do you want beef or mutton? 你想要牛肉还是羊肉？<br>\n—— Would you like an apple or a banana? 你想要一个苹果还是一根香蕉？<br>\n—— Beef, please. 牛肉。<br>\n—— An apple, please. 一个苹果。</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般疑问句式的选择疑问句</div><div class=\"gb\"><p class=\"source-line\">句型结构:一般疑问句+or+可选择内容?</p>\n<p class=\"source-line\">Are you in Class Three or Class Four?</p>\n<p class=\"source-line\">你在3班还是4班？</p>\n<p class=\"source-line\">Is he thirteen or fourteen? 他13岁还是14岁?</p></div></div>\n<div class=\"g\"><div class=\"gt\">特殊疑问句式的选择疑问句</div><div class=\"gb\"><p class=\"source-line\">句型结构: 特殊疑问句, 可选择内容 A + or + 可选择内容 B?</p>\n<p class=\"source-line\">Which do you prefer, tea or coffee?</p>\n<p class=\"source-line\">你更喜欢哪个,茶还是咖啡?</p>\n<p class=\"source-line\">How can we go to the park, by bus or by taxi?</p>\n<p class=\"source-line\">我们可以怎样去公园,乘坐公共汽车还是乘坐出租车?</p></div></div>\n<div class=\"g\"><div class=\"gt\">选择疑问句的回答</div><div class=\"gb\"><p class=\"source-line\">选择疑问句的回答不用 yes 或 no, 而是根据实际情况进行回答。</p>\n<p class=\"source-line\">—— Are your shoes red or blue? 你的鞋是红色的还是蓝色的？<br>\n—— They are red. 它们是红色的。</p>\n<p class=\"source-line\">:::tip title=\"口诀\"\n选择问句真奇妙，一般问句加上 or；or 的前后要对称，朗读时前升后降。\n:::</p></div></div>\n<div class=\"g\"><div class=\"gt\">but 的用法</div><div class=\"gb\"><p class=\"source-line\">but 用于“肯定句+否定句”或“否定句+肯定句”中, 连接相反意思的词、短语或句子, 表示转折关系, 意为 “但是”。</p>\n<p class=\"source-line\">He likes steak, but he doesn't like chicken.</p>\n<p class=\"source-line\">他喜欢牛排,但是他不喜欢鸡肉。</p>\n<p class=\"source-line\">He likes steak, but I don't.</p>\n<p class=\"source-line\">他喜欢牛排，但是我不喜欢。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】选择题：选择正确答案。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">I like water ____ I don't like cola.</p>", "options": ["and", "but"], "correct": 1, "answer": "B<br>\n解析：“I like water” 为肯定句, 意为 “我喜欢水”; “I don’t like cola” 为否定句, 意为 “我不喜欢可乐”。前后句是转折关系, 表转折用 but。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">It will be warm ____ sunny on Friday.</p>", "options": ["but", "and"], "correct": 1, "answer": "B<br>\n解析：和第 3 题中的形容词都是并列关系, 可以用 and。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">I like cold ____ snowy days.</p>", "options": ["and", "but"], "correct": 0, "answer": "A"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">I like ice cream ____ I like cake.</p>", "options": ["but", "and"], "correct": 1, "answer": "B<br>\n解析：“I like ice cream” 为肯定句, “I like cake” 为肯定句, 前后句是并列关系, 用 and。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">I like cake ____ I don't like ice cream.</p>", "options": ["and", "but"], "correct": 1, "answer": "B<br>\n解析：“I like cake”为肯定句，“I don’t like ice cream”为否定句，前后句是转折关系，用 but。"}], "questionCount": 5, "hasAnswers": true}, {"title": "【真题锦囊】【佛山·禅城区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">I have a brother ____ two sisters, ____ I don't have cousins.</p>", "options": ["but; and", "and; and", "and; but"], "correct": 2, "answer": "C<br>\n解析：前半句中 a brother (一个兄弟) 和 two sisters (两个姐妹) 表示并列关系, 用 and 连接; 前后句是转折关系, 用 but。故此题选择 C 选项。"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">David likes ____ model planes, ____ Mike doesn't.</p>", "options": ["make; but", "making; but", "make; and"], "correct": 1, "answer": "B<br>\n解析：like (喜欢) 后接动词 -ing 形式或动词不定式, make (制作) 的 -ing 形式为 making。前后句是转折关系, 用 but。故此题选择 B 选项。"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Do you like orange juice ____ grape juice?<br>\n—— I like orange juice.</p>", "options": ["or", "so", "but"], "correct": 0, "answer": "A<br>\n解析：问句是选择疑问句。orange juice (橙汁) 和 grape juice (葡萄汁) 用 or 连接。故此题选择 A 选项。"}, {"number": 9, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Would you like tea ____ milk?<br>\n—— I don't like tea ____ milk. I'd like some coffee.</p>", "options": ["and; and", "and; or", "or; or"], "correct": 2, "answer": "C<br>\n解析：问句是选择疑问句。tea(茶)和 milk(牛奶)用 or 连接。答语为否定句,否定句中连接两种事物用 or,而不用 and。故此题选择 C 选项。"}, {"number": 10, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ you want these ____ those?<br>\n—— I want these.</p>", "options": ["Do; and", "Are; or", "Do; or"], "correct": 2, "answer": "C<br>\n解析：you (你)为第二人称, want (想要)为实义动词, 所以用助动词 do 提问。问句为选择疑问句, these (这些)和 those (那些)用 or 连接。故此题选择 C 选项。"}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s26", "section": 26, "unit": 5, "unitName": "单元05 · 第25–30节", "short": "第26节 · L51–52", "title": "关于 what 的句型", "lessons": "Lesson 51 — Lesson 52", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>关于what的句型</td>\n<td>句型“What's ... like?”</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>关于what的句型</td>\n<td>句型“What do / does ... like?”</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">句型 What's ... like?</div><div class=\"gb\"><p class=\"source-line\">句型结构1：</p>\n<p class=\"source-line\">（1）What's + 主语 + like?（询问某人的性格特征或外貌特点）</p>\n<p class=\"source-line\">（2）主语 + is + 描述性格特征或外貌特点的形容词。</p>\n<p class=\"source-line\">—— What's your mother like? 你妈妈什么样？<br>\n—— She is very kind. 她很和蔼。<br>\n—— What's his English teacher like? 他的英语老师什么样？<br>\n—— She is very strict. 她很严厉。</p>\n<p class=\"source-line\">句型结构2：</p>\n<p class=\"source-line\">（1）What's the weather like (in) ...?</p>\n<p class=\"source-line\">（2）It's + 描述天气状况的形容词。</p>\n<p class=\"source-line\">—— What's the weather like in Beijing? 北京的天气怎么样？<br>\n—— It's sunny. 天气阳光明媚。<br>\n—— What's the weather like there? 那里的天气怎么样？<br>\n—— It's cloudy. 天气多云。</p></div></div>\n<div class=\"g\"><div class=\"gt\">句型 “What do / does ... like?”</div><div class=\"gb\"><p class=\"source-line\">句型结构：</p>\n<p class=\"source-line\">（1）What do / does + 主语 + like?</p>\n<p class=\"source-line\">（2）主语 + like / likes + 其他。</p>\n<p class=\"source-line\">—— What do you like? 你喜欢什么？<br>\n—— I like peaches. 我喜欢桃子。<br>\n—— What does your mother like? 你妈妈喜欢什么？<br>\n—— She likes singing. 她喜欢唱歌。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【合肥·包河区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ is he like?<br>\n—— He is strict.</p>", "options": ["Who", "What", "Which"], "correct": 1, "answer": "B<br>\n解析：根据句型 “What be + 主语 + like?” 可知选 What。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">My aunt ____ strawberries.</p>", "options": ["like", "liked", "likes"], "correct": 2, "answer": "C<br>\n解析：主语 my aunt 是第三人称单数, 实义动词用单三形式 likes。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">It's ____ and ____ in London.</p>", "options": ["snowy; hot", "warm; snowy", "snowy; cold"], "correct": 2, "answer": "C<br>\n解析：根据生活常识可知 “下雪时天气寒冷”,故选 snowy 和 cold。"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">I don't like ____ days.</p>", "options": ["snowy", "snowing", "snows"], "correct": 0, "answer": "A<br>\n解析：day(天)是名词, 故用形容词 snowy 修饰。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">What ____ the weather like today?</p>", "options": ["is", "are", "am"], "correct": 0, "answer": "A<br>\n解析：根据句型 “What is the weather like(+其他)?” 可知选 is。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">I like ____ days.</p>", "options": ["cloudy", "clouds", "clouding"], "correct": 0, "answer": "A<br>\n解析：day(天)是名词, 故用形容词 cloudy 修饰。"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">What ____ your uncle like?</p>", "options": ["do", "does", "did"], "correct": 1, "answer": "B<br>\n解析：主语 your uncle 是第三人称单数, 助动词用 does。"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">It's ____ today.</p>", "options": ["suns", "sun", "sunny"], "correct": 2, "answer": "C<br>\n解析：根据句型“It's + 描述天气的形容词.”可知选sunny。"}], "questionCount": 8, "hasAnswers": true}]}, {"id": "s27", "section": 27, "unit": 5, "unitName": "单元05 · 第25–30节", "short": "第27节 · L53–54", "title": "频度副词", "lessons": "Lesson 53 — Lesson 54", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>频度副词</td>\n<td>概念</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>频度副词</td>\n<td>常见频度副词所表示的频率</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>频度副词</td>\n<td>频度副词的位置</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">什么是频度副词？</div><div class=\"gb\"><p class=\"source-line\">频度副词又称频率副词,用来表示动作、事情发生的频率,即某事多长时间发生一次,通常用于一般现在时的句子中。</p>\n<p class=\"source-line\">Ben often goes to the cinema with his friend.</p>\n<p class=\"source-line\">本经常和他的朋友去看电影。</p>\n<p class=\"source-line\">He never eats hamburgers. 他从不吃汉堡包。</p></div></div>\n<div class=\"g\"><div class=\"gt\">常见频度副词所表示的频率</div><div class=\"gb\"><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>频率</th>\n<th>频度副词</th>\n<th>含义</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>100%</td>\n<td>always</td>\n<td>(总是)</td>\n</tr>\n<tr>\n<td>90%</td>\n<td>usually</td>\n<td>(通常)</td>\n</tr>\n<tr>\n<td>70%</td>\n<td>often</td>\n<td>(经常)</td>\n</tr>\n<tr>\n<td>50%</td>\n<td>sometimes</td>\n<td>(有时)</td>\n</tr>\n<tr>\n<td>10%</td>\n<td>seldom</td>\n<td>(很少)</td>\n</tr>\n<tr>\n<td>5%</td>\n<td>hardly</td>\n<td>(几乎不)</td>\n</tr>\n<tr>\n<td>0</td>\n<td>never</td>\n<td>(从不)</td>\n</tr>\n</tbody>\n</table></div></div></div>\n<div class=\"g\"><div class=\"gt\">频度副词的位置</div><div class=\"gb\"><h5>1. 在句中放在实义动词前面。</h5>\n<p class=\"source-line\">I always go to school by bike.</p>\n<p class=\"source-line\">我总是骑自行车去上学。</p>\n<p class=\"source-line\">My sister often does exercise.</p>\n<p class=\"source-line\">我妹妹经常锻炼。</p>\n<h5>2. 一般放在 be(动词)、助动词和情态动词后面。</h5>\n<p class=\"source-line\">I am never late for school.</p>\n<p class=\"source-line\">我上学从不迟到。</p>\n<p class=\"source-line\">I can hardly say a word.</p>\n<p class=\"source-line\">我几乎说不出一个字。</p>\n<p class=\"source-line\">:::tip title=\"口诀\"\n频度副词很重要，句中位置要记牢：实义动词前，be 动词、助动词和情态动词后；sometimes 较灵活，也可用于句首或句末。\n:::</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【惠州·惠城区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— How often do you go to the cinema?<br>\n—— ____. I only watch movies at home.</p>", "options": ["Always", "Usually", "Sometimes", "Never"], "correct": 3, "answer": "D<br>\n解析：根据句意可知回答者从不去电影院,故选择 D 选项。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— How often do you go to work by subway?<br>\n—— ____. I always take a bus, because there is no subway in this city.</p>", "options": ["Sometimes", "Often", "Never", "Seldom"], "correct": 2, "answer": "C<br>\n解析：根据句意可知回答者从未乘坐过地铁，故选择C选项。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">Tina ____ drives to work. But today she drives because of rain.</p>", "options": ["always", "often", "sometimes", "hardly ever"], "correct": 3, "answer": "D<br>\n解析：后一句中, but 表转折, 故前一句 Tina 不常开车, D 选项 hardly ever 符合题意。"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">I am ____ late for school because I get up early every day.</p>", "options": ["sometimes", "often", "never", "usually"], "correct": 2, "answer": "C<br>\n解析：“because I get up early every day”意为“因为我每天起得早”，说明回答者从未迟到，故本题选择 C 选项。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Do you play computer games?<br>\n—— No, ____. I think they're boring.</p>", "options": ["always", "never", "usually", "often"], "correct": 1, "answer": "B<br>\n解析：根据 “I think they’re boring. (我认为它们很无聊。)” 可知回答者从不玩儿电脑游戏,故本题选择 B 选项。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">The boy is very lazy. He ____ washes his shoes.</p>", "options": ["always", "usually", "hardly ever", "often"], "correct": 2, "answer": "C<br>\n解析：由前一句 “这个男孩儿非常懒” 可知后一句大意为 “他几乎不刷鞋”, 故本题选择 C 选项。"}], "questionCount": 6, "hasAnswers": true}, {"title": "【真题锦囊】【合肥·包河区】排序题：将下列句子重新排序，组成完整对话。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">E. Let's go shopping together next Saturday.</p>", "options": ["I usually watch TV. Sometimes I go shopping. What about you?", "Hi, Lily! What do you do on the weekend?", "Great!", "I often clean my room. Sometimes I go shopping too."], "correct": 1, "answer": "B—A—D—E—C"}], "questionCount": 1, "hasAnswers": true}]}, {"id": "s28", "section": 28, "unit": 5, "unitName": "单元05 · 第25–30节", "short": "第28节 · L55–56", "title": "动词的第三人称单数", "lessons": "Lesson 55 — Lesson 56", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>动词的第三人称单数</td>\n<td>概念</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>动词的第三人称单数</td>\n<td>动词第三人称单数的变化规则</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<h5>1. 什么是第三人称单数？</h5>\n<p class=\"source-line\">第一人称:I / we</p>\n<p class=\"source-line\">第二人称:you</p>\n<p class=\"source-line\">第三人称: he / she / it / they</p>\n<p class=\"source-line\">“单” → 单数</p>\n<h5>2. 怎样判断主语是不是“单三”？</h5>\n<p class=\"source-line\">满足“三非”即可！</p>\n<p class=\"source-line\">非你非我非复数即是“单三”！</p>\n<p class=\"source-line\">单三: Mary、my mother、the cat</p>\n<p class=\"source-line\">非单三: they (第三人称复数)、my teachers (第三人称复数)、I (第一人称单数)、we (第一人称复数)、you (第二人称单数 / 复数)</p>\n<h5>3. 在一般现在时的句子中,当主语是第三人称单数时,谓语动词要用第三人称单数形式。</h5><div class=\"g\"><div class=\"gt\">动词第三人称单数的变化规则</div><div class=\"gb\"><h5>1. 一般情况下,在词尾直接加 s。</h5>\n<p class=\"source-line\">run → runs 跑</p>\n<p class=\"source-line\">speak → speaks 说,讲话</p>\n<p class=\"source-line\">like → likes 喜欢<br />\nsing → sings 唱歌</p>\n<p class=\"source-line\">My sister likes ice cream. 我姐姐喜欢冰激凌。</p>\n<p class=\"source-line\">My mother always cooks delicious food for us.</p>\n<p class=\"source-line\">我妈妈总是为我们做美味的食物。</p>\n<h5>2. 以 ch、sh、s、x、o 结尾的动词，在词尾加 es。</h5>\n<p class=\"source-line\">teach → teaches 讲授,教授</p>\n<p class=\"source-line\">do → does 做, 干</p>\n<p class=\"source-line\">pass → passes 给;递</p>\n<p class=\"source-line\">My brother usually does housework at home. 我哥哥在家通常做家务。</p>\n<p class=\"source-line\">wash → washes 洗;洗涤</p>\n<p class=\"source-line\">Miss Wang teaches us Chinese.</p>\n<p class=\"source-line\">王老师教我们语文。</p>\n<h5>3. 以辅音字母加 y 结尾的动词, 把 y 变 i, 再加 es。</h5>\n<p class=\"source-line\">try → tries 试图;想要</p>\n<p class=\"source-line\">fly → flies 飞</p>\n<p class=\"source-line\">study → studies 学习,研究</p>\n<p class=\"source-line\">marry → marries 结婚</p>\n<p class=\"source-line\">My little sister studies very hard.</p>\n<p class=\"source-line\">我妹妹学习很努力。</p>\n<p class=\"source-line\">The bird flies very high.</p>\n<p class=\"source-line\">那只鸟飞得很高。</p>\n<p class=\"source-line\">（1）以“元音字母+y”结尾的动词，在词尾加s，如pay—pays、play—plays等。</p>\n<p class=\"source-line\">（2）have 的第三人称单数形式是 has。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【天津·红桥区】用所给词的适当形式填空。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">She ____ (like) strawberries.</p>", "options": [], "correct": null, "answer": "likes<br>"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">My cousin ____ (speak) English very well.</p>", "options": [], "correct": null, "answer": "speaks"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">Mr Green often ____ (wash) his car on Sundays.</p>", "options": [], "correct": null, "answer": "washes"}, {"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\">Andy can ____ (swim).</p>", "options": [], "correct": null, "answer": "swim<br>"}, {"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">Alice always ____ (do) housework on Saturdays.</p>", "options": [], "correct": null, "answer": "does<br>"}, {"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">He often ____ (go) to school by bike.</p>", "options": [], "correct": null, "answer": "goes"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">My aunt ____ (look) after her baby carefully.</p>", "options": [], "correct": null, "answer": "looks"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">They always ____ (do) their homework quickly.</p>", "options": [], "correct": null, "answer": "do<br>"}], "questionCount": 8, "hasAnswers": true}]}, {"id": "s29", "section": 29, "unit": 5, "unitName": "单元05 · 第25–30节", "short": "第29节 · L57–58", "title": "现在进行时和一般现在时", "lessons": "Lesson 57 — Lesson 58", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>现在进行时和一般现在时</td>\n<td>现在进行时</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>现在进行时和一般现在时</td>\n<td>一般现在时</td>\n<td>★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>现在进行时和一般现在时</td>\n<td>现在进行时和一般现在时的区别</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">现在进行时</div><div class=\"gb\"><h5>1. 含义: 表示现在正在进行或发生的动作。</h5>\n<h5>2. 肯定句结构: 主语 + be (am / is / are) + 动词 -ing 形式 (+ 其他).</h5>\n<h5>3. 动词 -ing 形式的构成</h5>\n<p class=\"source-line\">（1）一般情况下,直接加 ing。如:read — reading</p>\n<p class=\"source-line\">（2）以不发音的 e 结尾的动词,去 e 加 ing。如:make — making</p>\n<p class=\"source-line\">（3）以重读闭音节结尾,且词尾只有一个辅音字母的动词,双写词尾辅音字母再加ing。如:run—running、plan—planning。</p>\n<p class=\"source-line\">（4）有些以 ie 结尾的动词,变 ie 为 y,再加 ing。如:lie — lying</p>\n<h5>4. 用法</h5>\n<p class=\"source-line\">（1）表示说话时正在发生的事情, 常与 now、at present 等时间状语连用。</p>\n<p class=\"source-line\">Sarah is singing now. 萨拉现在正在唱歌。</p>\n<p class=\"source-line\">Look! Mike is doing his homework.</p>\n<p class=\"source-line\">看！迈克正在做作业。</p>\n<p class=\"source-line\">（2）表示当前一段时间内正在进行的动作, 说话时不一定进行。</p>\n<p class=\"source-line\">Three bees are flying from flowers to flowers this afternoon.</p>\n<p class=\"source-line\">三只蜜蜂今天下午在花丛中飞来飞去。</p></div></div>\n<div class=\"g\"><div class=\"gt\">一般现在时</div><div class=\"gb\"><h5>1. 含义: 表示经常发生的动作或存在的状态。</h5>\n<h5>2. 肯定句结构</h5>\n<p class=\"source-line\">主语 + 情态动词 + 动词原形（+ 其他）；或：主语 + 动词原形／动词第三人称单数形式（+ 其他）。</p>\n<h5>3. 动词第三人称单数形式的构成</h5>\n<p class=\"source-line\">（1）一般情况下,在动词词尾直接加 s。如:like — likes</p>\n<p class=\"source-line\">（2）以 s、x、sh、ch、o 结尾的动词,加 es。如: watch — watches、do — does。</p>\n<p class=\"source-line\">（3）以“辅音字母+y”结尾的动词,先变y为i,再加es。如:study—studies</p>\n<p class=\"source-line\">（4）不规则变化。如:have—has</p>\n<h5>4. 用法</h5>\n<p class=\"source-line\">（1）表示经常性或习惯性的动作; 常与 always、often、usually、every day 等词语连用。</p>\n<p class=\"source-line\">She studies English every day. 她每天学习英语。</p>\n<p class=\"source-line\">Jack often takes a bath at night. 杰克经常在晚上洗澡。</p>\n<p class=\"source-line\">（2）表示永恒不变的真理或描述一般性的事实。</p>\n<p class=\"source-line\">The sun rises in the east. 太阳从东边升起。</p>\n<p class=\"source-line\">Three and five is eight. 3 加 5 等于 8。</p></div></div>\n<div class=\"g\"><div class=\"gt\">现在进行时和一般现在时的区别</div><div class=\"gb\"><p class=\"source-line\">肯定句: He is reading an interesting book. 他正在读一本有趣的书。</p>\n<p class=\"source-line\">He reads an interesting book. 他读一本有趣的书。</p>\n<p class=\"source-line\">否定句: He isn't reading an interesting book. 他没在读一本有趣的书。\nHe doesn't read an interesting book. 他没读一本有趣的书。</p>\n<p class=\"source-line\">一般疑问句: Is he reading an interesting book? 他正在读一本有趣的书吗?\nDoes he read an interesting book? 他读一本有趣的书吗?</p>\n<p class=\"source-line\">特殊疑问句: What is he doing?</p>\n<p class=\"source-line\">他正在做什么？</p>\n<p class=\"source-line\">What does he do?</p>\n<p class=\"source-line\">他做什么？</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【佛山·顺德区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— What ____ they often ____ on Sundays?<br>\n—— They often play football on Sundays.</p>", "options": ["does; do", "do; does", "do; do"], "correct": 2, "answer": "C<br>\n解析：主语 they (他们) 为第三人称复数, 助动词用 do, 第二个 do 为实义动词, 用原形。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— What ____ they doing?<br>\n—— They are ____ their hair.</p>", "options": ["are; cutting", "do; cut", "is; cutting"], "correct": 0, "answer": "A"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">Look! The mice ____ through the grass.</p>", "options": ["is running", "run", "are running"], "correct": 2, "answer": "C<br>\n解析：look (看) 是现在进行时的标志词。mice (老鼠) 是 mouse 的复数形式, 所以 be 用 are, be 后接动词 -ing 形式。"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">Jill and her friend often ____ hiking on the weekend.</p>", "options": ["went", "go", "goes"], "correct": 1, "answer": "B"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ she ____ her homework?<br>\n—— No, she isn't.</p>", "options": ["Is; doing", "Does; do", "Is; do"], "correct": 0, "answer": "A<br>\n解析：根据答语可知问句是 is 引导的一般疑问句, 后接动词 -ing 形式。"}], "questionCount": 5, "hasAnswers": true}, {"title": "【真题锦囊】【昆明·官渡区】用所给词的适当形式填空。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">Sam often ____ (clean) his bedroom on the weekend.</p>", "options": [], "correct": null, "answer": "cleans"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">Look! Lily and Bob ____ (skate).</p>", "options": [], "correct": null, "answer": "are skating<br>"}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">Each girl ____ (have) a dream.</p>", "options": [], "correct": null, "answer": "has"}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">Jim always ____ (do) his homework in the evening.</p>", "options": [], "correct": null, "answer": "does"}, {"number": 10, "type": "input", "questionHtml": "<p class=\"source-line\">Don't talk! My baby Bill ____ (sleep) in the bedroom.</p>", "options": [], "correct": null, "answer": "is sleeping<br>"}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s30", "section": 30, "unit": 5, "unitName": "单元05 · 第25–30节", "short": "第30节 · L59–60", "title": "have 的用法", "lessons": "Lesson 59 — Lesson 60", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>have 的用法</td>\n<td>have 的用法</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>have 的用法</td>\n<td>have 和 there be 的用法对比</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">have 的用法</div><div class=\"gb\"><h5>1. have 作实义动词, 表示 “有”。</h5>\n<p class=\"source-line\">I have a new pen. 我有一支新钢笔。</p>\n<p class=\"source-line\">She has an apple. 她有一个苹果。</p>\n<h5>2. have 作实义动词, 表示 “吃, 喝”。</h5>\n<p class=\"source-line\">I have breakfast at 6:30 every morning.</p>\n<p class=\"source-line\">我每天早上6:30吃早餐。</p>\n<p class=\"source-line\">She often has rice and fish for dinner.</p>\n<p class=\"source-line\">她晚餐经常吃米饭和鱼肉。</p>\n<h5>3. have 与 to 一起构成情态动词, 表示 “不得不; 必须”。</h5>\n<p class=\"source-line\">I have to finish my homework.</p>\n<p class=\"source-line\">我不得不完成我的家庭作业。</p>\n<p class=\"source-line\">She has to look after her younger sister at home today.</p>\n<p class=\"source-line\">她今天必须在家照顾她妹妹。</p></div></div>\n<div class=\"g\"><div class=\"gt\">have 和 there be 的用法对比</div><div class=\"gb\"><h5>1. have 表示 “某人 / 某物拥有……”, 强调 “拥有”。</h5>\n<p class=\"source-line\">I have some pears. 我有一些梨。</p>\n<p class=\"source-line\">The table has three legs. 这张桌子有 3 条腿。</p>\n<h5>2. there be 表示某处有某人 / 某物, 强调 “存在”。</h5>\n<p class=\"source-line\">There are some pears on the table.</p>\n<p class=\"source-line\">桌子上有一些梨。</p>\n<p class=\"source-line\">There are some people in the park.</p>\n<p class=\"source-line\">公园里有一些人。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【昆明·五华区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">Does Alice ____ many friends?</p>", "options": ["have", "has", "there are"], "correct": 0, "answer": "A<br>\n解析：由助动词 does 引导的一般疑问句,后面的实义动词用原形,故选 have。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ a lot of food, milk and fruits in the fridge.</p>", "options": ["are", "am", "is"], "correct": 2, "answer": "C<br>\n解析：a lot of food (许多食物) 不可数, 故选 is。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">It ____ a short tail.</p>", "options": ["have", "has", "there is"], "correct": 1, "answer": "B<br>\n解析：主语 It(它) 是第三人称单数, 故后面的动词用单三形式 has。"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">How many watches ____ in the box?</p>", "options": ["there are", "there is", "are there"], "correct": 2, "answer": "C<br>\n解析：此句是特殊疑问句, watches(手表) 是可数名词复数, 故后面选择 are there。"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【北京·东城区】翻译下列句子。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">书桌上有一本书。</p>", "options": [], "correct": null, "answer": "There is a book on the desk."}, {"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">我姐姐有一个新杯子。</p>", "options": [], "correct": null, "answer": "My sister has a new cup."}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">床下面有一个篮球。</p>", "options": [], "correct": null, "answer": "There is a basketball under the bed."}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">那个小婴儿没有牙齿。</p>", "options": [], "correct": null, "answer": "The little baby has no teeth."}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s31", "section": 31, "unit": 6, "unitName": "单元06 · 第31–36节", "short": "第31节 · L61–62", "title": "系动词", "lessons": "Lesson 61 — Lesson 62", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>系动词</td>\n<td>be 动词</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>系动词</td>\n<td>感官连系动词</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">系动词</div><div class=\"gb\"><p class=\"source-line\">系动词也叫连系动词,不能单独作谓语,必须后接名词、形容词等表语一起作句子的谓语。be 动词是最基本的系动词。</p>\n<p class=\"source-line\">She is pretty. 她很漂亮。</p>\n<p class=\"source-line\">I am a football player. 我是一名足球运动员。</p></div></div>\n<div class=\"g\"><div class=\"gt\">be 动词</div><div class=\"gb\"><p class=\"source-line\">be 动词通常用来表示事物的性质或状态。根据主语的人称和单复数形式，be 动词可变化为 am、is、are。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>人称</th>\n<th>单数·主语</th>\n<th>单数·be 动词</th>\n<th>单数·缩写</th>\n<th>复数·主语</th>\n<th>复数·be 动词</th>\n<th>复数·缩写</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>第一人称</td>\n<td>I</td>\n<td>am</td>\n<td>I'm</td>\n<td>we</td>\n<td>are</td>\n<td>we're</td>\n</tr>\n<tr>\n<td>第二人称</td>\n<td>you</td>\n<td>are</td>\n<td>you're</td>\n<td>you</td>\n<td>are</td>\n<td>you're</td>\n</tr>\n<tr>\n<td>第三人称</td>\n<td>he</td>\n<td>is</td>\n<td>he's</td>\n<td>they</td>\n<td>are</td>\n<td>they're</td>\n</tr>\n<tr>\n<td>第三人称</td>\n<td>she</td>\n<td>is</td>\n<td>she's</td>\n<td>they</td>\n<td>are</td>\n<td>they're</td>\n</tr>\n<tr>\n<td>第三人称</td>\n<td>it</td>\n<td>is</td>\n<td>it's</td>\n<td>they</td>\n<td>are</td>\n<td>they're</td>\n</tr>\n</tbody>\n</table></div>\n<p class=\"source-line\">:::tip title=\"口诀\"\n我（I）用 am，你（you）用 are，is 连着他（he）、她（she）、它（it）；单数名词用 is，复数名词用 are。\n:::</p></div></div>\n<div class=\"g\"><div class=\"gt\">感官连系动词</div><div class=\"gb\"><p class=\"source-line\">除了 be 动词, 常用的系动词还有感官连系动词。</p>\n<p class=\"source-line\">look 看起来</p>\n<p class=\"source-line\">smell 闻起来</p>\n<p class=\"source-line\">taste 尝起来</p>\n<p class=\"source-line\">sound 听起来</p>\n<p class=\"source-line\">feel 摸起来</p>\n<p class=\"source-line\">His mother looks very young.</p>\n<p class=\"source-line\">他妈妈看起来很年轻。</p>\n<p class=\"source-line\">The flowers smell sweet.</p>\n<p class=\"source-line\">这些花儿闻起来很香。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【广州·天河区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">The strawberries ____ delicious. You can have a try.</p>", "options": ["drink", "taste", "sound"], "correct": 1, "answer": "B<br>\n解析：第一句意为 “草莓尝起来很美味”, 故本题选择 B 选项。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">I like this silk dress, and it ____ so soft and comfortable.</p>", "options": ["is feeling", "feels", "has felt"], "correct": 1, "answer": "B<br>\n解析：此句意为 “我喜欢这条丝绸裙子, 它摸起来柔软舒服”, 故选择 B 选项。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ some children singing and dancing in the yard.</p>", "options": ["is", "are", "has"], "correct": 1, "answer": "B<br>\n解析：some children (一些孩子) 为第三人称复数形式, be 用 are。"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">How old ____ she?</p>", "options": ["am", "is", "are"], "correct": 1, "answer": "B"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— ____ these your parents?<br>\n—— No, they are ____ uncle and aunt.</p>", "options": ["Is; me", "Are; me", "Are; my"], "correct": 2, "answer": "C"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">Look! There ____ some milk, two eggs and a few cakes on the table.</p>", "options": ["is", "are", "has"], "correct": 0, "answer": "A<br>\n解析：此句为 there be 句型, 句中有多个主语, 要遵循 “就近原则”。离 be 最近的主语 some milk (一些牛奶) 为不可数名词, 故 be 用 is。"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">The milk ____ sour. You'd better not drink it.</p>", "options": ["sounds", "tastes", "looks"], "correct": 1, "answer": "B"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">The number of the students in our class ____ thirty-nine.</p>", "options": ["is", "are", "have"], "correct": 0, "answer": "A<br>\n解析：“the number of...”意为“……的数量”，number 为主语，be 动词用 is。"}, {"number": 9, "type": "mcq", "questionHtml": "<p class=\"source-line\">The trip ____ really exciting to me. How I wish to go!</p>", "options": ["tastes", "smells", "sounds"], "correct": 2, "answer": "C"}, {"number": 10, "type": "mcq", "questionHtml": "<p class=\"source-line\">This apple looks nice but ____ sour.</p>", "options": ["touches", "feels", "tastes"], "correct": 2, "answer": "C"}], "questionCount": 10, "hasAnswers": true}]}, {"id": "s32", "section": 32, "unit": 6, "unitName": "单元06 · 第31–36节", "short": "第32节 · L63–64", "title": "情态动词 must", "lessons": "Lesson 63 — Lesson 64", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>情态动词 must</td>\n<td>情态动词的概念</td>\n<td>★★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>情态动词 must</td>\n<td>情态动词 must 的用法</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">情态动词的概念</div><div class=\"gb\"><p class=\"source-line\">情态动词本身有一定的词义,表示说话人对有关行为或事物的态度和看法,认为其可能、应该或必要等。</p>\n<p class=\"source-line\">常见的情态动词有 can（能）、may（可以）、need（需要）、must（必须）、should（应该）等。</p>\n<p class=\"source-line\">I can do Chinese kung fu.</p>\n<p class=\"source-line\">我会练中国功夫。</p>\n<p class=\"source-line\">May I borrow your pen?</p>\n<p class=\"source-line\">我可以借用你的钢笔吗？</p>\n<p class=\"source-line\">You needn't finish that work today.</p>\n<p class=\"source-line\">你不必今天做完那项工作。</p>\n<p class=\"source-line\">You must clean your bedroom on Sunday.</p>\n<p class=\"source-line\">你必须在星期日打扫你的卧室。</p>\n<p class=\"source-line\">You should study hard from now on.</p>\n<p class=\"source-line\">你应该从现在开始努力学习。</p></div></div>\n<div class=\"g\"><div class=\"gt\">情态动词 must 的用法</div><div class=\"gb\"><h5>1. must 表示说话人的主观意志, 意为 “必须, 一定”, 后接动词原形。</h5>\n<p class=\"source-line\">You must study English hard.</p>\n<p class=\"source-line\">你必须努力学习英语。</p>\n<p class=\"source-line\">I must go now.</p>\n<p class=\"source-line\">我现在必须走。</p>\n<h5>2. 含有 must 的肯定句结构: 主语 + must + 动词原形 (+ 其他).</h5>\n<p class=\"source-line\">You must listen to your teacher. 你必须听你老师(的话)。</p>\n<p class=\"source-line\">I must earn money. 我必须赚钱。</p>\n<h5>3. 含有 must 的否定句结构: 主语 + mustn't + 动词原形 (+ 其他).</h5>\n<p class=\"source-line\">You mustn't take photos here.</p>\n<p class=\"source-line\">你不得在这里拍照。</p>\n<p class=\"source-line\">You mustn't tell him about it.</p>\n<p class=\"source-line\">你一定不要告诉他这件事。</p>\n<h5>4. must 开头的一般疑问句结构: Must + 主语 + 动词原形 (+ 其他)?</h5>\n<p class=\"source-line\">肯定回答: Yes, 主语 + must.</p>\n<p class=\"source-line\">否定回答: No, 主语 + needn't.</p>\n<p class=\"source-line\">—— Must you go now? 你现在必须走吗？<br>\n—— Yes, I must. 是的, 我必须走。<br>\n—— No, I needn't. 不, 我不必走。</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【广州·天河区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">Even the top students can't work out this problem, so it ____ be very difficult.</p>", "options": ["can", "may", "must"], "correct": 2, "answer": "C<br>\n解析：此题想表达 “它一定很难”, 故选 must。"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Must I stay at the cinema?<br>\n—— No, you ____.</p>", "options": ["needn't", "mustn't", "don't"], "correct": 0, "answer": "A<br>\n解析：must 引导的一般疑问句, 否定回答为 “No, 主语 + needn't.”, 故选 needn't。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">Miss Zhang ____ be in Shanghai now, because she went to Beijing yesterday.</p>", "options": ["may", "can't", "needn't"], "correct": 1, "answer": "B<br>\n解析：此题想表达 “张小姐现在不可能在上海”, 故选 can't。"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">Cars ____ stop when the traffic lights turn red.</p>", "options": ["need", "can", "must"], "correct": 2, "answer": "C<br>\n解析：根据常识 “红灯车停”, 故选 must。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">Look out! The knife is very sharp, you ____ cut your finger.</p>", "options": ["need", "may", "must"], "correct": 1, "answer": "B"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— I can’t find my pen. ____ I use yours?<br>\n—— Sure, here you are.</p>", "options": ["May", "Must", "Need"], "correct": 0, "answer": "A"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Do you like poems?<br>\n—— Yes, I ____ read some poems.</p>", "options": ["must", "can", "need"], "correct": 1, "answer": "B"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— What ____ he do?<br>\n—— He can do kung fu.</p>", "options": ["can", "must", "may"], "correct": 0, "answer": "A"}], "questionCount": 8, "hasAnswers": true}]}, {"id": "s33", "section": 33, "unit": 6, "unitName": "单元06 · 第31–36节", "short": "第33节 · L65–66", "title": "反身代词", "lessons": "Lesson 65 — Lesson 66", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>反身代词</td>\n<td>反身代词的形式</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n<tr>\n<td>反身代词</td>\n<td>反身代词的用法</td>\n<td>★★</td>\n<td>★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">反身代词</div><div class=\"gb\"><p class=\"source-line\">反身代词是一种表示反身或强调的代词。即表示“我(们)自己、你(们)自己、他/她/它(们)自己”的代词称为反身代词。</p>\n<p class=\"source-line\">I made the hamburger by myself. 我自己做的汉堡包。</p>\n<p class=\"source-line\">Help yourselves, children.</p>\n<p class=\"source-line\">孩子们，随便吃点儿吧。</p></div></div>\n<div class=\"g\"><div class=\"gt\">反身代词的形式</div><div class=\"gb\"><p class=\"source-line\">反身代词第一、二人称是由“形容词性物主代词+self/selves”构成。第三人称是由“人称代词宾格+self/selves”构成。反身代词可作宾语、同位语等，但不可作主语。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>数</th>\n<th>第一人称</th>\n<th>第二人称</th>\n<th>第三人称</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>单数</td>\n<td>myself 我自己</td>\n<td>yourself 你自己</td>\n<td>himself / herself / itself 他 / 她 / 它自己</td>\n</tr>\n<tr>\n<td>复数</td>\n<td>ourselves 我们自己</td>\n<td>yourselves 你们自己</td>\n<td>themselves 他 / 她 / 它们自己</td>\n</tr>\n</tbody>\n</table></div></div></div>\n<div class=\"g\"><div class=\"gt\">反身代词的用法</div><div class=\"gb\"><h5>1. 主语与宾语同为一(群)人时,宾语用反身代词。</h5>\n<p class=\"source-line\">Sarah hurt herself while riding the bike.</p>\n<p class=\"source-line\">萨拉在骑自行车时弄伤了自己。</p>\n<h5>2. 用反身代词加强语气。</h5>\n<p class=\"source-line\">She cooked breakfast by herself.</p>\n<p class=\"source-line\">她自己做的早饭。</p>\n<h5>3. 和某些动词或介词共同构成固定短语。</h5>\n<p class=\"source-line\">by oneself 亲自</p>\n<p class=\"source-line\">for oneself 为自己</p>\n<p class=\"source-line\">enjoy oneself 玩儿得高兴</p>\n<p class=\"source-line\">help oneself 随意吃</p>\n<p class=\"source-line\">teach oneself 自学</p>\n<p class=\"source-line\">seat oneself 就座</p>\n<p class=\"source-line\">I can do housework by myself. 我能够自己做家务。</p>\n<p class=\"source-line\">:::tip title=\"口诀\"\n反身代词：第一、二人称由形容词性物主代词加 self／selves 构成，第三人称由人称代词宾格加 self／selves 构成；可作宾语、表语或同位语，不能作主语或定语。\n:::</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【佛山·顺德区】把下列句子变成复数形式。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">I teach myself English.（改为复数形式）</p>", "options": [], "correct": null, "answer": "We teach ourselves English."}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">He usually goes to school by himself.（改为复数形式）</p>", "options": [], "correct": null, "answer": "They usually go to school by themselves."}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">Do it yourself, my boy.（改为复数形式）</p>", "options": [], "correct": null, "answer": "Do it yourselves, my boys."}, {"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\">The little bird got out of the nest by itself.（改为复数形式）</p>", "options": [], "correct": null, "answer": "The little birds got out of the nest by themselves."}, {"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">The girl did all of these herself.（改为复数形式）</p>", "options": [], "correct": null, "answer": "The girls did all of these themselves."}], "questionCount": 5, "hasAnswers": true}, {"title": "【真题锦囊】【蚌埠·淮上区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">The cat can see ____ in the mirror.</p>", "options": ["it", "its", "itself", "him"], "correct": 2, "answer": "C"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">Tom painted the room all by ____, because he likes doing it.</p>", "options": ["yourself", "herself", "himself", "themselves"], "correct": 2, "answer": "C<br>\n解析：by oneself 为固定搭配, 主语 Tom [汤姆(男名)] 的反身代词为 himself, 故此题选择 C 选项。"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">Boys, don't touch the machine, or you may hurt ____.</p>", "options": ["myself", "themselves", "yourself", "yourselves"], "correct": 3, "answer": "D<br>\n解析：主语 boys(男孩们)为复数形式, 根据句意选择 yourselves(你们自己)。"}, {"number": 9, "type": "mcq", "questionHtml": "<p class=\"source-line\">I made the cake ____. Help ____, Tom.</p>", "options": ["ourselves; yourself", "myself; yourself", "myself; you", "me; him"], "correct": 1, "answer": "B<br>\n解析：此题意为“我自己做了蛋糕。汤姆,随意吃”。第一句主语I(我)为第一人称,所以反身代词用myself(我自己)。help yourself(随意吃)为固定搭配。故此题选择B选项。"}, {"number": 10, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Did she go to school when she was young?<br>\n—— No. She taught ____ at home.</p>", "options": ["herself", "her", "hers", "she"], "correct": 0, "answer": "A"}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s34", "section": 34, "unit": 6, "unitName": "单元06 · 第31–36节", "short": "第34节 · L67–68", "title": "含有 be 动词的一般过去时", "lessons": "Lesson 67 — Lesson 68", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>含有be动词的一般过去时</td>\n<td>概念</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>含有be动词的一般过去时</td>\n<td>含有be动词的一般过去时</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">一般过去时的概念</div><div class=\"gb\"><p class=\"source-line\">一般过去时表示过去发生的动作、行为或存在的状态。</p>\n<p class=\"source-line\">I was short two years ago. 我两年前很矮。</p>\n<p class=\"source-line\">My grandparents were teachers twenty years ago. 我的(外)祖父母20年前是老师。</p></div></div>\n<div class=\"g\"><div class=\"gt\">含有 be 动词的一般过去时</div><div class=\"gb\"><h5>1. 肯定句: 主语 + was / were + 其他.</h5>\n<p class=\"source-line\">I was tired last night. 我昨天晚上很累。</p>\n<p class=\"source-line\">There were some books there. 那里(曾经)有一些书。</p>\n<h5>2. 否定句: 主语 + was / were not + 其他.</h5>\n<p class=\"source-line\">Mike wasn't at home this morning.<br />\n迈克今天早上不在家。<br />\nThey weren't there yesterday.<br />\n他们昨天不在那里。</p>\n<p class=\"source-line\">was not 可缩写为 wasn't, were not 可缩写为 weren't。</p>\n<h5>3. 一般疑问句: Was / Were + 主语 + 其他?</h5>\n<p class=\"source-line\">肯定回答: Yes, 主语 + was / were.</p>\n<p class=\"source-line\">否定回答: No, 主语 + wasn't / weren't.</p>\n<p class=\"source-line\">—— Was he a driver? 他(以前)是司机吗?<br>\n—— Yes, he was. 是的，他是。<br>\n—— No, he wasn't. 不，他不是。<br>\n—— Were they doctors? 他们(以前)是医生吗?<br>\n—— Yes, they were. 是的,他们是。<br>\n—— No, they weren't. 不,他们不是。</p>\n<h5>4. 特殊疑问句:疑问词+was/were+主语(+其他)?</h5>\n<p class=\"source-line\">Where was the dog five days ago? 那只狗 5 天前在哪里？</p>\n<p class=\"source-line\">Where were they two years ago? 他们两年前在哪里？</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【惠州·惠城区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">I ____ a shy girl before.</p>", "options": ["were", "am", "was"], "correct": 2, "answer": "C"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">His pen ____ in the pencil box last night.</p>", "options": ["is", "was", "were"], "correct": 1, "answer": "B"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">There ____ enough milk at home last week.</p>", "options": ["was", "were", "is"], "correct": 0, "answer": "A"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">It ____ hot yesterday.</p>", "options": ["is", "are", "was"], "correct": 2, "answer": "C"}], "questionCount": 4, "hasAnswers": true}, {"title": "【真题锦囊】【玉溪·红塔区】按要求完成下列句子。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">The monkeys were in the tree. (改为否定句)</p>", "options": [], "correct": null, "answer": "The monkeys weren't in the tree."}, {"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">My pens were in the desk. (改为一般疑问句)</p>", "options": [], "correct": null, "answer": "Were your pens in the desk?"}, {"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">My friends weren't happy last Sunday. (改为肯定句)</p>", "options": [], "correct": null, "answer": "My friends were happy last Sunday."}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">Paper was very expensive many years ago. (改为否定句)</p>", "options": [], "correct": null, "answer": "Paper wasn't very expensive many years ago."}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s35", "section": 35, "unit": 6, "unitName": "单元06 · 第31–36节", "short": "第35节 · L69–70", "title": "表示时间的 at、in 和 on", "lessons": "Lesson 69 — Lesson 70", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>表示时间的 at、in 和 on</td>\n<td>介词 at</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>表示时间的 at、in 和 on</td>\n<td>介词 in</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n<tr>\n<td>表示时间的 at、in 和 on</td>\n<td>介词 on</td>\n<td>★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">at 的用法</div><div class=\"gb\"><h5>1. at 后接具体的时刻, 意为 “在某一时刻”。</h5>\n<p class=\"source-line\">At noon, the sun is high in the sky. 在中午，烈日当空。</p>\n<p class=\"source-line\">We work in the morning, and have lunch at 12 o'clock.</p>\n<p class=\"source-line\">我们在上午工作，在12:00吃午饭。</p>\n<h5>2. at 可放在短暂的时间前或某个节日前。</h5>\n<p class=\"source-line\">He went home at Chinese New Year.</p>\n<p class=\"source-line\">他在春节回家了。</p>\n<p class=\"source-line\">其他含有 at 的短语:</p>\n<p class=\"source-line\">at the weekend 在周末</p>\n<p class=\"source-line\">at night 在晚上</p>\n<p class=\"source-line\">at last 最后</p>\n<p class=\"source-line\">at the end of... 在……的最后</p>\n<p class=\"source-line\">at midnight 在午夜</p></div></div>\n<div class=\"g\"><div class=\"gt\">in 的用法</div><div class=\"gb\"><p class=\"source-line\">in 后接一段时间, 意为 “在……期间”, 也可以放在表示年、季节、月、上午、下午、晚上等时间名词前。</p>\n<p class=\"source-line\">What's the weather like in spring? 春天天气怎么样?</p>\n<p class=\"source-line\">There are 31 days in August. 8月有31天。</p>\n<p class=\"source-line\">其他含有 in 的短语:</p>\n<p class=\"source-line\">in the future 在将来</p>\n<p class=\"source-line\">in one's life 在某人的一生中</p>\n<p class=\"source-line\">in the 1990s 在 20 世纪 90 年代</p>\n<p class=\"source-line\">in one's opinion 在某人看来</p>\n<p class=\"source-line\">in fact 事实上</p></div></div>\n<div class=\"g\"><div class=\"gt\">on 的用法</div><div class=\"gb\"><p class=\"source-line\">on 后接具体的某一天或特定的时间。</p>\n<p class=\"source-line\">Mike was born on a cold winter day.</p>\n<p class=\"source-line\">迈克出生在一个寒冷的冬日。</p>\n<h5>2. on 用在表示某一天的上午、下午、晚上的名词前。</h5>\n<p class=\"source-line\">We'll have a party on Sunday evening.</p>\n<p class=\"source-line\">我们将在星期日晚上举行聚会。</p>\n<p class=\"source-line\">:::tip title=\"口诀\"\n时间介词 in、on、at：in 年、in 月、in 季节；on 日、on 号、on 星期；at 用于具体时刻。泛指早午晚用 in，有具体修饰时用 on。\n:::</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【合肥·庐阳区】单项选择。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "mcq", "questionHtml": "<p class=\"source-line\">Mrs Brown came to China ____ 1996.</p>", "options": ["on", "of", "to", "in"], "correct": 3, "answer": "D"}, {"number": 2, "type": "mcq", "questionHtml": "<p class=\"source-line\">He often goes to school ____ six thirty ____ the morning.</p>", "options": ["to; in", "at; in", "for; at", "at; to"], "correct": 1, "answer": "B<br>\n解析：six thirty(6:30)为具体的时间点, 前用介词 at; in the morning(在早上)为固定搭配。故此题选择 B 选项。"}, {"number": 3, "type": "mcq", "questionHtml": "<p class=\"source-line\">A lot of students in our school were born ____ March, 2014.</p>", "options": ["in", "at", "on", "since"], "correct": 0, "answer": "A"}, {"number": 4, "type": "mcq", "questionHtml": "<p class=\"source-line\">He suddenly returned ____ a rainy night.</p>", "options": ["on", "at", "in", "during"], "correct": 0, "answer": "A<br>\n解析：a rainy night (一个雨夜) 表示具体的某一天的夜晚, 前用介词 on。"}, {"number": 5, "type": "mcq", "questionHtml": "<p class=\"source-line\">My grandfather was born ____ October 10th, 1964.</p>", "options": ["on", "in", "at", "of"], "correct": 0, "answer": "A<br>\n解析：October 10th, 1964 (1964 年 10 月 10 日) 表示具体的一天, 前用介词 on。"}, {"number": 6, "type": "mcq", "questionHtml": "<p class=\"source-line\">More and more people go skiing ____ winter.</p>", "options": ["in", "at", "on", "of"], "correct": 0, "answer": "A"}, {"number": 7, "type": "mcq", "questionHtml": "<p class=\"source-line\">Jim doesn't go to school ____ Sundays.</p>", "options": ["in", "at", "on", "to"], "correct": 2, "answer": "C"}, {"number": 8, "type": "mcq", "questionHtml": "<p class=\"source-line\">The students put on (上演) a short play ____ the Spring Festival.</p>", "options": ["in", "with", "on", "of"], "correct": 2, "answer": "C"}, {"number": 9, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— When is your father's birthday?<br>\n—— It's on ____.</p>", "options": ["December", "ten o'clock", "eight", "December 8th"], "correct": 3, "answer": "D"}, {"number": 10, "type": "mcq", "questionHtml": "<p class=\"source-line\">—— Does the autumn start ____ August?<br>\n—— Sometimes it does. But usually it starts ____ September.</p>", "options": ["in; in", "on; on", "at; at", "in; at"], "correct": 0, "answer": "A<br>\n解析：August(8 月)、September(9 月)都表示月份, 前用介词 in。"}], "questionCount": 10, "hasAnswers": true}]}, {"id": "s36", "section": 36, "unit": 6, "unitName": "单元06 · 第31–36节", "short": "第36节 · L71–72", "title": "含有实义动词的一般过去时的句子", "lessons": "Lesson 71 — Lesson 72", "knowledgeHtml": "<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>语法类别</th>\n<th>知识点</th>\n<th>新概念重要指数</th>\n<th>小升初重要指数</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>含有实义动词的一般过去时的句子</td>\n<td>动词过去式的构成规则</td>\n<td>★★</td>\n<td>★★</td>\n</tr>\n<tr>\n<td>含有实义动词的一般过去时的句子</td>\n<td>含有实义动词的一般过去时的句子</td>\n<td>★★★★</td>\n<td>★★★★</td>\n</tr>\n</tbody>\n</table></div>", "grammarHtml": "<div class=\"g\"><div class=\"gt\">动词过去式的构成规则</div><div class=\"gb\"><h5>1. 一般情况在动词词尾直接加 ed。</h5>\n<p class=\"source-line\">work — worked 工作</p>\n<p class=\"source-line\">jump — jumped 跳</p>\n<p class=\"source-line\">talk — talked 说话</p>\n<p class=\"source-line\">watch — watched 观看</p>\n<h5>2. 以不发音的 e 结尾的动词, 在词尾加 d。</h5>\n<p class=\"source-line\">like — liked 喜欢</p>\n<p class=\"source-line\">arrive — arrived 到达</p>\n<p class=\"source-line\">smile — smiled 微笑</p>\n<p class=\"source-line\">love — loved 爱</p>\n<h5>3. 以辅音字母加 y 结尾的动词, 把 y 变 i, 再加 ed。</h5>\n<p class=\"source-line\">study — studied 学习</p>\n<p class=\"source-line\">carry — carried 拿</p>\n<p class=\"source-line\">try — tried 试图</p>\n<h5>4. 以重读闭音节结尾的动词,末尾只有一个辅音字母时,双写这个辅音字母,再加 ed。</h5>\n<p class=\"source-line\">stop — stopped 停止</p>\n<p class=\"source-line\">plan — planned 计划</p>\n<p class=\"source-line\">chat — chatted 聊天</p>\n<p class=\"source-line\">skip — skipped 跳绳</p></div></div>\n<div class=\"g\"><div class=\"gt\">含有实义动词的一般过去时的句子</div><div class=\"gb\"><h5>1. 肯定句: 主语+动词过去式(+其他).</h5>\n<p class=\"source-line\">I played the piano yesterday afternoon. 我昨天下午弹钢琴了。</p>\n<p class=\"source-line\">She found a new English book. 她找到了一本新英语书。</p>\n<h5>2. 否定句: 主语 + didn't + 动词原形 (+ 其他).</h5>\n<p class=\"source-line\">I didn't have an English class this morning. 我今天上午没有英语课。</p>\n<p class=\"source-line\">You didn't do your best. 你没有尽力。</p>\n<p class=\"source-line\">含有实义动词的一般过去时的肯定句在变否定句时，在谓语动词前加did not（did not可缩写为didn't），谓语动词变为原形即可。</p>\n<h5>3. 一般疑问句: Did + 主语 + 动词原形 (+ 其他)?</h5>\n<p class=\"source-line\">Did he go there yesterday? 他昨天去那里了吗?</p>\n<p class=\"source-line\">Did you play ping-pong last weekend? 你们上周末打乒乓球了吗?</p>\n<h5>4. 特殊疑问句: 疑问词 + did + 主语 + 动词原形 (+ 其他)?</h5>\n<p class=\"source-line\">（1）针对做了什么提问。</p>\n<p class=\"source-line\">What did you do yesterday? 你昨天做了什么？<br />\nWhat did Mike do last night? 迈克昨晚做了什么？</p>\n<p class=\"source-line\">（2）针对时间提问。</p>\n<p class=\"source-line\">What time did you go to school yesterday?</p>\n<p class=\"source-line\">你昨天几点去上学的？</p>\n<p class=\"source-line\">When did your mother go to work last Monday?</p>\n<p class=\"source-line\">你妈妈上星期一什么时候去上班的？</p>\n<p class=\"source-line\">（3）针对地点提问。</p>\n<p class=\"source-line\">Where did your family live five years ago? 你的家人5年前住在哪里？</p>\n<p class=\"source-line\">Where did he play basketball this morning? 他今天早上在哪里打篮球？</p>\n<p class=\"source-line\">（4）针对方式提问。</p>\n<p class=\"source-line\">How did your mother go to work a week ago? 你妈妈一周前是怎么上班的？</p>\n<p class=\"source-line\">How did he get to the zoo the day before yesterday? 他前天是怎么到动物园的？</p>\n<p class=\"source-line\">（5）针对动词的对象提问。</p>\n<p class=\"source-line\">What did she write? 她写了什么？</p>\n<p class=\"source-line\">What did she tell you? 她告诉了你什么？</p></div></div>\n", "notesHtml": "", "exerciseGroups": [{"title": "【真题锦囊】【成都·锦江区】用所给词的适当形式填空。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 1, "type": "input", "questionHtml": "<p class=\"source-line\">We ____ (enjoy) ourselves at the party last night.</p>", "options": [], "correct": null, "answer": "enjoyed"}, {"number": 2, "type": "input", "questionHtml": "<p class=\"source-line\">____ you ____ (go) to the Great Wall last year?</p>", "options": [], "correct": null, "answer": "Did, go<br>"}, {"number": 3, "type": "input", "questionHtml": "<p class=\"source-line\">What day ____ (be) it yesterday?</p>", "options": [], "correct": null, "answer": "was<br>"}, {"number": 4, "type": "input", "questionHtml": "<p class=\"source-line\">The old man ____ (be) ill and went to see a doctor.</p>", "options": [], "correct": null, "answer": "was<br>"}, {"number": 5, "type": "input", "questionHtml": "<p class=\"source-line\">We ____ (visit) the museum and went home.</p>", "options": [], "correct": null, "answer": "visited"}, {"number": 6, "type": "input", "questionHtml": "<p class=\"source-line\">We ____ (have) a party last night.</p>", "options": [], "correct": null, "answer": "had"}], "questionCount": 6, "hasAnswers": true}, {"title": "【真题锦囊】【昆明·五华区】句型转换。", "questionsHtml": "", "answersHtml": "", "preambleHtml": "", "items": [{"number": 7, "type": "input", "questionHtml": "<p class=\"source-line\">Mary did her homework at home. (改为否定句)</p>", "options": [], "correct": null, "answer": "Mary didn't do her homework at home."}, {"number": 8, "type": "input", "questionHtml": "<p class=\"source-line\">He found some food in the fridge. (改为一般疑问句)</p>", "options": [], "correct": null, "answer": "Did he find any food in the fridge?"}, {"number": 9, "type": "input", "questionHtml": "<p class=\"source-line\">She went to Shanghai <u>last month</u>. (对画线部分提问)</p>", "options": [], "correct": null, "answer": "When did she go to Shanghai?"}, {"number": 10, "type": "input", "questionHtml": "<p class=\"source-line\">There was some orange juice in the cup. (改为一般疑问句)</p>", "options": [], "correct": null, "answer": "Was there any orange juice in the cup?"}], "questionCount": 4, "hasAnswers": true}]}];
(function clientRuntime() {
  const $ = (id) => document.getElementById(id);
  const escapeHtml = (value) =>
    String(value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  const storageKey = "new-concept-grammar-72-v1";
  let curUnit = 1;
  let curSec = DATA[0].id;
  let state = { solved: {}, work: {}, stars: {} };

  try {
    const saved = JSON.parse(localStorage.getItem(storageKey) || "{}");
    state.solved = saved.solved || {};
    state.work = saved.work || {};
    state.stars = saved.stars || {};
  } catch (error) {
    state = { solved: {}, work: {}, stars: {} };
  }

  function saveState() {
    try {
      localStorage.setItem(storageKey, JSON.stringify(state));
    } catch (error) {
      // Local files or privacy settings may block storage; the page still works in-memory.
    }
  }

  function solvedSet(id) {
    return new Set(state.solved[id] || []);
  }

  function setSolved(id, values) {
    state.solved[id] = [...values].sort();
    saveState();
  }

  function totalOf(section) {
    return section.exerciseGroups.reduce(
      (sum, group) => sum + (group.items.length || 1),
      0
    );
  }

  function itemKey(groupIndex, itemIndex) {
    return `${groupIndex}-${itemIndex}`;
  }

  function speak(text) {}

  function buildNav() {
    const units = [...new Set(DATA.map((section) => section.unit))];
    $("units").innerHTML = units
      .map((unit) => {
        const name = DATA.find((section) => section.unit === unit).unitName;
        return `<button class="unit-tab${unit === curUnit ? " on" : ""}" data-u="${unit}">${name}</button>`;
      })
      .join("") + `<button class="unit-tab${curUnit === 'stars' ? " on" : ""}" style="color:#B96A00;background:${curUnit==='stars'?'#FFF3E2':'transparent'};border:1px solid #FFF3E2;margin-left:auto" data-u="stars">⭐ 错题本</button>`;

    $("units")
      .querySelectorAll(".unit-tab")
      .forEach((button) => {
        button.onclick = () => {
          const u = button.dataset.u;
          if (u === "stars") {
            curUnit = "stars";
            if (typeof renderStars === 'function') renderStars();
          } else {
            curUnit = Number(u);
            curSec = DATA.find((section) => section.unit === curUnit).id;
            render();
          }
        };
      });

    const list = DATA.filter((section) => section.unit === curUnit);
    $("chips").innerHTML = list
      .map((section) => {
        const count = solvedSet(section.id).size;
        const done = count >= totalOf(section) && totalOf(section) > 0;
        return `<button class="chip${section.id === curSec ? " on" : ""}" data-s="${section.id}">
          ${section.short}${done ? ' <span class="dot">✓</span>' : ""}
        </button>`;
      })
      .join("");

    $("chips")
      .querySelectorAll(".chip")
      .forEach((button) => {
        button.onclick = () => {
          curSec = button.dataset.s;
          render();
          window.scrollTo({ top: 0, behavior: "smooth" });
        };
      });
  }

  function feedbackHtml(secId, groupIndex, itemIndex) {
    return `<div class="fb" id="feedback-${secId}-${groupIndex}-${itemIndex}"></div>`;
  }

  function practiceItemHtml(section, item, groupIndex, itemIndex) {
    const isStarred = (state.stars[section.id] || []).includes(itemKey(groupIndex, itemIndex));
    const starBtn = `<button class="star-btn${isStarred ? " on" : ""}" type="button" data-star="${section.id}|${itemKey(groupIndex, itemIndex)}" title="收藏本题">⭐</button>`;
    const key = itemKey(groupIndex, itemIndex);
    const done = solvedSet(section.id).has(key);
    const workKey = `${section.id}-${key}`;
    if (item.type === "mcq") {
      const options = item.options
        .map(
          (option, optionIndex) =>
            `<button class="opt" type="button" data-mcq="${section.id}|${groupIndex}-${itemIndex}" data-option="${optionIndex}">
              ${String.fromCharCode(65 + optionIndex)}. ${option}
            </button>`
        )
        .join("");
      return `<div class="q exercise-item${done ? " is-done" : ""}" id="item-${section.id}-${key}">
        <div class="qt"><b>${item.number}.</b> ${starBtn}<div class="question-body">${item.questionHtml}</div></div>
        <div class="opts">${options}</div>
        <div class="group-actions" style="display:flex; justify-content: space-between; align-items: center; width: 100%;">
          ${item.correct === null ? `<button class="btn done-btn${done ? " on" : ""}" type="button" data-manual="${section.id}|${key}">${done ? "✓ 已完成本题" : "标记本题完成"}</button>` : "<div></div>"}
          ${curUnit === 'stars' ? `<button class="btn" type="button" data-star="${section.id}|${key}" style="color:#B96A00; background:#FFF3E2;">🗑️ 移出错题本</button>` : ""}
        </div>
        ${feedbackHtml(section.id, groupIndex, itemIndex)}
      </div>`;
    }

    const answerButtons = item.answer
      ? `<button class="btn p" type="button" data-check="${section.id}|${key}">检查</button>
         <button class="btn s" type="button" data-show="${section.id}|${key}">看答案</button>`
      : `<button class="btn done-btn${done ? " on" : ""}" type="button" data-manual="${section.id}|${key}">
           ${done ? "✓ 已完成本题" : "标记本题完成"}
         </button>
         <button class="btn s" type="button" disabled>原文未列答案</button>`;
    return `<div class="q exercise-item${done ? " is-done" : ""}" id="item-${section.id}-${key}">
      <div class="qt"><b>${item.number}.</b> ${starBtn}<div class="question-body">${item.questionHtml}</div></div>
      <div class="row" style="display:flex; flex-wrap:wrap; gap:8px;">
        <input type="text" class="item-input" id="input-${section.id}-${key}" data-input="${section.id}|${key}"
          value="${escapeHtml(state.work[workKey] || "")}" placeholder="在这里填写答案…" autocomplete="off" spellcheck="false" style="flex:1;">
        ${answerButtons}
        ${curUnit === 'stars' ? `<button class="btn" type="button" data-star="${section.id}|${key}" style="color:#B96A00; background:#FFF3E2;">🗑️ 移出错题本</button>` : ""}
      </div>
      ${feedbackHtml(section.id, groupIndex, itemIndex)}
    </div>`;
  }

  function fallbackGroupHtml(section, group, groupIndex) {
    const key = itemKey(groupIndex, 0);
    const done = solvedSet(section.id).has(key);
    const workKey = `${section.id}-${key}`;
    return `<div class="q exercise-item${done ? " is-done" : ""}" id="item-${section.id}-${key}">
      <div class="source-content">${group.questionsHtml}</div>
      <label class="work-label" for="work-${key}">我的作答（自动保存在本浏览器）</label>
      <textarea class="workpad" id="work-${key}" data-fallback="${key}" placeholder="在这里写下答案、改写后的句子或翻译……">${escapeHtml(
        state.work[workKey] || ""
      )}</textarea>
      <div class="group-actions">
        <button class="btn done-btn${done ? " on" : ""}" type="button" data-manual="${section.id}|${key}">
          ${done ? "✓ 已完成本组" : "标记本组完成"}
        </button>
      </div>
      ${group.hasAnswers ? `<div class="answer-panel source-content"><div class="answer-label">参考答案</div>${group.answersHtml}</div>` : ""}
    </div>`;
  }

  function groupHtml(section, group, groupIndex) {
    const items = group.items.length
      ? group.items
          .map((item, itemIndex) => practiceItemHtml(section, item, groupIndex, itemIndex))
          .join("")
      : fallbackGroupHtml(section, group, groupIndex);
    return `<section class="exercise-section">
      <div class="group-top">
        <div class="group-title">${group.title}</div>
        <span class="count-badge">约 ${group.questionCount} 题</span>
      </div>
      ${group.preambleHtml ? `<div class="source-content">${group.preambleHtml}</div>` : ""}
      ${items}
      ${
        group.hasAnswers
          ? ""
          : ""
      }
    </section>`;
  }

  
  function toggleStar(secId, key) {
    state.stars[secId] = state.stars[secId] || [];
    const stars = new Set(state.stars[secId]);
    if (stars.has(key)) stars.delete(key);
    else stars.add(key);
    state.stars[secId] = [...stars];
    saveState();
    document.querySelectorAll(`[data-star="${secId}|${key}"]`).forEach(btn => {
      btn.classList.toggle("on", stars.has(key));
    });
    if (curUnit === "stars" && !stars.has(key)) {
      renderStars();
    }
  }

  function renderStars() {
    buildNav();
    $("chips").innerHTML = "";
    let html = `<div class="card">
        <h2><span class="em">⭐</span>错题本</h2>
        <p class="lead">您收藏的所有错题和难点。</p>
        <div class="exp-row" style="margin:12px 0 10px;"><b>导出</b>
          <label><input type="checkbox" id="optStarsEx" checked> 错题</label>
          <label><input type="checkbox" id="optStarsAns" checked> 答案</label>
        </div>
        <div style="display:flex; gap:10px;">
          <button class="btn p" id="btnExportStars" type="button">⬇️ 导出错题为 Word</button>
          <button class="btn" id="btnClearStars" type="button" style="color:#d32f2f; background:#ffebee;">🗑️ 清空所有错题</button>
        </div>
      </div>`;
    
    let hasStars = false;
    DATA.forEach(section => {
      const stars = state.stars[section.id] || [];
      if (stars.length === 0) return;
      
      let sectionHtml = `<div class="card"><h3>${section.short} ${section.title}</h3>`;
      let sectionHasItems = false;
      section.exerciseGroups.forEach((group, gIdx) => {
         const starredItems = group.items.filter((item, iIdx) => stars.includes(itemKey(gIdx, iIdx)));
         if (starredItems.length > 0) {
            sectionHasItems = true;
            sectionHtml += `<div class="group-title" style="margin-top:14px;margin-bottom:8px">${group.title}</div>`;
            starredItems.forEach(item => {
               const iIdx = group.items.indexOf(item);
               sectionHtml += practiceItemHtml(section, item, gIdx, iIdx);
            });
         }
      });
      sectionHtml += `</div>`;
      if (sectionHasItems) {
         html += sectionHtml;
         hasStars = true;
      }
    });

    if (!hasStars) {
      html += `<div class="card"><p style="text-align:center;color:#999;padding:40px 0">还没有收藏任何题目哦~</p></div>`;
    }

    $("main").innerHTML = html;
    bindMainEvents();
  }

    function bindMainEvents() {
    const btnResetSection = $("btnResetSection");
    if (btnResetSection) {
       btnResetSection.onclick = () => {
          if (confirm("确定要清空本节所有练习的输入内容和完成状态吗？（错题本收藏不会被清空）")) {
             state.solved[curSec] = [];
             Object.keys(state.work).forEach(key => {
                if (key.startsWith(curSec + "|")) {
                   delete state.work[key];
                }
             });
             saveState();
             render();
          }
       };
    }
    const btnExportStars = $("btnExportStars");
    if (btnExportStars) btnExportStars.onclick = exportStarsDoc;
    const btnClearStars = $("btnClearStars");
    if (btnClearStars) btnClearStars.onclick = () => {
       if (confirm("确定要清空所有错题吗？操作不可恢复。")) {
          state.stars = {};
          saveState();
          renderStars();
       }
    };
    $("main")
      .querySelectorAll(".spk")
      .forEach((button) => (button.onclick = () => {} /* TTS removed */));
    $("main")
      .querySelectorAll("[data-mcq]")
      .forEach((button) => (button.onclick = () => pickMcq(button)));
    $("main")
      .querySelectorAll("[data-check]")
      .forEach((button) => (button.onclick = () => checkInput(button.dataset.check)));
    $("main")
      .querySelectorAll("[data-show]")
      .forEach((button) => (button.onclick = () => showInputAnswer(button.dataset.show)));
    $("main")
      .querySelectorAll("[data-manual]")
      .forEach((button) => (button.onclick = () => toggleManual(button.dataset.manual)));
    $("main")
      .querySelectorAll("[data-star]")
      .forEach((button) => (button.onclick = () => {
         const [secId, key] = button.dataset.star.split("|");
         toggleStar(secId, key);
      }));
    $("main")
      .querySelectorAll("[data-input]")
      .forEach((input) => {
        input.addEventListener("input", () => {
          const [secId, key] = input.dataset.input.split("|");
          state.work[`${secId}-${key}`] = input.value;
          saveState();
        });
        input.addEventListener("keydown", (event) => {
          if (event.key === "Enter") checkInput(input.dataset.input);
        });
      });
  }

  function render() {
    buildNav();
    const section = DATA.find((item) => item.id === curSec) || DATA[0];
    curSec = section.id;
    const totalQuestions = section.exerciseGroups.reduce(
      (sum, group) => sum + (group.questionCount || 0),
      0
    );

    $("main").innerHTML = `
      <div class="card">
        <div class="section-kicker">第${String(section.section).padStart(2, "0")}节 · ${section.lessons}</div>
        <h2><span class="em">📖</span>${section.title}</h2>
        <div class="course-meta">
          <span class="meta-pill">全课共 72 节</span>
          <span class="meta-pill">${section.unitName}</span>
          <span class="meta-pill">语法精讲 + 典型例题</span>
        </div>
        <div class="overview source-content">
          ${section.knowledgeHtml || "<p>本节知识图谱请结合语法讲解学习。</p>"}
        </div>
      </div>

      <div class="card">
        <h2><span class="em">🧩</span>语法要点</h2>
        <p class="lead">按原课程层级重新排版；英文例句可点 🔊 朗读。</p>
        <div class="source-content">${section.grammarHtml}</div>
      </div>

      <div class="card">
        <div style="display:flex; justify-content:space-between; align-items:flex-start;">
          <h2><span class="em">✏️</span>典型例题</h2>
          <button class="btn" id="btnResetSection" type="button" style="color:#d32f2f; background:#ffebee;">🔄 重置本节练习</button>
        </div>
        <p class="lead">共 ${section.exerciseGroups.length} 组、约 ${totalQuestions} 题。先在作答区完成，再展开参考答案核对。</p>
        ${section.exerciseGroups.map((group, index) => groupHtml(section, group, index)).join("")}
        <div id="allDone"></div>
      </div>



      <div class="card">
        <h2><span class="em">📄</span>一键导出 Word</h2>
        <p class="lead">生成 .doc 文件，可用 Word 或 WPS 打开并打印。</p>
        <div class="exp-row"><b>范围</b>
          <label><input type="radio" name="scope" value="sec" checked> 本节</label>
          <label><input type="radio" name="scope" value="unit"> 本单元</label>
          <label><input type="radio" name="scope" value="all"> 全部 72 节</label>
        </div>
        <div class="exp-row"><b>内容</b>
          <label><input type="checkbox" id="optMap" checked> 知识图谱</label>
          <label><input type="checkbox" id="optGram" checked> 语法要点</label>
          <label><input type="checkbox" id="optEx" checked> 练习题</label>
          <label><input type="checkbox" id="optAns" checked> 参考答案</label>

        </div>
        <button class="btn p" id="btnExport" type="button">⬇️ 导出 Word 文档</button>
        <div class="tip">制作纯练习卷时，可只保留“练习题”和“参考答案”。</div>
      </div>`;

    bindMainEvents();
    $("btnExport").onclick = exportDoc;
    updateScore(curSec);
  }

  function getItem(secId, key) {
    const [groupIndex, itemIndex] = key.split("-").map(Number);
    const section = DATA.find((item) => item.id === secId);
    return {
      section,
      groupIndex,
      itemIndex,
      item: section.exerciseGroups[groupIndex].items[itemIndex],
    };
  }

  function markSolved(secId, key) {
    const values = solvedSet(secId);
    values.add(key);
    setSolved(secId, values);
    const item = $(`item-${secId}-${key}`);
    if (item) item.classList.add("is-done");
    updateScore(secId);
    if (curUnit !== "stars") updateCurrentChip(secId);
  }

  function updateCurrentChip(secId) {
    const section = DATA.find((item) => item.id === secId);
    if (!section) return;
    const values = solvedSet(secId);
    const chip = $("chips").querySelector(`.chip[data-s="${section.id}"]`);
    if (chip) {
      const complete = values.size >= totalOf(section) && totalOf(section) > 0;
      chip.innerHTML = `${section.short}${complete ? ' <span class="dot">✓</span>' : ""}`;
    }
  }

  function toggleManual(dataset_manual) {
    const [secId, key] = dataset_manual.split("|");
    const values = solvedSet(secId);
    const done = !values.has(key);
    if (done) values.add(key);
    else values.delete(key);
    setSolved(secId, values);
    const item = $(`item-${secId}-${key}`);
    const button = document.querySelector(`[data-manual="${section.id}|${key}"]`);
    if (item) item.classList.toggle("is-done", done);
    if (button) {
      button.classList.toggle("on", done);
      button.textContent = done ? "✓ 已完成本题" : "标记本题完成";
    }
    updateScore(secId);
    if (curUnit !== "stars") updateCurrentChip(secId);
  }

  function feedback(secId, key, correct, html) {
    const panel = $(`feedback-${secId}-${key}`);
    if (!panel) return;
    panel.className = `fb show ${correct ? "good" : "bad"}`;
    panel.innerHTML = html;
  }

  function pickMcq(button) {
    const [secId, key] = button.dataset.mcq.split("|");
    const { item } = getItem(secId, key);
    const picked = Number(button.dataset.option);
    const box = $(`item-${secId}-${key}`);
    const options = box.querySelectorAll(".opt");

    if (item.correct === null) {
      options.forEach((option) => option.classList.remove("on"));
      button.classList.add("on");
      feedback(secId, key, false, "本题源文件未单列答案，请完成后使用“标记本题完成”。");
      return;
    }

    options.forEach((option, index) => {
      option.disabled = true;
      if (index === item.correct) option.classList.add("ok");
      else if (index === picked) option.classList.add("no");
    });
    const correct = picked === item.correct;
    feedback(
      secId,
      key,
      correct,
      correct
        ? "🎉 答对了！"
        : `再看看～ 正确答案是 <span class="ans">${String.fromCharCode(
            65 + item.correct
          )}. ${item.options[item.correct]}</span>`
    );
    if (correct) {
      markSolved(secId, key);
    } else {
      const stars = new Set(state.stars[secId] || []);
      if (!stars.has(key)) toggleStar(secId, key);
    }
  }

  function normalizeAnswer(value) {
    return String(value || "")
      .toLowerCase()
      .replace(/[‘’]/g, "'")
      .replace(/[“”]/g, '"')
      .replace(/[.,!?;:"()，。！？；：]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  function checkInput(dataset_check) {
    const [secId, key] = dataset_check.split("|");
    const { item } = getItem(secId, key);
    const input = $(`input-${secId}-${key}`);
    const value = input ? input.value : "";
    if (!value.trim()) {
      feedback(key, false, "先填写答案再检查哦～");
      return;
    }
    const correct = normalizeAnswer(value) === normalizeAnswer(item.answer);
    feedback(
      secId,
      key,
      correct,
      correct
        ? "🎉 答对了！"
        : `还差一点，参考答案：<span class="ans">${escapeHtml(item.answer)}</span>`
    );
    if (correct) {
      markSolved(secId, key);
    } else {
      const stars = new Set(state.stars[secId] || []);
      if (!stars.has(key)) toggleStar(secId, key);
    }
  }

  function showInputAnswer(dataset_show) {
    const [secId, key] = dataset_show.split("|");
    const { item } = getItem(secId, key);
    feedback(secId, key, false, `参考答案：<span class="ans">${escapeHtml(item.answer)}</span>`);
  }

  function updateScore(secId) {
    const section = DATA.find((item) => item.id === secId);
    if (!section) return;
    const count = solvedSet(section.id).size;
    const total = totalOf(section);
    const scoreTxt = $("scoreTxt");
    if (!scoreTxt) return;
    scoreTxt.textContent = `本节练习进度 ${count} / ${total} 组`;
    const scoreBar = $("scoreBar");
    if (scoreBar) scoreBar.style.width = `${total ? Math.round((count / total) * 100) : 0}%`;
    const done = $("allDone");
    if (done) {
      done.innerHTML =
        total && count >= total
          ? '<div class="done">🏆 本节练习全部完成！可以进入下一节。</div>'
          : "";
    }
  }

  const WORD_CSS = `@page{size:A4;margin:2cm 1.8cm}
body{font-family:"Microsoft YaHei","PingFang SC",SimSun,sans-serif;font-size:10.5pt;line-height:1.75;color:#111}
h1{font-size:19pt;text-align:center;margin:0 0 4pt}
.head-sub{text-align:center;color:#666;font-size:9.5pt;margin:0 0 18pt}
h2{font-size:15pt;border-bottom:1.5pt solid #4F7DF3;padding-bottom:3pt;margin:20pt 0 4pt;color:#1F3A93}
h3{font-size:12pt;margin:13pt 0 5pt;color:#B45309}
p{margin:3pt 0}.source-heading{font-size:11.5pt;color:#1F3A93}.english-line{font-family:"Times New Roman",serif}
table{border-collapse:collapse;width:100%;margin:5pt 0;font-size:9.5pt}td,th{border:.5pt solid #999;padding:3pt 5pt}
th{background:#EEF2FB}.lesson-figure img{max-width:100%;height:auto}.spk{display:none}
.answer-block{background:#F1FBF4;padding:7pt;margin:5pt 0}.exercise-block{margin:8pt 0 14pt}.blank-token{border-bottom:.75pt solid #444;color:transparent}`;

  function exportClean(html) {
    return html
      .replace(/<button[\s\S]*?<\/button>/g, "")
      .replace(/\sloading="lazy"/g, "")
      .replace(/<figure class="lesson-figure">/g, "<div class=\"lesson-figure\">")
      .replace(/<\/figure>/g, "</div>");
  }

  
  function exportStarsDoc() {
    const includeEx = $("optStarsEx") ? $("optStarsEx").checked : true;
    const includeAns = $("optStarsAns") ? $("optStarsAns").checked : true;
    
    if (!includeEx && !includeAns) {
       alert("请至少选择一项导出内容！");
       return;
    }

    let body = `<h1>错题本聚合练习卷</h1><p class="head-sub">姓名：__________　日期：__________</p>`;
    
    let hasStars = false;
    let questionsHtmlAll = "";
    let answersHtmlAll = "";

    DATA.forEach(section => {
      const stars = state.stars[section.id] || [];
      if (stars.length === 0) return;
      hasStars = true;
      
      let secQHtml = "";
      let secAHtml = "";

      section.exerciseGroups.forEach((group, gIdx) => {
         const starredItems = group.items.filter((item, iIdx) => stars.includes(itemKey(gIdx, iIdx)));
         if (starredItems.length > 0) {
            secQHtml += `<div class="exercise-block"><b>${group.title}</b>`;
            secAHtml += `<div class="answer-block"><b>${group.title}</b><div style="margin-top: 5px;">`;
            
            starredItems.forEach(item => {
               let qHtml = item.questionHtml.replace(/<\/?p[^>]*>/g, "");
               secQHtml += `<div style="margin: 6pt 0;"><b>${item.number}.</b> ${qHtml}`;
               if (item.type === 'mcq') {
                 secQHtml += `<div style="margin-left: 18pt;">${item.options.map((opt, i) => String.fromCharCode(65+i) + '. ' + opt).join('&nbsp;&nbsp;&nbsp;&nbsp;')}</div>`;
               } else {
                 secQHtml += `<div style="margin-top: 4pt;">_________________________________________</div>`;
               }
               secQHtml += `</div>`;
               
               secAHtml += `<span style="margin-right: 15px;"><b>${item.number}.</b> ${item.answer}</span>`;
            });
            secQHtml += `</div>`;
            secAHtml += `</div></div>`;
         }
      });
      if (secQHtml) {
         if (includeEx) {
             questionsHtmlAll += `<h2>第${str_padStart(String(section.section), 2, "0")}节　${section.title}</h2>${secQHtml}`;
         }
         if (includeAns) {
             answersHtmlAll += `<h3>第${str_padStart(String(section.section), 2, "0")}节　${section.title}</h3>${secAHtml}`;
         }
      }
    });

    if (!hasStars) {
       alert("错题本为空，无法导出！");
       return;
    }

    if (includeEx) {
       body += questionsHtmlAll;
    }
    if (includeAns) {
       if (includeEx) body += '<h2 style="page-break-before:always">参考答案</h2>';
       else body += '<h2>参考答案</h2>';
       body += answersHtmlAll;
    }
    
    const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><style>${WORD_CSS}</style></head><body>${body}</body></html>`;
    const blob = new Blob(['\ufeff' + html], { type: "application/msword;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `错题本_新概念语法课.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }

  function str_padStart(str, len, pad) {
     return String(str).padStart(len, pad);
  }

  function exportDoc() {
    const scope = (document.querySelector('input[name="scope"]:checked') || { value: "sec" })
      .value;
    const include = {
      map: $("optMap").checked,
      grammar: $("optGram").checked,
      exercise: $("optEx").checked,
      answers: $("optAns").checked,
    };
    const current = DATA.find((section) => section.id === curSec);
    let sections;
    let name;
    if (scope === "unit") {
      sections = DATA.filter((section) => section.unit === current.unit);
      name = `72节新概念语法课_${current.unitName.replace(" · ", "_")}`;
    } else if (scope === "all") {
      sections = DATA.slice();
      name = "72节新概念语法课_全册";
    } else {
      sections = [current];
      name = `72节新概念语法课_第${String(current.section).padStart(2, "0")}节_${current.title}`;
    }

    let body = `<h1>${name}</h1><p class="head-sub">新概念英语第一册 · 语法知识与典型例题　　姓名：__________　日期：__________</p>`;
    sections.forEach((section) => {
      body += `<h2>第${String(section.section).padStart(2, "0")}节　${section.title}</h2>`;
      body += `<p>${section.lessons}</p>`;
      if (include.map) body += `<h3>知识图谱</h3>${exportClean(section.knowledgeHtml)}`;
      if (include.grammar) body += `<h3>语法要点</h3>${exportClean(section.grammarHtml)}`;
      if (include.exercise) {
        body += "<h3>典型例题</h3>";
        section.exerciseGroups.forEach((group) => {
          let questionsHtml = group.preambleHtml || "";
          group.items.forEach(item => {
            let qHtml = item.questionHtml.replace(/<\/?p[^>]*>/g, "");
            questionsHtml += `<div style="margin: 6pt 0;"><b>${item.number}.</b> ${qHtml}`;
            if (item.type === 'mcq') {
              questionsHtml += `<div style="margin-left: 18pt;">${item.options.map((opt, i) => String.fromCharCode(65+i) + '. ' + opt).join('&nbsp;&nbsp;&nbsp;&nbsp;')}</div>`;
            } else {
              questionsHtml += `<div style="margin-top: 4pt;">_________________________________________</div>`;
            }
            questionsHtml += `</div>`;
          });
          body += `<div class="exercise-block"><b>${group.title}</b>${exportClean(
            questionsHtml
          )}</div>`;
        });
      }

    });

    if (include.answers && include.exercise) {
      body += '<h2 style="page-break-before:always">参考答案</h2>';
      sections.forEach((section) => {
        body += `<h3>第${String(section.section).padStart(2, "0")}节　${section.title}</h3>`;
        section.exerciseGroups.forEach((group) => {
          let answersHtml = "";
          group.items.forEach(item => {
            answersHtml += `<span style="margin-right: 15px;"><b>${item.number}.</b> ${item.answer}</span>`;
          });
          body += `<div class="answer-block"><b>${group.title}</b><div style="margin-top: 5px;">${
            answersHtml
              ? exportClean(answersHtml)
              : "<p>源文件未单列本组答案。</p>"
          }</div></div>`;
        });
      });
    }

    const html =
      "﻿<html xmlns:o='urn:schemas-microsoft-com:office:office' " +
      "xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>" +
      `<head><meta charset="utf-8"><title>${name}</title><style>${WORD_CSS}</style></head><body>${body}</body></html>`;
    const blob = new Blob([html], { type: "application/msword;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `${name.replace(/[\\/:*?"<>|]/g, "")}.doc`;
    document.body.appendChild(anchor);
    anchor.click();
    setTimeout(() => {
      URL.revokeObjectURL(url);
      anchor.remove();
    }, 1500);
    const button = $("btnExport");
    const original = button.textContent;
    button.textContent = "✅ 已导出，去下载文件夹查看";
    setTimeout(() => (button.textContent = original), 2600);
  }

  render();
})();